const Map<String, String> NADI_PREDICTIONS = {
  'sun+moon': 'ஜாதகரின் தந்தையார் சலனப்புத்தி உடையவர்.\n பிரயாணங்களில் விருப்பமுள்ளவர்.\n ஜாதகரின் தந்தையார் தான் பிறந்த இடத்தைவிட்டு குடிபெயர்ந்து வேரொரு இடத்தில் குடியேறுவார்.\n ஜாதகரின் ஒரு மகன் வேறு இடத்தில் குடியேறுவார்.\n ஜாதகரின் தாயார் நிர்வாகத் திறமையுள்ளவர்.\n நம்பிக்கைக்கு உரியவர்.\n இரக்க குணமுடையவர்.\n  கொஞ்சம் ஆணவமும் இருக்கும்.',
  'sun+mars': 'ஜாதகரின் தந்தை ஆணவமிக்கவர்.\n  தான் என்ற கர்வம் உடையவர்.\n அதிகார தோரணையுடன் இருப்பார்.\n சொந்தமாக நிலபுறன் உடையவர்.\n ஜாதகரின் சகோதரன் அரசாங்க ஆதரவு உள்ளவர்.\n யாருக்கும் அடங்கி போமாட்டார்.\n புகழுடையவர்.\n ஜாதகர் பெண்ணானால் கணவர் அரசாங்க ஆதரவு உள்ளவர்.\n புகழுடையவர்.\n நல்ல கௌரவான குடும்பத்தில் பிறந்தவர்.\n ஆனால் முன் கோபக்காரனாகவும், பிடிவாதகாரராகவும் இருப்பார்.',
  'sun+mercury': 'ஜாதகரின் தந்தையார் புத்திசாலியாக இருப்பார்.\n வியாபார நோக்கமுள்ளவர்.\n எப்பொழுதும் சிரித்த முகமாக இருப்பார்.\n சொந்தமாக நிலபுலன்கள் இருக்கும்.\n வாக்கு வன்மை உடையவர்.',
  'sun+jupiter': 'சாதகரின் தந்தையார் நல்ல குணங்களையுடையவர்.\n இரக்க குணமுள்ளவர்.\n கடவுள்பக்தியுள்ளவர்.\n புகழுடையவர்.\n ஜாதகர் புகழுடையவர்.\n தந்தை மீது மிக்க பாசமுள்ளவர்.\n தர்ம குணமுள்ளவர்.\n இறந்தும் இறவா புகழுடையவர்.\n தந்தையுடைய நல்லகுணங்கள் அனைத்தையும் கொண்டிருப்பார்.',
  'sun+venus': 'ஜாதகரின் தந்தையார், செல்வந்தராக இருப்பார்.\n சொந்தமாக வீடு, வாகனங்கள் இருக்கும்.\n பெண்கள் மீது மோகம் கொண்டிருப்பார்.\n ஜாதகரின் மனைவி நிர்வாக திறமையுள்ளவர்.\n ஜாதகருக்கு குழந்தை பிறப்பதில் தடையிருக்கும்.\n சுக்கிலம் நீர்த்து போயிருக்கும்.\n மனைவி இரக்க குணம் உள்ளவர்.\n நம்பிக்கைக்கு உரியவர்.\n கொஞ்சம் ஆணவமும் இருக்கும்.\n ஜாதகரின் சகோதரி நிர்வாக திறமையுள்ளவர்.',
  'sun+saturn': 'ஜாதகருக்கும் அவன் தந்தைக்குமிடையே ஒற்றுமையிருக்காது.\n இருவரும் பிரிந்து இருப்பார்கள் அல்லது காதகரின் தந்தை சிறுவயதிலேயே இறந்து போவார்.\n ஜாதகருக்கு அரசாங்க உத்யோகம் கிடைக்கும்.',
  'sun+rahu': 'தந்தை எப்பொழுதும் நோய்வாய்ப்பட்டு இருப்பார் அல்லது ஏதாவது ஒரு கஷ்டத்திலேயே இருப்பார்.\n தந்தையாருக்கு ஆயுள் குறைவு.\n மகனுக்கு ஆயுள் குறைவு.\n ஜாதகரின் பாட்டனார் புகமுடையவர்.\n ஜாதகர்கண்நோய் உள்ளவர்.',
  'sun+ketu': 'இது தெய்வத்தினால் உண்டான சாபம்.\n தந்தையார் ஆன்மீகத்தில் ஈடுபாடு உள்ளவர்.\n  சதா நோய் வாய்ப்பட்டிருப்பார்.\n ஜாதகருக்கு குழந்தை பிறப்பதில் தடை உண்டு.',
  'sun+moon+mars': 'சாதகருக்கு மனசஞ்சலம் இருக்கும்.\n பிரயாணம் செய்வதில் விருப்பம் உள்ளவராக இருப்பார்.\n ஜாதகரின் தாய் முன்கோபியாக இருப்பார்.\n ஜாதகரின் தாய் உஷ்ணம் சம்பந்தப்பட்ட வியாதி உடையவராக இருப்பார்.\n தாய் ஆதிக்க எண்ணமுடையவராக இருப்பார்.\n தாய் நிர்வாக திறமையுள்ளவராக இருப்பார்.',
  'sun+moon+mercury': 'நீண்ட தூர பிரயாணங்கள் செய்வார்.\n ஜாதகருக்கு தோல் சம்மந்தப்பட்ட வியாதியிருக்கும்.\n  தொண்டையிலும் சிறுகோளாறுகள் இருக்கும்.\n  ஜாதகருக்கு காம உணர்வு அதிகமாக இருக்கும்.\n தாயார் நல்ல குணமுள்ளவளாகவும் அறிவாளியாகவும் இருப்பார்.\n தாய் நிர்வாக திறமையுள்ளவராக இருப்பார்.',
  'sun+moon+jupiter': 'ஜாதகர் அழகிய ஒளிசிந்தும் பிரகாசமான கண்களை பெற்றிருப்பார்.\n ஜாதகர் தொண்டுள்ளம் கொண்டவராக இருப்பார்.\n தந்தை புகழ்பெற்றவராக இருப்பார்.\n தந்தை நல்ல ஒழுக்கமுள்ளவராகவும் நேர்மையானவராகவும், தெய்வபக்தி உள்ளவராகவும் இருப்பார்.\n தந்தை ஆசார அனுஷ்டானங்களை அனுசரிப்பவராக இருப்பார்.\n தந்தை சாந்த குணமுள்ளவர்.\n ஜாதகரின் தாய் நிர்வாக திறமையுள்ளவர்.\n ஜாதகரின் தாய் தர்ம குணமுள்ளவராக இருப்பார்.',
  'sun+moon+venus': 'ஜாதகர் பெற்றோர்களிடம் கருத்து வேறுபாடு கொண்டிருப்பார்.\n பெற்றோர்களின் தலையீடுகளால் ஜாதகருக்கு உத்யோகத்தில் தடை, முன்னேற முடியாத நிலைமை உண்டாகும்.\n ஜாதகர் தாய் தந்தையரை பிரிந்திருப்பார்.\n ஜாதகர் கண்பார்வையில் குறையுள்ளவர்.\n தந்தையார் தொழில், உத்யோகம் சம்மந்தமாக அலைந்து கொண்டேயிருப்பார் அல்லது அடிக்கடி இடமாற்றம். தொழில் மாற்றம் செய்ய வேண்டிய நிலையில் இருப்பார்.\n ஜாதகரின் தாய் பிணியுள்ளவராகவும், சோம்பேறியாகவும் இருப்பார்.',
  'sun+moon+rahu': 'ஜாதகருக்கு கண்பார்வையில் குறையிருக்கும்.\n தந்தைக்கு எப்பொழுதும் பயம், மனக்கலக்கம் போன்றவை இருக்கும்.\n தாய் தந்தையருக்கு பிணி, கஷ்டங்கள், மந்திரவாதிகளால் தொல்லை ஏற்படும்.\n தாய் தந்தையின் ஆயுள் மிகவும் குறைவு.\n ஜாதகரின் தந்தை பிற தேசங்களுக்கு போய் வருவார்.\n ஜாதகர் புத்ர தோஷமுள்ளவர்.\n ஆயுள் குறைவான குழந்தைகளைப் பெறுவார்.',
  'sun+moon+ketu': 'குடும்ப உறுப்பினர்கள் எப்பொழுதும் தெய்வ வழிபாட்டில் ஈடுபட்டிருப்பார்கள்.\n ஆனால் இவர்கள் கஷ்டம் எளிதில் தீராது.\n குடும்பத்தில் எப்பொழுதும் கஷ்டமிருக்கும்.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு. கண் நோயும் இருக்கும்.',
  'sun+mars+moon': 'ஜாதகரின் சகோதரன் வேறு இடத்தில் குடியேறுவார்.\n ஜாதகர் பெண்ணானால் கணவன் அடிக்கடி பிரயாணம் செய்பவராக இருப்பார்.\n ஜாதகரின் தந்தை சற்று முன்கோபியாக இருப்பார்.\n மனசஞ்சலம் உடையவராக இருப்பார்.\n ஜாதகர் நிர்வாக திறமையுள்ளவர்.\n வரன் சொந்தத்தில் அமையாது.',
  'sun+mars+mercury': 'சகோதரர்களுக்கிடையே ஒற்றுமையிருக்காது. நண்பர்களுடனும் தொழில் முறை கூட்டாளிகளுடனும் கருத்து வேறுபாடு கொண்டிருப்பார். ஜாதகரின் தந்தை முன்கோபியாக இருப்பார். நிலபுலங்களுக்கு சொந்தக்காரராக இருப்பார். ஜாதகருக்கு கல்வியில் தடையுண்டு.',
  'sun+mars+jupiter': 'ஜாதகர் முன்கோபியாக இருப்பார்.\n ஜாதகருக்கு அதிக ரத்த அழுத்தம், இதய நோய், ஆண்மை குறைவு போன்ற நோய்கள் வரும்.\n ஜாதகரின் தந்தை முன்கோபியாக இருந்தாலும் நேர்மையானவராக இருப்பார்.\n உடம்பில் அதிக உஷ்ணம் இருக்கும்.\n ஜாதகருக்கு புருவங்கள் அழகாக இருக்கும்.\n பற்களும் பார்ப்பதற்கு அழகாக இருக்கும்.\n ஜாதகர் உரத்த குரலில் பேசுவார்.\n சிறு விஷயங்களுக்கும் சண்டை போடுவார்.\n பிடிவாதமும், வைராக்யமும் இருக்கும்.\n ஜாதகருக்கு ஆதிக்க உணர்வு அதிகமாக இருக்கும்.',
  'sun+mars+venus': 'சகோதரர்களுக்கு கஷ்டம், ஆயுள் குறைவு.\n ஜாதகரின் தந்தை ஆதிக்க உணர்வு உள்ளவராகவும், செல்வந்தராகவும் இருப்பார்.\n மனைவி மற்றும் மகளுக்கு உஷ்ணம் சம்பந்தமான பிணி இருக்கும்.ஜாதகருக்கு பற்கள் கவர்ச்சியாக இருக்கும்.\n ஜாதகர் ஆண்மை குறைவுள்ளவர்.\n புத்திர தோஷம் உண்டு.\n ஜாதகர் பெண்ணானால் கணவர் செல்வாக்கான குடும்பத்திலிருந்து வருவார்.',
  'sun+mars+saturn': 'ஜாதகரின் தகப்பனார் முன்கோபி.\n தகப்பனாருக்கு எதிரிகளால் தொல்லை.\n ஜாதகருக்கும் தொழில் அல்லது உத்யோகத்தில் தொல்லைகள் உண்பாகும்.\n ஜாதகர் பல்லில் ரோகமுடையவர்.\n வயிற்றில் புண்ணுடையவர்.\n ஜாதகருக்கு தாமதமாக திருமணம் நடைபெறும்.\n ஜாதகரின் குடும்பத்தில் ஒற்றுமை இருக்காது.\n ஜாதகருக்கு உடம்பில் வெட்டுக்காயம், தழும்பு போன்றவை இருக்கும்.\n குழந்தைதாமதமாக பிறக்கும்.',
  'sun+mars+rahu': 'ஜாதகருக்கு விபத்துக்கள், காயங்கள் ஏற்படும்.\n ஜாதகரின் தந்தை மற்றும் சகோதரர்களுக்கு கண்டங்கள் அல்லது கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n குழந்தைகளுக்கு நோய்கள் உண்டாகும்.',
  'sun+mars+ketu': 'சகோதரர்களிடையே சண்டை சச்சரவு ஏற்படும்.\n ஜாதகருக்கு உஷ்ணம் சம்பந்தமான வியாதிகள் வரும்.\n மூல வியாதி, ரத்த ஓட்டத்தில் தடை, புற்றுநோய் போன்றவைகள் தோன்றும்.\n ஜாதகரின் தந்தை விரக்தி மனப்பான்மை உள்ளவராக இருப்பார்.',
  'sun+mercury+moon': 'தந்தை புத்திசாலியாக இருப்பார். தந்திரசாலியாக இருப்பார்.\n ஜாதகருக்கு தொண்டையில் புண் மற்றும் தோல் சம்பந்தமான வியாதி வரும்.\n ஜாதகரின் தந்தை அறிவாளியாக இருப்பார்.\n தந்தைக்கு பெண்களால் அவமானம் ஏற்படும்.\n ஜாதகர் கலை சம்பந்தமான கல்வியை கற்பார்.\n தந்தைக்கு காம உணர்வு அதிகம்.',
  'sun+mercury+mars': 'ஜாதகரின் சகோதரர்களிடையே ஒற்றுமை இருக்காது.\n ஜாதகருக்கு கல்வியில் தடை ஏற்படும்.\n ஜாதகர் எந்திரங்கள் சம்பந்தமாக கல்வியை கற்பார்.\n ஜாதகரின் தந்தை புத்திசாலி.\n எப்பொழுதும் ஏதாவது பேசிக்கொண்டே இருப்பார்.\n நிலம் பூமிகளுக்கு சொந்தக்காரராக இருப்பார்.\n ஜாதகருக்கு நெற்றியில் ஒரு தழும்பு இருக்கும்.\n பற்கள் சொத்தையாக இருக்கும்.',
  'sun+mercury+jupiter': 'தந்தை  தர்ம சிந்தனை உள்ளவராக இருப்பார்.\n தந்தை தொண்டுகள் செய்வதில் ஈடுபட்டிருப்பார்.\n தகப்பன் மீது மிகுந்த பற்று பாசம் வைத்திருப்பார்.\n ஜாதகரின் கண்கள் கவர்ச்சியாகவும் ஒளி சிந்துவதாகவும் இருக்கும்.\n ஜாதகனுக்கு சிறப்பான கல்வி யோகம் உண்டு, கௌரவமான உத்யோகம் செய்பவராக இருப்பார்.\n ஜாதகர் நல்ல பண்புள்ள குழந்தைகளைப் பெறுவார். அவர்கள் கல்வி கேள்விகளில் சிறந்த புகழுடன் விளங்குவார்கள்.\n ஜாதகர் நல்ல பேச்சாளராகவும், எழுத்தாளர்களாகவும் புகழ்பெற்று விளங்குவார். எல்லா நல்ல குணங்களும் இருக்கும்.\n  தலையில் வழுக்கை இருக்கும். எல்லோரையும் கவரும் வசீகரத் தன்மை பெற்றிருப்பார்.\n ஜாதகரின் தந்தை படித்தவராகவும், பண்பாராகவும் இருப்பார்.',
  'sun+mercury+venus': 'ஜாதகருக்கு சிறப்பான கல்வி யோகம் உண்டு.\n ஜாதகர் தந்தை படித்தவராகவும், செல்வந்தராகவும் இருப்பார்.\n மேலும் தந்தைக்கு கலைகளில் நாட்டம் இருக்கும்.\n நிலபுலன்கள் எல்லாம் இருக்கும். வியாபார நோக்கமுள்ளவராகவும் இருப்பார்.',
  'sun+mercury+saturn': 'ஜாதகர் கண்ணில் நோய் உள்ளவர்.\n ஜாதகரின் தந்தை படித்தவராகவும், தொழில் நுட்பம் அறிந்தவராகவும் இருப்பார்.\n ஜாதகரின் தந்தை சொந்தமாக வியாபாரம் செய்பவராக இருப்பார்.',
  'sun+mercury+rahu': 'ஜாதகரின் தந்தை பெரிய அளவில் வியாபாரம் அல்லது தொழில் செய்பவராக இருப்பார்.\n தந்தைக்கு கல்வியில் தடை உண்டாகும்.\n ஜாதகருக்கு கண் மற்றும் தோல் சம்பந்தமான வியாதி உண்பாகும்.\n தந்தைக்கும், ஜாதகரின் இளைய சகோதரர்களுக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் மந்த புத்தியுள்ளவராக இருப்பார்.',
  'sun+mercury+ketu': 'ஜாதகர் சுருண்ட முடியைப்பெற்றிருப்பார். அழகான மீசை இருக்கும்.\n தந்தை காதல் விவகாரத்தில் ஈடுபட்டு, அதில் சண்டை சச்சரவு ஏற்படும்.\n பெண்களுக்கு சுருண்ட அல்லது நீண்ட கூந்தல் இருக்கும்.\n தகப்பனாரின் சொத்துக்கள் தகராறில் இருக்கும்.\n ஜாதகருக்கு கண் மற்றும் தோல் சம்பந்தமான நோய் இருக்கும்.',
  'sun+jupiter+moon': 'தந்தை கௌரவமான குடும்பத்தில் பிறந்தவர்.\n தந்தை தொண்டுள்ளம் கொண்டவர். தான தர்மங்கள் செய்வார்.\n ஜாதகரின் பெற்றோர் நல்லவர்களாகவும், பண்புள்ளவர்களாகவும் இருப்பார். தர்ம சிந்தனையுள்ளவர்கள். தெய்வ பக்தியுள்ளவர்கள்.\n ஜாதகர் மிகவும் அதிர்ஷ்டம் உள்ளவர். ஜாதகருக்கு ஆன்மீகத்தில் நாட்டமிருக்கும்.\n புகழுடையவர். பெற்றோரிடம் மிகுந்தபற்று வைத்திருப்பார்.\n ஜாதகர் நிர்வாகத் திறமையுள்ளவராக இருப்பார். பெரிய மனிதர்களின் தொடர்பு இருக்கும்.\n ஜாதகர் வாழ்க்கையில் உயர்ந்த அந்தஸ்தைப் பெறுவார். ஆன்மீகத்தில் ஈடுபாடு இருக்கும். பிரயாணங்கள் செய்வதில் விருப்பமிருக்கும்.\n ஜாதகர் அழகான கண்களைப் பெற்றிருப்பார்.',
  'sun+jupiter+mars': 'ஜாதகரின் தந்தை நல்ல குணமுடையவர். சற்று முன்கோபியாக இருப்பார்.\n ஜாதகருக்கு உடம்பில் உஷ்ணம் அதிகமாக இருக்கும். அதிக இரத்த அழுத்தம். இதயநோய் போன்றவைகள் ஏற்படும்.\n ஜாதகர் அழகான உடலமைப்பு கண்கள் மற்றும் பற்களைப் பெற்றிருப்பார்.\n தந்தை முன்கோபியாக இருந்தாலும் நல்லவராக இருப்பார். அதிகார ஆதிக்க உணர்வு அதிகமாக இருக்கும். யாருக்கும் அடிபணியமாட்டார்.\n தந்தை விடாமுயற்சியும் வீரமும் உடையவர். அரசியல் ஈடுபாடு இருக்கும் அல்லது அதிகாரப் பதவியிலிருப்பார்.',
  'sun+jupiter+mercury': 'ஜாதகர் அதிர்ஷ்டசாலியாக இருப்பார்.\n தந்தை புகழுடையவர்.\n ஜாதகர் அறிவாளியாக இருப்பார். அழகானவர். வாக்குவன்மை உள்ளவர். நிர்வாகத் திறமையுள்ளவர்.\n ஜாதகரின் தந்தை பண்பாளராகவும், படித்தவராகவும் இருப்பார்.\n ஜாதகர் பண்புள்ள குழந்தைகளைப் பெறுவார். அவர்கள் கல்வி கேள்விகளில் சிறந்து விளங்குவார்கள்.\n ஜாதகர் மிகவும் புகழ்பெற்றவராவர். தன்பேச்சு திறமையால் எல்லோரையும் கவர்வார்.\n தந்தை சமுதாய தொண்டில் ஈடுபடுவார். தானதர்மங்கள் செய்வார். அதிகார பதவியைப் பெறுவார். அரசியலில் ஈடுபடுவார்.\n தந்தை சமுதாயத்தில் ஒரு தலைவனாக உருவெடுப்பார். தெய்வ அருள் பெற்றவர்.',
  'sun+jupiter+venus': 'ஜாதகரின் தந்தை நல்ல பண்பாளராகவும், செல்வந்தராகவும் இருப்பார்.\n ஜாதகருக்கு அழகான கண்கள், கன்னம் இருக்கும்.\n ஜாதகருக்கு மூக்கு கவர்ச்சியாக இருக்கும்.\n ஜாதகர் புகழ் பெற்றவராவர். செல்வந்தராவர். வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.\n ஜாதகருக்கு நல்ல பண்புள்ள குழந்தைகள் பிறக்கும். அவர்கள் பிற்காலத்தில் செல்வந்தராவார்கள்.\n தந்தைக்கு கலைத்துறையில் நாட்டமிருக்கும். ஆடம்பரப் பிரியன். பெண்கள் மீது மோகமுள்ளவர்.',
  'sun+jupiter+saturn': 'ஜாதகரின் தந்தை கௌரவமான உத்யோகம் செய்பவராக இருப்பார். மிக உயர்ந்த பதவிகளை வகிப்பவராக இருப்பார்.\n ஜாதகரும் தன் உத்யோகத்தில் உயர்ந்த நிலையை அடைவார். பேரும் புகழும் பெறுவார்.',
  'sun+jupiter+rahu': 'ஜாதகரின் தந்தை தெய்வ பக்தியுள்ளவர். நல்ல பண்பாளர்.\n தந்தைக்கு மற்றும் ஜாதகருக்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும். வாகன விபத்துக்கள், உயரமான இடத்திலிருந்து விழுதல் போன்ற ஆபத்துக்கள் ஏற்படும்.\n ஜாதகர் பெரிய விகாரமான மூக்கை பெற்றிருப்பார். அலட்சியப்போக்கு உடையவர்.',
  'sun+jupiter+ketu': 'ஜாதகரின் தந்தை தெய்வபக்தி உள்ளவர். புகழ்பெற்ற மனிதர், அரசியல் ஈடுபாடு உள்ளவர்.\n ஜாதகருக்கு உஷ்ணம் சம்பந்தமான வியாதிகள் தோன்றும். மூல வியாதி, புற்றுநோய் போன்றவை தோன்றும்.\n ஜாதகர் விரக்தி மனப்பான்மை உள்ளவராக இருப்பார். எதிலும் ஒரு பிடிப்பு இருக்காது. ஆன்மீகத்தில் நாட்டமுள்ளவராக இருப்பார்.',
  'sun+venus+moon': 'ஜாதகரின் தந்தைக்கு பணக்கஷ்டம், பணவிரையம் ஏற்படும். பெண்கள் மீது மோகமுள்ளவராக இருப்பார்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஜாதகரின் மனைவி நோயாளியாக இருப்பார். அழகானவராகவும், கர்பப்பையில் கோளாறும் இருக்கும்.\n தந்தைக்கு காம உணர்வு அதிகமாக இருக்கும்.\n வயிற்றில் பிணி உள்ளவராக இருப்பார்.',
  'sun+venus+mars': 'ஜாதகரின் மனைவி மற்றும் சகோதரிக்கு உஷ்ணம் சம்பந்தமான வியாதிகள் இருக்கும்.\n ஜாதகரின் மனைவி நிர்வாக திறமையுள்ளவராகவும், ஆதிக்க எண்ணம் உடையவராகவும் இருப்பார்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஆண்மை குறைவுள்ளவராக இருப்பார்.\n ஜாதகரின் தந்தை செல்வந்தராகவும் இருப்பார்.',
  'sun+venus+mercury': 'ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n மனைவி படித்தவராக இருப்பார். தந்தை செல்வந்தராகவும், செல்வாக்கு உள்ளவராகவும் இருப்பார்.\n தந்தை பெண்கள் மீது மோகமுள்ளவராக இருப்பார்.\n தந்தைக்கு சொந்த வீடு நிலபுலன்கள் எல்லாம் இருக்கும்.',
  'sun+venus+jupiter': 'தந்தை சமுதாயத்தில் செல்வந்தராகவும் மதிப்பு மரியாதையுடன் நீடித்து வாழ்வார்.\n தந்தை அழகான முகத்தோற்றம் உடையவர் பெரிய நிதி நிறுவனங்களை நடத்துவார்.',
  'sun+venus+saturn': 'ஜாதகரின் தந்தை செல்வந்தராகவும், சொந்த வியாபாரம் செய்பவராகவும் இருப்பார்.\n ஜாதகரின் மனைவி உத்யோகத்தில் இருப்பார்.\n ஜாதகருக்கு மனைவியால் யோகம் வரும்.',
  'sun+venus+rahu': 'ஜாதகரின் தந்தை செல்வந்தராவார்.\n ஜாதகர் புத்ரதோஷமுள்ளவர்.\n தந்தை மற்றும் மனைவிக்கு பிணி, கஷ்டங்கள் ஏற்படும்.',
  'sun+venus+ketu': 'ஜாதகரின் சகோதரிகளுக்கு திருமணம் ஏற்படுவதில் தடை உண்டு.\n மனைவியுடன் கருத்து வேறுபாடு ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம், பணம் நஷ்டம், பொருளாதார தடைகள் ஏற்படும்.\n ஜாதகரின் மனைவிக்கு கர்பப்பையில் கோளாறு உண்டு.',
  'sun+saturn+moon': 'ஜாதகரின் பெற்றோரே அவன் உயர்வதற்கு தடையாக இருப்பார்கள்.\n ஜாதகருக்கும் அவர் பெற்றோருக்குமிடையே கருத்து வேறுபாடு இருக்கும்.\n ஜாதகருக்கு தொழில் அல்லது உத்யோகத்தில் தொல்லைகள் ஏற்படும்.\n வீண்பழி, அபராதம் ஏற்படும்.\n ஜாதகருக்கு அடிக்கடி இடமாற்றம் தொழில்மாற்றம் ஏற்படும்.',
  'sun+saturn+mars': 'ஜாதகருக்கு உத்யோகம் மற்றும் தொழில் ரீதியாக தொல்லைகள் இருக்கும்.\n தந்தைக்கு எதிரிகள் தொல்லை ஏற்படும்.\n ஜாதகர் பல்லில் ரோகமுள்ளவர்.\n ஜாதகருக்கு சரியான உத்யோகம், தகுதிக்கு தகுந்த தொழில் கிடைக்காது.\n ஜாதகருக்கு உயர் அதிகாரிகள் எப்பொழுதும் தொல்லை கொடுத்துக் கொண்டே இருப்பார்கள்.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.',
  'sun+saturn+mercury': 'ஜாதகர் அரசாங்க உத்யோகம் செய்பவராக இருப்பார்.\n தந்தைக்கு கணக்கர், சட்டம், எழுத்துத்துறை போன்றவற்றில் தொழில் அமையும்.\n தந்தை அச்சிடும் தொழிலும் செய்யலாம்.\n ஜாதகருக்கு அரசியலில் ஈடுபாடு இருக்கும்.',
  'sun+saturn+jupiter': 'தந்தை கௌரவமான இடத்தில் பணிபுரிவார்.\n தந்தைக்கு காலதாமதமான முன்னேற்றத்தை தரும்.',
  'sun+saturn+venus': 'தந்தை வாழ்க்கையில் எல்லா சுகபோகங்களையும் அனுபவிப்பார்.\n ஜாதகருக்கும் அவர் தந்தைக்குமிடையே ஒற்றுமையிருக்காது.\n தந்தை செல்வந்தர். பண புழக்கமுள்ளவர்.\n தந்தை வங்கியில் பணி, வட்டித்தொழில் செய்வார்.\n தந்தைக்கு சொந்தவீடு, வாகனங்கள் உண்டு.',
  'sun+saturn+rahu': 'தந்தை மகனுக்கு இடையே ஒற்றுமை இருக்காது.\n ஜாதகருக்கு கை, கால், மூட்டுகளில் வலி இருக்கும்.\n ஜாதகரின் தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷமுண்டு.\n தந்தை கடினமாக உழைக்க வேண்டிய நிலை ஏற்படும். யாருடைய உதவியும் இருக்காது.\n ஜாதகருக்கு அரசு மற்றும் அரசாங்க அதிகாரிகளால் தொல்லை ஏற்படும்.',
  'sun+saturn+ketu': 'தந்தைக்கும் மகனுக்கும் இடையே சண்டை சச்சரவு,\n தந்தைக்கு தொழில் முடக்கம். உத்யோக தடை.\n ஜாதகருக்கு அரசியல்வாதிமற்றும் பதவியில் இருப்பவர்களால் தொல்லை ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு',
  'sun+rahu+moon': 'தாய் தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு. கண்ரோகமும் வரும்.\n ஜாதகருக்கு அற்ப ஆயுள் உள்ள புத்திரர்கள் பிறப்பார்கள்.',
  'sun+rahu+mars': 'தந்தை மற்றும் சகோதரர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கும் கண்டங்கள் ஏற்படும். புத்ரதோஷம் உண்டு\n அற்ப ஆயுள் புத்திரர்கள் பிறப்பார்கள். ஜாதகர் பெண்ணானால் கணவனுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு கண்ரோகமுண்டு. குஷ்ட ரோகம் வரும்.',
  'sun+rahu+mercury': 'ஜாதகரின் தந்தைக்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு. கல்வியில் தடை ஏற்படும்.\n தந்தைக்கு கண் ரோகம், தோல் வியாதி வரும்.',
  'sun+rahu+jupiter': 'ஜாதகருக்கும் தந்தைக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n புத்ரதோஷம் உண்டு. கண் ரோகம் வரும்.\n ஜாதகரின் தாத்தா புகழ்பெற்றவர்.\n தந்தை தெய்வபக்தி உள்ளவர்.',
  'sun+rahu+venus': 'தாத்தா செல்வந்தராகவும். அற்ப புத்திரர்களைக் கொண்டவராகவும் இருப்பார்.\n ஜாதகரின் தந்தை, மனைவி மற்றும் சகோதரிக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n புத்ரதோஷம் உண்டு.',
  'sun+rahu+saturn': 'ஜாதகருக்கும் தந்தைக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n தந்தைக்கும் ஜாதகருக்கும் இடையே ஒற்றுமை இருக்காது.\n புத்ரதோஷம் உண்டு. கண்நோய் தோன்றும்.',
  'sun+rahu+ketu': 'ஜாதகரின் தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'sun+ketu+moon': 'பெற்றோர் தெய்வ நம்பிக்கை உள்ளவர்களாக இருப்பார்கள்.\n ஜாதகரின் தாய் தந்தையரிடையே ஒற்றுமை இருக்காது.\n ஜாதகர் கண்ணில் ரோகமுள்ளவர். புத்ரதோஷமுள்ளவர்.',
  'sun+ketu+mars': 'தந்தைக்கு விபத்து கண்டம்.\n ஜாதகரின் இரத்த சம்மந்தமான உறவினர்களுடன் சுமுகமான உறவு இருக்காது.\n சண்டை சச்சரவுகள் தோன்றும்.',
  'sun+ketu+mercury': 'ஜாதகர் காதல் விவகாரத்தில் ஈடுபட்டு தகராறு வரும்.\n ஜாதகரின் தந்தை நண்பர்களுடன் கருத்து வேறுபாடுகொண்டிருப்பார்.\n தந்தைக்கு நிலம் சம்மந்தமான வகையில் வழக்கு தகராறு இருக்கும்.',
  'sun+ketu+jupiter': 'தந்தைக்கு உயர்ந்த ஆன்மீக சிந்தனை உண்டு.\n தந்தை மகான் என்று பெயரெடுப்பார்.',
  'sun+ketu+venus': 'தந்தைக்கு மனைவி வகையில் கருத்து வேறுபாடு பிரிவினைகள் தோன்றும்.\n ஜாதகரின் பூர்வீகச் சொத்து சம்பந்தமானவகையில் வழக்கு தகராறு இருக்கும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு',
  'sun+ketu+saturn': 'ஜாதகருக்கும் தந்தைக்குமிடையே சண்டை சச்சரவு, தொழில் முடக்கம் உண்டு.\n ஜாதகருக்கு உத்யோகத்தில் தடை அரசியல்வாதி மற்றும்பதவியில் இருப்பவர்களால் தொல்லை ஏற்படும்.\n தந்தைக்கு கண்டம்\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.',
  'sun+ketu+rahu': 'ஜாதகரின் தந்தைக்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n தந்தைக்கு அற்ப ஆயுள்.',
  'moon+sun': 'ஜாதகரின் தாயார் ஆதிக்கக்குணம் மிக்கவர்.\n அரசாங்கத்தில் செல்வாக்கு உடையவர், நிர்வாக திறமை உள்ளவர்.\n இரக்க குணம் உடையவர்.',
  'moon+mars': 'ஜாதகரின் தாயார் ஆணவமிக்கவர்.\n ஜாதகரின் சகோதரன் பிறந்த இடத்தை விட்டு குடிபெயர்ந்து வேறொரு இடத்தில் குடியேறுவார்.\n ஜாதகர் பெண்ணானால் கணவர் சதா பிரயாணத்திலேயே இருப்பார் அல்லது கணவர் வேறு ஊரிலோ, வேறு நாட்டிலோ இருப்பார்.\n ஜாதகருக்கு மனநிம்மதி இருக்காது.',
  'moon+mercury': 'ஜாதகர் வாக்கு வன்மையுடையவர்.\n ஜாதகர் தோல் வியாதி உடையவர்.\n காமம் அதிகமுள்ளவர்.\n புத்திசாலியாக இருப்பார்.\n நீண்ட தூர பயணங்கள் செல்வார்.\n ஜாதகரின் தாயார் புத்தி கூர்மையுடையவர்.\n வயிற்றில் பிணி உள்ளவர்.\n தொண்டையில் வியாதி உள்ளவர்.',
  'moon+jupiter': 'ஜாதகரின் தாயார் நல்ல குணமுடையர்.\n தெய்வபக்தி உடையவர்.\n ஜாதகர் சலனபுத்தி உடையவர்.\n தர்மகுணமுள்ளவர்.\n தீர்த்த யாத்திரைகள் செய்வார்.\n புகழுடையவர்.',
  'moon+venus': 'ஜாதகரின் தாயார் அழகானவர்.\n செல்வ செழிப்புள்ளவர்.\n ஸ்திரி போல வசீகரமாக இருப்பார்.\n ஜாதகரின் மனைவி மிகவும் அழகாக இருப்பார்.\n கலைத்துறையில் நாட்டமுள்ளவர்.\n சலன புத்தியுடையவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கருப்பையில் கோளாறு இருக்கும்.\n மாதவிடாய் நேரத்தில் தொல்லைகள், கருச்சிதைவு போன்றவை ஏற்படும்.\n ஜாதகருடைய மனைவி தூரதேசத்திலிருந்து வருவார்.',
  'moon+saturn': 'ஜாதகரின் தாயார் சோம்பேறியாக இருப்பார்.\n மந்தபுத்தியுடையவராக இருப்பார்.\n ஜாதகரும் மந்த புத்தியுடையவனாக இருப்பார்.\n ஜாதகர் சதா அலைந்து கொண்டே இருப்பார்.\n உத்யோகம் அல்லது தொழில் தேடி வேறு ஊருக்கு போவார்.\n ஜாதகர் வயிற்றில் பிணியுள்ளவர்.',
  'moon+rahu': 'ஜாதகருக்கு நீரில் கண்டமுண்டு.\n மனதில் இனம்புரியாத பயம் இருக்கும்.\n மனநோயாளியாகும் சந்தர்ப்பம் வரலாம்.\n ஜாதகர் வயிற்றில் பிணி உள்ளவர்.\n ஜாதகரின் தாயாருக்கு ஆயுள் குறைவு அல்லது எப்பொழுதும் ஏதாவது ஒரு கஷ்டத்திலிருப்பார் அல்லது நோய்வாய்ப்பட்டிருப்பார்.\n தந்தைவழிபாட்டன் வேறு இடத்திலிருந்து வந்து தற்போது இருக்கும் இடத்தில் குடியேறியவர்.',
  'moon+ketu': 'ஜாதகரின் தாயாருக்கு ஆன்மீகத்தில் ஈடுபாடு உண்டு.\n தாயார் தர்மகுணமுள்ளவராக இருப்பார்.\n எப்பொழுதும் நோய்வாய்ப்பட்டிருப்பார்.\n வயிற்றில் பிணியுள்ளவர்.\n சுவாச வழி பிணி உண்டு.',
  'moon+sun+mars': 'ஜாதகரின் தாய் நிர்வாக திறமையுள்ளவராகவும், முன்கோபியாகவும் ஆதிக்க எண்ணமுள்ளவராகவும் இருப்பார்.\n ஜாதகருக்கு மனகலக்கம், பெற்றோர்களின் தலையீடுகளால் நிம்மதி இருக்காது.\n தாய்க்கு உஷ்ணம் சம்பந்தமானபிணி இருக்கும்.',
  'moon+sun+mercury': 'ஜாதகர் மற்றும் தந்தையினுடைய அதிபுத்திசாலிதனத்தால் ஜாதகருக்கு கஷ்டங்கள் அபவாதங்கள் ஏற்படும்.\n சொத்து மற்றும் பண விஷயமாக தகராறு ஏற்படும்.\n ஜாதகர் பெண்ணானால் கர்ப்பப்பையில் கோளாறு இருக்கும்.\n ஜாதகருக்கு தோல் வியாதிவரும்.\n தந்தைக்கு இரு மனைவிகள் இருக்கலாம்.',
  'moon+sun+jupiter': 'ஜாதகருக்கு வெளியூரில் அதிர்ஷ்டம், கௌரவம் ஏற்படும்.\n தன் மகனுக்கும் அதிர்ஷ்டம், கௌரவம் ஏற்படும்.\n நல்ல பண்புள்ள குழந்தைகள் பிறக்கும்.',
  'moon+sun+venus': 'ஜாதகருக்கு பணக்கஷ்டம், தேவையில்லாத செலவினங்கள், பணம் வீண் விரயமாகும்.\n  தந்தை பெண் மோகமுள்ளவராக இருப்பார்.\n தந்தைக்கு இருமனைவிகள் இருக்கலாம்.',
  'moon+venus+ketu': 'ஜாதகரின் தாய் மற்றும் மனைவிக்கு பிணி, கருப்பையில் கோளாறு இருக்கும்.\n சகோதரிகளுக்கு திருமண வாழ்க்கையில் தடை.\n ஜாதகர் பெண்ணாக இருந்தால் தனக்குமே திருமண வாழ்வில் தடை உண்டாகும்.\n மர்ம உறுப்பில் வியாதி இருக்கும்.\n ஜாதகரின் தாய்க்கு ஆன்மீக ஈடுபாடு உண்டு. வயிற்றில் பிணி உண்டு.',
  'moon+sun+saturn': 'ஜாதகரின் பெற்றோர்களின் தலையீடுகளால் தொழிலில் அல்லது உத்யோகத்தில் உயரமுடியாத நிலை ஏற்படும்.\n ஜாதகருக்கு மனநிம்மதி இருக்காது.\n தாமதமாக புத்திரர் பிறப்பார்கள்.',
  'moon+sun+rahu': 'ஜாதகரின் தாய் தந்தையருக்கு கஷ்டங்கள் பிணிகள், மந்திரவாதிகளால் தொல்லை ஏற்படும்.\n  தனக்கும்மனநிம்மதி இருக்காது.\n புத்ரதோஷமுண்டு.',
  'moon+sun+ketu': 'குடும்பத்தில் கஷ்டங்கள் இருக்கும். வெறுப்பும் ஏமாற்றமும் ஏற்படும். எப்பொழுதும் தெய்வ வழிபாட்டில் ஈடுபட்டிருப்பார்கள். ஆனால் கஷ்டங்கள் எளிதில் நீங்காது. புத்ரதோஷம் உண்டு.',
  'moon+mars+sun': 'ஜாதகருக்கு மனகலக்கம், நிம்மதி இருக்காது.\n தாய் நிர்வாக திறமையுள்ளவராக இருப்பார்.\n ஆதிக்க எண்ணங்கள் அதிகமாக இருக்கும்.\n ஜாதகர் பெண்ணானால் கணவர் அரசு உத்யோகத்தில் இருப்பார்.\n தூரதேசத்திலிருந்து வருவார்.\n சொந்தத்தில் வரன் அமையலாம்.',
  'moon+mars+mercury': 'ஜாதகருக்கு மனக்கலக்கம், நிம்மதி இருக்காது. சகோதரர்களுக்கு இடையே ஒற்றுமை இருக்காது.\n ஜாதகருக்கு கல்வியில் தடை ஏற்படும்.\n ஜாதகருக்கு காம உணர்வு அதிகமாக இருக்கும்.\n தோல் வியாதிவரும்.\n  ஜாதகரின் தாய் முன்கோபியாகவும், படித்தவராகவும் இருப்பார்.',
  'moon+mars+jupiter': 'ஜாதகரின் தாய் முன்கோபி.\n நேர்மையானவர்.\n ஜாதகருக்கு மனக்கலக்கம், அதிக இரத்த அழுத்தம், இருதய நோய் போன்றவை தோன்றும்.\n ஜாதகரும் முன்கோபியாக இருப்பார்.\n சகோதரர்கள் நல்ல குணமுள்ளவர்களாக இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் மிகதொலைவிலிருந்து வருவார்.\n நல்ல குணம் உள்ளவராக இருப்பார்.',
  'moon+mars+venus': 'ஜாதகரின் மனைவிக்கு கர்ப்பப்பையில் கோளாறு, அறுவை சிகிச்சை செய்து கொள்வார்.\n ஜாதகருக்கு மனகலக்கம், வயிற்றில் பிணி, ஜாதகரின் தாய் முன்கோபி.\n பண விரயம், தேவையில்லா செலவினங்கள்.\n கணவன் மனைவியிடையே அடிக்கடி சண்டை போட்டுக்கொண்டே இருப்பார்கள்.',
  'moon+mars+saturn': 'ஜாதகரின் தாய் முன்கோபியாக இருப்பார்.\n சகோதரனுக்கு கஷ்டங்கள், ஜாதகருக்கு தொழில் வகையில் உத்யோக வகையில் கஷ்டங்கள்.\n ஜாதகருக்கு பல்லில் ரோகம்.\n மன சஞ்சலம்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு கஷ்டங்கள்.',
  'moon+mars+rahu': 'ஜாதகரின் தாய்க்கு கண்டங்கள், கஷ்டங்கள்.\n சகோதரனுக்கும் கண்டங்கள் கஷ்டங்கள்.\n ஜாதகர் பெண்ணானால் கணவருக்கு கண்டங்கள் கஷ்டங்கள்.\n ஜாதகருக்கு வயிற்றில் பிணி அழகற்ற பற்கள்.\n சகோதரனுக்கு தூரதேசபயணங்கள்.',
  'moon+mars+ketu': 'ஜாதகரின் தாய் மற்றும் சகோதரனுக்கு கஷ்டங்கள்.\n தாய்க்கு ஆன்மீக ஈடுபாடு.\n திருமணத்தில் தடை.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருடன் கருத்து வேறுபாடு கொள்தல்.\n  மூலவியாதி, கட்டிகள் தோன்றுதல், புற்றுநோய் தோன்றுதல்.',
  'moon+mercury+sun': 'ஜாதகரின் தாய் அறிவாளி, நிர்வாகத் திறமையுள்ளவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கர்ப்பப்பையில் கோளாறு, தோல் வியாதி.\n அதிக காம உணர்வு.',
  'moon+mercury+mars': 'ஜாதகரின் தாய் அறிவாளி, சற்று முன்கோபி.\n எப்போதும் ஏதாவது பேசிக்கொண்டே இருப்பார்.\n எல்லோருடனும் தர்க்கம் செய்பவராக இருப்பார்.\n தோல் வியாதி.\n ஜாதகருக்கு கல்வியில் தடை சகோதரர்களிடையே ஒற்றுமையின்மை.',
  'moon+mercury+jupiter': 'ஜாதகரின் தாய் நல்ல அறிவாளியாகவும், குணவதியாகவும் இருப்பார்.\n தாய் நல்ல நகைச்சுவையாகவும் பேசுவார்.\n ஜாதகர் சிறப்பான கல்வி உடையவராகவும், புத்திசாலியாகவும் இருப்பார்.\n வியாபார விஷயமாக வெளியில் சென்று கொண்டே இருப்பார்.',
  'moon+mercury+venus': 'ஜாதகரின் தாய் நல்ல அறிவாளியாகவும், செல்வ செழிப்புள்ளவராகவும் இருப்பார்.\n ஜாதகருக்கு அதிகமாக காம உணர்வு இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் விபச்சாரியாக இருப்பார்.\n ஜாதகருக்கு தோல்வியாதி மற்றும் வயிற்றில் பிணியிருக்கும்.',
  'moon+mercury+saturn': 'ஜாதகரின் தாய் நல்ல அறிவாளியாகவும் சற்று சோம்பேறியாகவும் இருப்பார்.\n ஜாதகருக்கு கல்வியில் மந்த நிலை ஏற்படும்.\n ஜாதகருக்கு தோல்வியாதி. வயிற்றில் பிணி உண்டாகும்.\n ஜாதகர் மந்த புத்தி உள்ளவராக இருப்பார்.\n ஜாதகருக்கு அவமானம், கெட்ட பெயர் ஏற்படும்.',
  'moon+mercury+rahu': 'ஜாதகரின் தாய்க்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு மனதில் எப்போதும் இனம் புரியாத பயம் இருக்கும்.\n பெண்களுடன் ரகசிய தொடர்பு வைத்திருப்பார்.\n தோல் வியாதி தோன்றும்.\n வயிற்றில் பிணி உண்டு.\n ஜாதகர் மந்த புத்தி உள்ளவராக இருப்பார்.',
  'moon+mercury+ketu': 'ஜாதகரின் தாய் தெய்வ பக்தியுள்ளவர்.\n சாஸ்திர சம்பிரதாயங்களை அனுசரிப்பவராக இருப்பார்.\n தாயின் சொத்து வகையில் தகராறு இருக்கும்.\n ஜாதகர் காதல் விவகாரத்தில் ஈடுபடுவார்.\n இதனால் கெட்ட பெயர் அவமானங்கள் ஏற்படும்.\n ஜாதகருக்கு சுருண்ட அல்லது அழகான முடி இருக்கும்.\n அழகான மீசை உடையவர்.\n ஜாதகர் பெண்ணானால்நீண்ட அல்லது சுருண்டகூந்தல் இருக்கும்.\n நரம்பு தளர்ச்சி, இடது கண்ணில் நோய் வரும்.',
  'moon+jupiter+sun': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும், நிர்வாகத் திறமையுள்ளவராகவும் இருப்பார்.\n தாய் தெய்வ பக்தியுள்ளவராக இருப்பார்.\n ஜாதகர் தாய் தந்தை மீது பற்றுள்ளவராக இருப்பார்.\n ஜாதகர் தன் தந்தையின் நல்ல குணங்கள் எல்லாவற்றையும் பெற்றிருப்பார்.\n ஜாதகர் புகழடைவார். நிர்வாகத் திறமை உள்ளவனாவார்.\n ஜாதகர் ஒளி பொருந்திய கண்களை பெற்றிருப்பார்.\n கருணை சிந்தும் கண்கள்.\n ஜாதகர் பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகர் பிறந்த இடத்திற்கு அருகில் நீர்நிலைகள் இருக்கும்.',
  'moon+jupiter+mars': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும். சற்று முன்கோபியாகவும் இருப்பார்.\n தாய் தெய்வ நம்பிக்கை, சத்தியத்தில் நம்பிக்கையுள்ளவர்.\n ஜாதகர் முன்கோபியாக இருப்பார். அதிக ரத்த அழுத்தம், இருதய நோய் போன்றவை உண்டாகும்.',
  'moon+jupiter+mercury': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும், அறிவாளியாகவும் இருப்பார்.\n ஜாதகர் நல்ல அறிவாளியாக இருப்பார்.\n ஜாதகருக்கு பேச்சு திறமை, எழுத்து திறமைகள் இருக்கும். எல்லோரையும் தன் பேச்சால் கவர்வார்.\n ஜாதகருக்கு பல பெண் நண்பர்கள் இருப்பார்கள். பல பெண்களை அனுபவிப்பார்.\n அடிக்கடி பயணங்கள் செய்வார்.\n ஜாதகருக்கு இரண்டு மனைவிகள் இருக்கலாம்.',
  'moon+jupiter+venus': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும், செல்வ செழிப்புள்ளவராகவும் இருப்பார்.\n ஜாதகர் செல்வ செழிப்புள்ளவர். அழகானவர். கலைத்துறையில் நாட்டமுள்ளவர். ஆடம்பரபிரியர்.\n ஜாதகருக்கு பல பெண்களுடன் தொடர்பு ஏற்படும். பல பெண்களை அனுபவிப்பார். இரண்டு மனைவிகள் இருக்கலாம்.\n ஜாதகர் தாய் மற்றும்மனைவி இருவருக்குமிடையே நடக்கும்பிரச்சனைகளைத் தீர்த்து வைக்க முடியாமல் தவிப்பார்.',
  'moon+jupiter+saturn': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும், கௌரவமான உத்யோகம் அல்லது சொந்த தொழில் செய்பவராகவும் இருப்பார்.\n ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.\n ஜாதகருக்கு ஆன்மீகத்தில் ஈடுபாடு ஏற்படும்.\n அடிக்கடி பிரயாணங்கள் செய்வார்.',
  'moon+jupiter+rahu': 'ஜாதகருக்கும்.\n தாய்க்கும் கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் வெளிநாடு போவார்.\n ஜாதகருக்கு நீரில் கண்டம் உண்டு.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.\n மனதில் இனம் புரியாத பயம் இருக்கும்.\n அம்மை போடுதல் போன்ற நோய்கள் வரும்.',
  'moon+jupiter+ketu': 'ஜாதகரின் தாய் நல்ல குணவதியாகவும், தெய்வ பக்தி உள்ளவராகவும் இருப்பார்.\n ஜாதகர் ஆன்மீக ஈடுபாடு உள்ளவராக இருப்பார்.\n ஜாதகருக்கு உள்ளுணர்வு அதிகமாக இருக்கும்.\n ஜாதகருக்கும் தாய்க்கும் இது கடைசி பிறப்பாகும்.\n மோட்சம் பெறுவார்கள்.\n ஜாதகருக்கு சுவாசம் சம்பந்தமான பிணி இருக்கும்.\n வயிற்றிலும் பிணி உண்டு.\n ஜாதகர் பிறந்த இடத்திற்கு பக்கத்தில் ஒரு கோவிலோ தர்ம ஸ்தாபனமோ, மருத்துவமனையோ இருக்கும்.\n ஜாதகர் பிறவிசித்தனாக இருப்பார்.\n வாக்குபலிதமுடையவர்.\n கைராசி உள்ளவர்.',
  'moon+venus+sun': 'ஜாதகரின் தாய் செல்வ செழிப்புள்ளவர்.\n நிர்வாக திறமையுள்ளவர்.\n ஜாதகரின் மனைவிக்கு கருப்பையில் கோளாறு இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் அவருக்கே கருப்பையில் கோளாறு இருக்கும்.\n ஜாதகனுக்கு வயிற்றில் பிணி உண்டு.\n அஜீரணம், வாயுகோளாறு, சர்க்கரை வியாதி போன்றவை இருக்கும்.\n புத்ரதோஷம் உண்டு.\n மனைவிக்கு கர்ப்ப சிதைவு உண்டாகும்.\n மனைவி நிர்வாகத் திறமையுள்ளவர்.\n ஜாதகருக்கு காம உணர்வு அதிகமிருக்கும்.',
  'moon+venus+mars': 'ஜாதகரின் தாய் செல்வ செழிப்புள்ளவர்.\n சற்று முன்கோபி ஜாதகரின் மனைவியும் முன்கோபியாக இருப்பார்.\n மனைவிக்கு கர்ப்ப சிதைவு கர்ப்பப்பையில் கோளாறு உண்டாகும்.\n அறுவை சிகிச்சை செய்து கொள்வார்.\n ஜாதகர் பெண்ணாக இருந்தால் அவருக்கே கருப்பையில் கோளாறு உண்பாகும்.\n அறுவை சிகிச்சை செய்து கொள்வார்.\n ஜாதகருக்கு காம உணர்வு அதிகம் இருக்கும்.',
  'moon+venus+mercury': 'ஜாதகரின் தாய் செல்வ செழிப்புள்ளவராகவும், அறிவாளியாகவும் இருப்பார்.\n ஜாதகருக்கு பல பெண்களுடன் தொடர்பு ஏற்படும்.\n பல வண்களை அனுபவிப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் விபச்சாரியாக இருப்பார்.\n தோல் வியாதி, கர்ப்பப்பையில் கோளாறு ஏற்படும்.\n மனைவி அழகானவராகவும், அறிவாளியாகவும் இருப்பார்.\n நடத்தையில் குற்றமுண்டு.',
  'moon+venus+jupiter': 'தாய் செல்வவளம் மிக்கவர்.\n சுய தொழில் உண்டு.',
  'moon+venus+saturn': 'ஜாதகரின் தாய் செல்வ செழிப்புள்ளவளாகவும், சுய சம்பாத்தியம் உள்ளவளாகவும் இருப்பார்.\n மனைவி சுய சம்பாத்தியமுள்ளவர்.\n ஜாதகருக்கு மனைவியால் யோகம். திருமணத்திற்கு பின் செல்வந்தனாவார்.\n வயிற்றில் பிணியுண்டு.\n மனைவிக்கு கர்ப்பப்பையில் கோளாறு உண்டு.\n மந்த புத்தியுடைவர்.\n தாய் மற்றும் மனைவி சோம்பேறியாக இருப்பார்கள்.',
  'moon+venus+rahu': 'ஜாதகரின் தாய் மற்றும் மனைவிக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மனைவி பொய் சொல்பவராகவும், வஞ்சகியாகவும் இருப்பார்.\n ரகசியமாக தவறு செய்பவராக இருப்பார்.\n மனைவிக்கு கருப்பையில்  கோளாறு உண்டு.\n ஜாதகர் பல பெண்களுடன் ரகசிய தொடர்பு வைத்திருப்பார்.\n காம உணர்வு அதிகமாக இருக்கும்.\n வயிற்று பிணி உண்டு.',
  'moon+saturn+sun': 'ஜாதகரின் தாய் சோம்பேறியாக இருப்பார்\n. ஜாதகருக்கு தாய் தந்தையரால் தடைகள்.\n தொழில் வகையில் முன்னேற முடியாத நிலை.\n வீண்பழி அபவாதம், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கும்  பெற்றோருக்கும் இடையே கருத்து வேறுபாடு இருக்கும்.',
  'moon+saturn+mars': 'ஜாதகருக்கு உத்யோகம் மற்றும் தொழில் வகையில் தொல்லைகள் கஷ்டங்கள் ஏற்படும்.\n சரியான உத்யோகமோ தொழிலோ அமையாது.\n அடிக்கடி தொழில் மாற்றம், இடமாற்றம் ஏற்படும்.\n ஜாதகர் பல்லில் ரோகமுள்ளவர்.\n வயிற்றில் பிணி உள்ளவர்.\n பசி தாங்கமாட்டார்.',
  'moon+saturn+mercury': 'ஜாதகர் வியாபாரம் செய்பவராகவும், அடிக்கடி பிரயாணம் செய்பவராகவும் இருப்பார்.\n ஜாதகர் நல்ல கற்பனை வளமுள்ளவராகவும், நல்ல பேச்சாளராகவும், எழுத்தாளராகவும் இருப்பார்.',
  'moon+saturn+jupiter': 'ஜாதகரின் தாய்க்கும் தனக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு நீரில் ஆபத்து உண்பாகும்.\n ஜாதகர் வெளிநாடு செல்வார்.\n அம்மைபோடுதல் போன்ற நோய், வயிற்று பிணி உண்டு.\n ஜாதகருக்கு மனதில் பயமிருக்கும்.',
  'moon+saturn+venus': 'ஜாதகரின் தாய் சோம்பேறியாகவும், செல்வந்தராகவும் இருப்பார்.\n ஜாதகர் செல்வந்தராவார்.\n மனைவியால் யோகம் உண்டாகும்.\n மனைவிக்கு சுயவருமானம் இருக்கும்.\n செல்வந்தர் வீட்டிலிருந்து வருவாள்.\n ஜாதகருக்கு பணவிரயம் ஏற்படும்.\n ஜாதகருக்கு பெண்களால் தொல்லை, அவமானம் ஏற்படும்.',
  'moon+saturn+rahu': 'ஜாதகரின் தாய்க்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு கடின உழைப்பு, பரதேசம் செல்லுதல் போன்றவை உண்டாகும்.\n ஜாதகன் மந்த புத்தியுடையவர்.\n வயிற்றில் பிணியிருக்கும்.\n ஜாதகருக்கு யாருடைய உதவியும் இருக்காது.\n சுயமுயற்சியில் 30 வயதிற்கு மேல் மேன்மை அடைவார்.',
  'moon+saturn+ketu': 'ஜாதகரின் தாய்க்கு ஆன்மீக ஈடுபாடு, தெய்வபக்தி இருக்கும்.\n ஜாதகர் ஒரு சன்யாசி போல இருப்பார்.\n குறிக்கோள் எதுவுமில்லாமல் அலைந்து கொண்டிருப்பார்.\n இந்த பிறவியில் பல கஷ்டங்களை அனுபவித்து, பாவங்களைத் தீர்த்து மோட்சத்தை அடைவார்.\n ஜாதகர் ஜோதிடம் வேதபாடம் முதலியவற்றை கற்பார்.\n சுவாச வழியில் பிணியிருக்கும்.\n சரியான உத்யோகம் தொழில் அமையாது.',
  'moon+rahu+sun': 'ஜாதகரின் பெற்றோருக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n கண் ரோகம் உண்டு.\n ஜாதகருக்கு அற்ப ஆயுள் உள்ள புத்திரர்கள் பிறப்பார்கள்.\n ஜாதகர் மனதில் பயமுள்ளவராக இருப்பார்.',
  'moon+rahu+mars': 'ஜாதகரின் பெற்றோர் மற்றும் சகோதரர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n தனக்குமேகண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n  ஜாதகர்பெண்ணாக இருந்தால் கணவருக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் மனதில் பயமுள்ளவராகவும், மந்த புத்தியுள்ளவராகவும் இருப்பார்.',
  'moon+rahu+mercury': 'ஜாதகரின் தாய்க்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n தோல் வியாதி வரும்.\n ஜாதகர் மனதில் பயமுள்ளவராகவும் மந்தபுத்தி உள்ளவராகவும் இருப்பார்.',
  'moon+rahu+venus': 'ஜாதகரின் தாய், மனைவி மற்றும் சகோதரிகளுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மனைவிக்கு கருச்சிதைவு உண்டாகும்.\n ஜாதகருக்கு மனதில் பயமிருக்கும்.',
  'moon+rahu+saturn': 'ஜாதகரின் தாய் சோம்பேறியாக இருப்பாள்.\n தாய்க்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் தூரதேசம் போவார்.\n ஜாதகர் மந்த புத்தியுள்ளவராக இருப்பார்.\n மனதில் பயமுள்ளவராக இருப்பார்.',
  'moon+rahu+ketu': 'ஜாதகரின் தாய்க்கு அற்ப ஆயுள், பிணி.\n ஜாதகர் மந்த புத்தியுள்ளவராகவும் மனதில் பயம் உள்ளவராகவும் இருப்பார்.',
  'moon+ketu+sun': 'ஜாதகரின் தாய் தந்தையருக்கிடையே தகராறு.\n ஒற்றுமையின்மை கண்ணில் ரோகமுண்டு.\n பெற்றோர் தெய்வ நம்பிக்கை உள்ளவராக இருப்பார்.\n ஜாதகர் உள்ளுணர்வு உள்ளவராக இருப்பார்.\n பெற்றோருக்கு பிணி உண்டாகும்.',
  'moon+ketu+mars': 'ஜாதகரின் தாய்வழி உறவினர்களுடன் சுமூகமான உறவு இருக்காது.\n சண்டை சச்சரவுகள் தோன்றும்.\n ஜாதகருக்கு மனசஞ்சலம் உண்டாகும்.\n தாய்க்கு கஷ்டங்கள், பிணிகள் உண்டாகும்.\n தாய்க்கும்சதோரர்களுக்குமிடையே தகராறு உண்டாகும்.',
  'moon+ketu+mercury': 'ஜாதகருக்கு நிலத்தகராறு.\n இரண்டு பெண்களுடன் சண்டை சச்சரவு.\n பெண்களால் ஏமாற்றம்.\n ஜாதருக்கு தோல் வியாதி இருக்கும்.\n பெண்களால் அவமானம் ஏற்படும்.',
  'moon+ketu+jupiter': 'ஜாதகரின் தாய் மகனுக்கிடையே தகராறு.\n பெண்களுடன் சண்டை சச்சரவு.\n தாய்வழி உறவினர்களுடன் சண்டை சச்சரவு.\n வீண்பழி அபவாதம்.',
  'moon+ketu+venus': 'ஜாதகரின் தாய்வழி சொத்து சம்பந்தமாக தகராறு.\n தாய் மற்றும் மனைவிக்குமிடையே தகராறு.\n இரண்டு பெண்களுடன் தகராறு.\n பெண்களால் பணவிரயம் ஏற்படும்.',
  'moon+ketu+saturn': 'ஜாதகரின் தாய்வழி உறவினர்களுடன் சண்டை சச்சரவு, வீண்பழி அபவாதம்.\n  தாய்க்கு கண்டங்களும், கஷ்டங்களும் இருக்கும்.',
  'moon+ketu+rahu': 'ஜாதகரின் தாய்க்கு அற்ப ஆயுள்.',
  'mars+sun': 'ஜாதகருடைய சகோதரன் நிர்வாகத் திறமையுள்ளவர்.\n புகழுடையவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் புகழுடையவர்.\n நல்ல உயர்ந்த குடும்பத்தை சேர்ந்தவர்.',
  'mars+moon': 'ஜாதகருடைய சகோதரர் பிரயாணம் செய்வதில் விருப்பம் உள்ளவர் அல்லது பிறந்த இடத்தை விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் அடிக்கடி பிரயாணம் செய்பவராக இருப்பார்.',
  'mars+mercury': 'ஜாதகர் எப்பொழுதும் விவாதம் செய்பவனாக இருப்பான்.\n ஜாதகர் பொறியியல் துறையில் வல்லுநராக இருப்பார்.\n கல்வியில் தடையுண்டு.\n ஜாதகரின் சகோதரர் புத்திசாலியாக இருப்பார்.\n சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் மிகவும் புத்திசாலியாக இருப்பார்.\n வாக்கு வன்மையுள்ளவர்.\n எப்பொழுதும் சிரித்த முகத்துடன் இருப்பார்.\n திருமண வாழ்வில் சந்தோஷம் இருக்காது.',
  'mars+jupiter': 'ஜாதகரின் சகோதரர் நல்ல குணங்களுடையவர்.\n தெய்வபக்தியுள்ளவர்.\n ஜாதகர் ஆணவமுள்ளவராக இருப்பார்.\n இருதய நோயுள்ளவர்.\n இரத்த அழுத்தம் அதிகமாக இருக்கும்.\n சிறு விஷயங்களுக்கெல்லாம் கோபப்படுவார்.\n உரக்கப்பேசுவார்.\n எல்லோரிடத்திலும் சண்டைக்குப்போவார்.\n கோபத்தில் கொலை செய்தாலும் ஆச்சர்யப்படுவதற்கில்லை.\n எல்லோரும் தனக்கு அடங்கி நடக்க வேண்டுமென நினைப்பான்.\n அடங்காவிட்டால் அடித்து அடக்க முயற்சி செய்வார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவன் நல்ல குணமுள்ளவராக இருப்பார்.\n கணவருக்கும் மேற்சொன்ன எல்லா குணங்களும் இருக்கும்.',
  'mars+venus': 'ஜாதகரின் சகோதரன் செல்வந்தராவார்.\n ஜாதகரின் மனைவி ஆணவமிக்கவராக இருப்பார்.\n எளிதில் உணர்ச்சிவசப்படுபவராகவும், கோபக்காரியாகவும் இருப்பார்.\n கணவன் மனைவி அடிக்கடி சண்டை போட்டுக்கொண்டே இருப்பார்கள்.',
  'mars+saturn': 'ஜாதகருக்கு எதிரிகளால் தொல்லை, சரியான உத்தியோகமோ தொழிலோ அமையாது.\n அப்படி அமைந்தாலும் ஏதாவது பிரச்சனைகள் இருந்து கொண்டே இருக்கும்.\n ஜாதகர் எல்லோரிடமும் சண்டை போடுவார்.\n பல்லில் ரோகமுள்ளவர்.\n அல்சர் போன்று வயிற்றில் வியாதியுள்ளவர்.\n பசிதாங்கமாட்டார்.\n எப்பொழுதும் தின்று கொண்டேயிருப்பார்.\n பிறரை பற்றி கவலைப்படமாட்டார்.\n சுயநலவாதியாக இருப்பார்.\n திருமணத் தடையுண்டு, தன் இனத்தையே வெறுப்பார்.\n ஆசாபாசம் இல்லாதவர்.\nஜாதகரின் சகோதரன் மந்த புத்தியுள்ளவர்.\n சோம்பேறியாக இருப்பார்.\n எப்பொழுதும் கஷ்டத்திலேயே இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் திருமணம் தாமதப்படும்.\n கணவர் சோம்பேறியாக இருப்பார்.',
  'mars+rahu': 'ஜாதகர் உடல்வலிமை இல்லாதவர்.\n பல்லில் ரோகமுடையவர்.\n  அகம்பாவமிக்கவர்.விபத்துக்களை சந்திப்பார்.\n வெட்டுக்காயங்கள்.\n அறுவை சிகிச்சை போன்றவை தவிர்க்க முடியாதது.\n கருவிகள் மற்றும் தீயினால் விபத்து ஏற்படும்.\n ஜாதகரின் சகோதரன் எப்பொழுதும் கஷ்டத்திலிருப்பார்.\n நோய்வாய்ப்பட்டிருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு ஆயுள் குறைவு.\n திருமணம் தாமதப்படும்.\n கணவனை பிரிந்து வாழ்வார்.',
  'mars+ketu': 'ஜாதகர் உடலில் அதிக உஷ்ணமுள்ளவர்.\n மூலவியாதி கட்டிகள், புற்றுநோய் முதலியவை தோன்றும்.\n திருமணத்தில் தடையுண்டு.\n தாமதப்படும்.\n ஜாதகரின் சகோதரர் ஆன்மீகத்தில் ஈடுபாடு உள்ளவர்.\n ஜாதகர் வெண்ணாக இருந்தால்கணவர் ஆன்மீகவாதியாக இருப்பார்.\n குடும்பவாழ்க்கையில் ஈடுபாடு இருக்காது.',
  'mars+sun+moon': 'ஜாதகர் அரசு உத்தியோகத்தில் இருக்கலாம்.\n ஜாதகரின் சகோதரர்கள் நிர்வாகத் திறமையுள்ளவர்கள்.\n அடிக்கடி பிரயாணம் செய்பவர்களாக இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நிர்வாக திறமையுள்ளவராக முன்கோபியாக இருப்பார்.',
  'mars+sun+mercury': 'ஜாதகரின் சகோதரர்கள் நிர்வாகத் திறமையுள்ளவர்களாகவும், அறிவாளிகளாகவும் இருப்பார்கள்.\n ஜாதகரின் தந்தைக்கு சொந்தமாக நிலபுலன்கள் இருக்கும்.\n தகப்பனுக்கு அற்ப ஆயுள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நிர்வாகத்திறமையுள்ளவர்.\n அறிவாளியாகவும் இருப்பார்.',
  'mars+sun+jupiter': 'ஜாதகரின் சகோதரர்கள் நிர்வாகத் திறமையுள்ளவர்களாகவும், நல்ல குணம் உள்ளவர்களாகவும் இருப்பார்கள்.\n தெய்வ நம்பிக்கையுள்ளவர்கள்.\n தகப்பன் புகழ்பெற்றவராகவும், தெய்வ நம்பிக்கையுள்ளவராகவும் இருப்பார்.\n தந்தை மரியாதைக்கு உரியவராகவும், கௌரவமான குடும்பத்தை சேர்ந்தவராகவும் இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நிர்வாகத் திறமையுள்ளவராகவும், நல்ல குணங்கள் உள்ளவராகவும், கௌரவமான குடும்பத்தில் பிறந்தவராகவும் இருப்பார்.',
  'mars+sun+venus': 'ஜாதகரின் சகோதரர்கள் நிர்வாகத் திறமையுள்ளவர்களாகவும், செல்வ செழிப்பு உள்ளவர்களாகவும் இருப்பார்கள்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு மேற்சொன்ன குணங்கள் இருக்கும்.\n கணவர் செல்வாக்கான குடும்பத்திலிருந்து வருவார்.',
  'mars+sun+saturn': 'ஜாதகரின் சகோதரர் முன்கோபி, சகோதரருக்கு எதிரிகளால் தொல்லை,\n தகப்பனுக்கு அற்ப ஆயுள்.\n கண்டங்கள், கஷ்டங்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு எதிரிகளால் தொல்லைகள் இருக்கும்.',
  'mars+sun+rahu': 'ஜாதகரின் சகோதரர் மற்றும் தகப்பனாருக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n தகப்பனுக்கு அற்ப ஆயுள்.\n விபத்துக்கள் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு இப்பலன்கள் நடக்கும்.\n ஜாதகருக்கும் விபத்துக்கள் ஏற்படும்.',
  'mars+sun+ketu': 'ஜாதகரின் சகோதரர்களிடையே ஒற்றுமை இருக்காது.\n குடும்பத்தில் சண்டை சச்சரவுகள் இருக்கும்.\n ஜாதகரின் தந்தைக்கு உஷ்ணம் சம்பந்தமான பிணி இருக்கும்.\n ஜாதகருக்கு மூலவியாதி, கட்டிகள் போன்றவை தோன்றும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் விரக்தி மனப்பான்மையுள்ளவராக இருப்பார்.',
  'mars+moon+sun': 'ஜாதகரின் மனைவிக்கு கர்ப்பப்பையில் கோளாறு இருக்கும்.\n கருச்சிதைவு ஏற்படும்.\n ஜாதகருக்கு காம உணர்வு அதிகம் இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவன் ஏற்கனவே திருமணமானவராக இருப்பார்.\n ஜாதகரின் சகோதரர்கள் சலனப்புத்தி உள்ளவர்களாக இருப்பார்கள்.\n ஜாதகரும் மனசஞ்சலம் உள்ளவராக இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் அடிக்கடி பிரயாணம் செய்பவராக இருப்பார்.\n சலனப்புத்தி உள்ளவராக இருப்பார்.',
  'mars+moon+mercury': 'ஜாதகரின் சகோதரனுக்கு பெண்களால் அவமானம் ஏற்படும்.\n சகோதரர்களில் ஒருவர் நீண்டதூரப் பயணங்கள் மேற்கொள்வார்.\n ஜாதகருக்கு தோல் நோய் உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நீண்டதூரப் பயணங்கள் மேற்கொள்வார்.\n கணவர் நல்லபுத்திசாலியாக இருப்பார்.',
  'mars+moon+jupiter': 'ஜாதகரின் ஒரு சகோதரர் வேறு இடத்தில் குடியேறுவார்.\n ஜாதகருக்கு மனசஞ்சலம், ஜாதகருக்கு வயிற்றில் பிணி, அறுவை சிகிச்சை செய்து கொள்வார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவன் தர்ம சிந்தனையுள்ளவராகவும் நல்ல குணமுள்ளவராகவும் இருப்பார்.',
  'mars+moon+venus': 'கணவர் கவர்ச்சியான தேகம் உடையவர்.\n ஆடம்பரமானவாழ்க்கை வாழ்வார்.',
  'mars+moon+saturn': 'ஜாதகரின் சகோதரர்களுக்கு கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கும் கஷ்டங்கள் வீண்பழி, அபவாதம் உண்டாகும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு இந்த பலன்கள் நடக்கும்.\n தாய்க்கு அற்ப ஆயுள்.',
  'mars+moon+rahu': 'ஜாதகரின் சகோதரனுக்கும் தாய்க்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n தாய்க்கு அற்ப ஆயுள்.\n ஜாதகருக்கு மனசஞ்சலம்.\n மனதில் பயம் இருக்கும்.\n ஒரு சகோதரர் தூரதேசப் பயணம் மேற்கொள்வார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு  இந்த பலன்கள் நடக்கும்.\n கணவர் தூரதேசப் பயணம் மேற்கொள்வார்.',
  'mars+moon+ketu': 'ஜாதகரின் சகோதரர்களுக்கும் தாய்க்கும் கஷ்டங்கள் பிணிகள் தோன்றும்.\n கஷ்டங்களிலிருந்து விடுபடுவதற்காக அவர்கள் கடவுள் வழிபாட்டில் ஈடுபட்டிருப்பார்கள்.\n எளிதில் அவர்கள் கஷ்டம் தீராது.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் விரக்தி மனப்பான்மை உடையவராக இருப்பார்.\n எதிலும் பிடிப்பு இருக்காது.\n சன்யாசி போல் இருப்பார்.\n தெய்வ அருள்பெற்றவராக இருப்பார்.\n ஜாதகருக்கு புற்றுநோய் வரலாம்.\n மூலவியாதி, கட்டிகள் தோன்றலாம்.\n ஜாதகருக்கு மனநிம்மதி இருக்காது.',
  'mars+mercury+sun': 'ஜாதகரின் சகோதரர்கள் அறிவாளிகளாகவும் நிர்வாகத் திறமை உள்ளவர்களாகவும் இருப்பார்கள்.\n சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n ஜாதகருக்கு கல்வியில் தடையுண்டாகும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் அறிவாளியாகவும் நிர்வாகத் திறமை உள்ளவராகவும் இருப்பார்.',
  'mars+mercury+moon': 'ஜாதகரின் சகோதரர்கள் நல்ல புத்திசாலியாக இருப்பார்கள்.\n நீண்ட தூரப் பயணம் செய்பவர்களாக இருப்பார்கள்.\n சகோதரர்களுக்கு இடையே ஒற்றுமை இருக்காது.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு மேற்சொன்ன குணங்கள் இருக்கும்.\n ஜாதகருக்கு கல்வியில் தடையுண்டு.',
  'mars+mercury+jupiter': 'ஜாதகரின் சகோதரர்கள் நல்ல புத்திசாலிகளாகவும், நல்ல பண்பட்ட குணங்கள் உடையவர்களாகவும் இருப்பார்கள். தெய்வபக்தியும் இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு மேற்சொன்ன குணங்கள் இருக்கும்.\n ஜாதகருக்கு கல்வியில் தடையுண்டு.',
  'mars+mercury+venus': 'ஜாதகரின் சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n பணவிஷயமாக அடிக்கடி சண்டை சச்சரவுகள் ஏற்படும்.\n ஜாதகருக்கு கல்வியில் தடை ஏற்படும்.\n கணவன் மனைவியிடையே ஒற்றுமை இருக்காது.\n அவரவர் விருப்பம் போல் வாழ்ந்து கொண்டிருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நல்ல புத்திசாலியாகவும், செல்வந்தராகவும் இருப்பார்.',
  'mars+mercury+saturn': 'ஜாதகருக்கு கல்வியில் தடையுண்டு.\n குடும்பத்தில் ஒற்றுமை இருக்காது.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு பலகஷ்டங்கள் ஏற்படும்.\n திருமணம் தாமதப்படும்.\n ஜாதகருக்கு பல்லில் ரோகமுண்டு.',
  'mars+mercury+rahu': 'ஜாதகருக்கு கல்வியில் தடையுண்டு.\n சகோதரர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n திருமண வாழ்க்கை நன்றாக இருக்காது.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு பல்வரிசை அழகாக இருக்காது.',
  'mars+mercury+ketu': 'ஜாதகரின் குடும்பத்தில் சொத்து விஷயமாக தகராறு ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருடன் கருத்து வேறுபாடு ஏற்பட்டு விவாகரத்து பெறும் நிலை ஏற்படும்.',
  'mars+jupiter+sun': 'ஜாதகர் ஆணாக இருந்தால் முன்கோபியாக இருப்பார்.\n உடலில் உஷ்ணம் அதிகமாக இருக்கும்.\n தைர்யமுள்ளவராகவும், நிர்வாகத் திறமையுள்ளவராகவும் இருப்பார்.\n சுறுசுறுப்பாக இருப்பார். எதையும் மனதில் வைக்க முடியாமல் வெளிப்படையாகப் பேசுவார்.\n கோபம் உள்ளவரானாலும், குணமுள்ளவராக இருப்பார்.\n ஆதிக்க எண்ணமுள்ளவராக இருப்பார். உஷ்ணம் சம்பந்தமான பிணிகள் வரும்.\n ஜாதகருடைய சகோதரன் நல்ல பண்பாளனாகவும் நிர்வாகத் திறமையுள்ளவனாகவும், தர்ம குணமுள்ளவனாகவும் இருப்பார்.\n சகோதரர்கள் நல்ல உயர்ந்த நிலையில் இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் மேற்சொன்னவைகள் எல்லாம் பொருந்தும்.\n ஜாதகியின் கணவர் நல்ல பண்புள்ளவராகவும் கௌரவமானவராகவும் இருப்பார்.\n அரசு உத்யோகம் பார்ப்பவராகவோ அராசாங்க ஆதரவு பெற்றவராகவோ இருப்பார்.\n கௌரவமான குடும்பத்திலிருந்து கணவர் வருவார்.\n ஜாதகர் உடல் இளைத்திருப்பார்.\n ஜாதகர் புகழ்பெற்ற மனிதர்களுடன் தொடர்பு வைத்திருப்பார்.\n தானும் புகழடைவார்.',
  'mars+jupiter+moon': 'ஜாதகர் ஆணாக இருந்தால் முன்கோபியாகவும், நிலையற்ற மனதுடையவராகவும் இருப்பார்.\n ஆத்திரக்காரராகவும், எந்த ஒரு செயலையும் சரிவரச் செய்ய முடியாமல் தவிப்பார்.\n அடிக்கடி மனமாற்றம் ஏற்படுவதால், எந்த ஒரு முடிவையும் எடுக்க முடியாமல் தவிப்பார்.\n ஜாதகரின் சகோதரர்கள் நல்ல பண்புள்ளவர்களாகவும், தர்ம குணமுள்ளவர்களாகவும் இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் அவருடைய கணவர் நல்ல குணங்கள் உடையவராகவும் தர்மவானாகவும் இருப்பார்.\n இதுபோன்ற கிரக அமைப்பு உள்ள ஜாதகருக்கு அழகான பற்கள், கூர்மையான மூக்கு அல்லது புருவங்கள் இரண்டும் மூக்கின் மீது வந்து கூடியிருக்கும்.\n ஜாதகரின் உடல் பருமனாக இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நல்ல கௌரவமான குடும்பத்திலிருந்து வருவார்.',
  'mars+jupiter+mercury': 'ஜாதகர் ஆணாக இருந்தால் சற்று முன்கோபியாக இருந்தாலும், புத்திசாலியாக இருப்பார்.\n பேச்சு வன்மையுள்ளவராக இருப்பார்.\n ஜாதகருக்கு தலையில் வழுக்கை விழுந்திருக்கும்.\n ஜாதகரின் சகோதரர்கள் நற்பண்புள்ளவர்களாகவும், புத்திசாலிகளாகவும் இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நற்பண்பு உள்ளவராகவும், புத்திசாலியாகவும் இருப்பார்.\n கௌரவமான குடும்பத்திலிருந்து வருவார்.',
  'mars+jupiter+venus': 'ஜாதகர் பிடிவாத குணமுள்ளவராக இருப்பார்.\n தன் கடமைகளைச் சரிவரச் செய்வார்.\n யாருக்கும் வளைந்து கொடுக்க மாட்டார்.\n இவரது பிடிவாத போக்கால் தொழில் மற்றும் உத்யோகத்தில் எதிரிகளால் தொல்லைகள் இருந்து கொண்டிருக்கும்.\n இவருக்கு கிடைக்க வேண்டியவைகள் எதுவும் எளிதாக கிடைக்காது.\n எதையுமே போராடி பெற வேண்டிய நிலை ஏற்படும்.\n இவருக்கு விபத்துக்கள் ஏற்பட வாய்ப்பு உண்டு.\n சகோதரர்களிடையே ஏற்படும். சண்டை சச்சரவுகளைத் தீர்த்து வைக்க முடியாமல் கஷ்டப்படுவார்.\n சகோதரர்கள் நல்ல கௌரவமான உத்யோகத்தில் இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நல்ல கௌரவமான உத்யோகத்தில் இருப்பார்.\n இதுபோன்ற கிரக அமைப்புள்ள ஜாதகருக்கு எதுவும் இவர்கள் விருப்பப்படி நடக்காது.',
  'mars+jupiter+rahu': 'ஜாதகருக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருடைய சகோதரர்களுக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு மேற்சொன்னவை நடக்கும்.\n ஜாதகருக்கு வாகனங்களில் விபத்து ஏற்படும்.\n எதிர்பாராத மரணம் ஏற்படலாம்.\n ஜாதகருக்கு அம்மை, வைசூரி போன்ற நோய்களும் வரும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் பரதேசம் போவார்.',
  'mars+jupiter+ketu': 'ஜாதகர் பிடிவாதம் உள்ளவராகவும், வைராக்யம் உள்ளவராகவும் இருப்பார்.\n ஆன்மீக ஈடுபாடு இருக்கும்.\n சகோதரர்கள் நற்பண்புள்ளவராகவும், ஆன்மீகத்தில் ஈடுபாடு உள்ளவராகவும் இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு இவை பொருந்தும்.',
  'mars+venus+sun': 'ஜாதகருடைய சகோதரர்கள் செல்வந்தர்களாகவும், நிர்வாகம் செய்யும் தகுதியுடையவர்களாகவும் இருப்பார்கள்.\n ஜாதகருடைய உயிரணுக்கள் குறைவுள்ளதாக இருக்கும்.\n இதனால் இவருக்கு குழந்தை பிறப்பது கடினம்.\n கணவன் மனைவியிடையே ஒற்றுமையிருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் முற்பிறவியில் யார் இவருக்கு கணவராக இருந்தாரோ அவரே இப்பிறவியிலும் கணவராக வருவார்.\n கணவர் செல்வந்தராகவும், அரசு உத்யோகம் பார்ப்பவராகவோ அல்லது அரசு ஆதரவு பெற்றவராகவோ இருப்பார்.\n புத்ரதோஷம் உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் அப்பெண்ணிற்கு உடம்பில் அதிக உஷ்ணம் இருக்கும்.\n புத்ரதோஷம் ஏற்படும்.\n ஆனால் அப்பெண் சற்று முன்கோபியாக இருப்பாள்.\n நிர்வாகத் திறமையுள்ளவராக இருப்பார்.\n கணவன் மனைவி ஒற்றுமையாக இருப்பார்கள்.',
  'mars+venus+moon': 'பெண்களால் பணம் விரயமாகும்.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.\n ஜீரண கோளாறு, வாயு உபாதைகள் இருக்கும்.\n சிறுநீரக கோளாறு ஏற்படலாம்.\n அறுவை சிகிச்சை செய்து கொள்ளும் நிலை ஏற்படும்.\n ஜாதகருக்கு கர்ப்பப்பையில் கோளாறு ஏற்பட்டு அறுவை சிகிச்சை செய்து கொள்ள நேரிடும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n மனைவிக்கு வயிற்றில் பிணி உண்டாகும்.\n மனைவி சற்று முன்கோபியாக இருப்பார்.\n ஜாதகருக்கு அனாவசியமான செலவுகள் ஏற்படும். பணம் கையில்தங்காது.',
  'mars+venus+mercury': 'ஜாதகருடைய சகோதரர்கள் செல்வந்தர்களாகவும், புத்திசாலிகளாகவும் இருப்பார்கள்.\n சகோதரர்களுக்கிடையே பண விஷயமாக தகராறு ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் இவருக்கு கணவனைத்தவிர காதலன் ஒருவன் இருக்க வாய்ப்புண்டு.\n ஜாதகியின் கணவர், செல்வந்தனாகவும், புத்திசாலியாகவும் இருப்பார்.\n நற்பண்புகளுடையவராக இருப்பார்.',
  'mars+venus+jupiter': 'ஜாதகருடைய சகோதரர்கள் செல்வந்தர்களாகவும், நல்ல கௌரவமான நிலையிலும் இருப்பார்கள்.\n ஜாதகர் அழகாக இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கற்புள்ளவராக இருப்பார்.\n கணவன் செல்வந்தனாகவும், நல்ல பண்புள்ளவராகவும் இருப்பார்.\n கணவன் கௌரவமான குடும்பத்திலிருந்து வருவார்.\n ஜாதகருக்கு புருவம், மூக்கு, கன்னம், பல்வரிசை போன்றவை அழகாக இருக்கும்.\n ஜாதகரின் உடல் கவர்ச்சியானதாகவும் கட்டுடலாகவும் இருக்கும்.',
  'mars+venus+saturn': 'ஜாதகரின் சகோதரர்களிடையே பண விஷயமாக தகராறு இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் சுய சம்பாத்தியம் இருக்கும்.\n இவர் நிலையை விட கணவரின் நிலை சற்று தாழ்வாகவே இருக்கும்.\n திருமணத்திற்குப்பின் கணவருக்காக கஷ்டப்படும் நிலை ஏற்படும்.\n சகோதரர்களிடையே ஏற்படும் சண்டை சச்சரவுகளைத் தீர்த்துவைப்பதில் சிரமப்படுவார்.',
  'mars+venus+rahu': 'ஜாதகருடைய சகோதர, சகோதரிகளுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மனைவிக்கு ஆயுள்குறைவு.\n கணவன் மனைவியிடையே பிரிவு ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் தன் கணவரை வெறுப்பார்.',
  'mars+venus+ketu': 'ஜாதகருடைய குடும்பத்தில் ஒற்றுமை இருக்காது.\n ஜாதகருக்கு சரியான உத்யோகமோ,தொழிலோ அமையாது.\n அப்படியே அமைந்தாலும் பலவிதமான தொல்லைகள் இருந்து கொண்டே இருக்கும்.\n ஜாதகர் அடிக்கடி உத்யோகத்தை மாற்ற வேண்டிய நிலை ஏற்படும்.\n இரும்பு சம்பந்தமான தொழில் அமையலாம்.\n பல்லில் ரோகமுடையவர்.\n சகோதரர்கள் எப்பாழுதும் கஷ்ட நிலையிலேயே இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் எப்பொழுதும் கஷ்டநிலையிலேயே இருப்பார்.\n திருமணத்தடை உண்டு.',
  'mars+saturn+sun': 'ஜாதகருக்கு தொழில் வகையில் அரசாங்கத் தொல்லைகள் இருக்கும்.\n ஜாதகர் முன்கோபி. இயந்திரகளினால் ஆபத்து உண்டு.\n ஜாதகரின் தந்தைக்கு தொழிலில் தொடர்ந்து பிரச்சனை இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவன் மேலதிகாரியுடன் தொடர்ந்து மோதல் போக்கை கடைபிடிப்பார்.\n ஜாதகருக்கு வயிற்றில் ரோகமுண்டு.',
  'mars+saturn+moon': 'ஜாதகருடைய குடும்பத்தில் ஒற்றுமை இருக்காது.\n ஜாதகருக்கு சரியான உத்யோகமோ, தொழிலோ அமையாது.\n அப்படியே அமைந்தாலும் பலவிதமான தொல்லைகளும், அவமானங்களும் ஏற்படும்.\n ஜாதகருக்கு அடிக்கடி உத்யோக மாற்றம், இடமாற்றம் போன்றவை ஏற்படும்.\n சகோதரர்கள் எப்பொழுதும் கஷ்ட நிலையிலேயே இருப்பார்கள்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு கஷ்ட நிலை இருக்கும்.\n திருமணத்தடைஉண்டு',
  'mars+saturn+mercury': 'ஜாதகர் சகோதரர்களுடன் கருத்து வேறுபாடு கொண்டிருப்பார்.\n ஜாதகருக்கு நண்பர்கள் உதவியிருக்கும்.\n கஷ்ட காலங்களில் நண்பர்கள் உதவுவார்கள்.\n சகோதரர்கள் கஷ்ட நிலையிலேயே இருப்பார்கள்.\n ஜாதகர் நண்பர்களின் உதவியோடு கூட்டுத்தொழில் செய்வார்.\n ஜாதகருக்கு தொழில் விஷயத்தில் சிறுசிறு தொல்லைகள் இருந்து கொண்டு தான் இருக்கும்.\n ஜாதகர் பல்லில் ரோகமுள்ளவர்.\n சகோதரர்கள் கஷ்ட நிலையிலேயே இருப்பார்.\n திருமணத்தில்தடையுண்டு.',
  'mars+saturn+jupiter': 'ஜாதகருக்கு சகோதரர்களால் எந்த நன்மையும் விளையாது.\n ஜாதகருக்கு கௌரவமான உத்யோகம் அமைந்தாலோ, உத்யோகத்தில் எதிரிகளால் சிறுசிறு தொல்லைகள் இருந்து கொண்டே இருக்கும்.\n ஜாதகர் பெண்ணானால் கணவர் நல்ல குணமுள்ளவராக இருந்தாலும் கஷ்ட நிலையிலேயே இருப்பார்.\n திருமணத்தில் தடையுண்டு.',
  'mars+saturn+venus': 'ஜாதகரின் சகோதரர்கள் தொழில் நல்ல முன்னேற்றத்தையும், பலவிதங்களில் லாபத்தையும் அடைவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் சிறப்பாகத் தொழில் செய்வார்.\n வேலையாட்கள் மூலம் கணவன் மனைவிக்கு இடையே பிரச்சனைகள் வர வாய்ப்புள்ளது.\n மனைவி தொழிலுக்கு இடைஞ்சலாக இருப்பார்.',
  'mars+saturn+rahu': 'ஜாதகருக்கும் சகோதரர்களுக்கும் துன்பங்கள் கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு வாகனங்களால் விபத்துக்கள் ஏற்படும்.\n பலவிதமான தொல்லைகள் ஏற்படும்.\n தன் உழைப்புக்கு ஏற்ற ஊதியம் கிடைக்காது.\n அடிமட்ட நிலையில் வேலைசெய்வார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு கஷ்டங்கள் ஏற்படும்.\n திருமணத்தில்தடையுண்டு.\n ஜாதகருக்கு நெருப்பு, வாகனம்மற்றும் ஆயுதங்களால் ஆபத்து உண்டு.',
  'mars+saturn+ketu': 'ஜாதகருக்கு சரியான தொழிலோ, உத்யோகமோ அமையாது.\n சகோதரர்கள் கஷ்டமான நிலையில் இருப்பார்கள்.\n ஜாதகர் எந்த குறிக்கோளும் இல்லாமல் சன்யாசிபோல இருப்பார்.\n பலவிதமான கஷ்டங்களை அனுபவிக்க நேரிடும்.\n ஆன்மீக ஈடுபாடு ஒன்றே இவருக்கு மனநிம்மதியைக் கொடுக்கும்.\n எதிரிகளால் தொல்லைகள், செய்யாத குற்றத்திற்கும் தண்டனை அனுபவித்தல் போன்ற நிலை ஏற்படும்.\n ஜாதகர் திக்கு திசை தெரியாமல் தவிப்பார்.\n இவருக்கு வாழ்க்கையில் வெறுப்பும், விரக்தியும் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு இப்பலன்கள் நடக்கும்.\n திருமணத்தில்தடையுண்டு.',
  'mars+rahu+sun': 'ஜாதகரின் சகோதரர்களுக்கும். தந்தைக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு பல் மற்றும் கண்ணில் ரோகமிருக்கும்.\n பல்வரிசை சரியாக அமைந்திருக்காது.\n திருமணத்தில் தடையுண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு அற்ப ஆயுள்.\n ஜாதகருக்கு நற்பண்புகள் இருக்காது.',
  'mars+rahu+moon': 'ஜாதகரின் சகோதரர்களுக்கும், தாய்க்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு பல் மற்றும் கண்ணில் ரோகமுண்டு.\n பல்வரிசை நன்றாக அமைந்திருக்காது.\n திருமணத்தில் தடையுண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு அற்ப ஆயுள்.\n ஜாதகருக்கு நற்பண்புகள் இருக்காது.',
  'mars+rahu+mercury': 'ஜாதகரின் சகோதரர்களிடையே ஒற்றுமை இருக்காது.\n சகோதரர்களுக்கு கண்டங்கள் கஷ்டங்கள் ஏற்படும்.\n பல்வரிசை நன்றாக அமைந்திருக்காது.\n திருமணத்தடை உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு அற்ப ஆயுள்.\n ஜாதகருக்கு நற்பண்புகள் இருக்காது.',
  'mars+rahu+jupiter': 'ஜாதகருக்கும், சகோதரர்களுக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு ஆயுள் குறைவு.\n ஜாதகருக்கு வாகனங்களால் விபத்து உண்டாகும்.\n ஜாதகருக்கு நெருப்பு மற்றும் ஆயுதங்களால் ஆபத்து உண்டு.\n ஜாதகருக்கு நற்குணங்கள் இருக்காது.',
  'mars+rahu+venus': 'ஜாதகரின் சகோதரர்களுக்கு பலவிதமான கஷ்டங்களும், கண்டங்களும் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு இப்பலன்கள் நடக்கும்.\n தாமதத்திருமணம், திருமண வாழ்க்கை சோபிக்காது.\n திருமணமே நடக்காமலும் போகலாம்.',
  'mars+rahu+ketu': 'ஜாதகரின் குடும்பத்தில் தகப்பனார் மற்றும் சகோதரர்களிடையே கருத்து வேறுபாடு இருக்கும்.\n ஒற்றுமை இருக்காது.\n ஜாதகருக்கு திருமணத்தில் தடையுண்டு. ஜாதகர் பெண்ணாக இருந்தால் இப்பலன்கள் நடக்கும். கணவருடன் கருத்து வேறுபாடு ஏற்படும்.',
  'mars+ketu+moon': 'ஜாதகரின் குடும்பத்தில் தாய்க்கும் சதோரர்களுக்குமிடையே கருத்து வேறுபாடு இருக்கும்.\n குடும்பத்தில் ஒற்றுமை இருக்காது.\n ஜாதகருக்கு திருமணத்தில் தடையுண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் இப்பலன்கள் கணவருக்கு நடக்கும்.\n கணவருடன் கருத்து வேறுபாடு ஏற்படும்.\n மூலவியாதி, கட்டிகள் போன்றவை தோன்றும்.',
  'mars+ketu+mercury': 'ஜாதகரின் சசோதரர்களிடையே சண்டை சச்சரவுகள் ஏற்படும்.\n நிலம் சம்பந்தமாக தகராறு ஏற்படும்.\n திருமணத்தில் தடை ஏற்படும்.\n திருமணம் ஆனாலும் விவாகரத்து ஏற்படுவதற்கு வாய்ப்புகள் உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் வேறு பெண்ணுடன் தொடர்பு வைத்திருப்பார்.\n இதனால் அடிக்கடி சண்டை சச்சரவுகள் ஏற்படும்.',
  'mars+ketu+jupiter': 'ஜாதகர் ஆன்மீகத்தில் ஈடுபாடு உள்ளவர்.\n பெண்களைக் கண்டால் வெறுக்கும் இயல்புள்ளவர்.\n சுவாசம்மற்றும் மூலவியாதி உள்ளவர்.',
  'mars+ketu+venus': 'ஜாதகர் பண விஷயமாக சகோதரர்களுடன் சண்டை சச்சரவு ஏற்படும்.\n கணவன், மனைவியிடையே பிரிவு ஏற்படும்.\n ஜாதகருக்கு உடம்பில் இரத்த ஓட்டத்தில்தடை ஏற்படும்.',
  'mars+ketu+saturn': 'ஜாதகரின் சகோதரர்களுக்கிடையே சண்டை சச்சரவு ஏற்படும்.\n திருமணத்தில் தடை ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவனுடன் கருத்து வேறுபாடு ஏற்படும்.',
  'mars+ketu+rahu': 'ஜாதகரின் சகோதரர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n திருமணத் தடை ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருடன் கருத்து வேறுபாடு ஏற்படும்.\n திருமணத் தடை ஏற்படும்.\n பெண்கள் கணவனோடு கருத்து வேறுபாடு கொள்வார்கள்.\n மூலவியாதி, கட்டிகள் போன்றவை உடலில் தோன்றும்.',
  'mercury+sun': 'ஜாதகரின் மாமன் புகழ்பெற்றவர்.\n சொந்தமாக நிலபுலன் உடையவர்.\n ஜாதகரும் புத்திசாலியாகவும், புகழ்பெற்றவராகவும் இருப்பார்.\n ஜாதகருக்கு தலையில் வழுக்கை இருக்கும்.',
  'mercury+moon': 'ஜாதகரின் மாமா நல்ல கலை ஞானம் உடையவர்.\n மென்மையாகப் பேசக் கூடியவர்.\n எப்பொழுதும்பயணம் செய்து கொண்டே இருப்பார்.',
  'mercury+mars': 'ஜாதகருக்கு கல்வியில் தடையுண்டு\n எப்பொழுதும் விவாதம் செய்து கொண்டே இருப்பார்.\n ஜாதகர் பொறியியல் துறையில் வல்லுனராக இருப்பார்.',
  'mercury+jupiter': 'ஜாதகர் உயர்கல்வி பெறுவார்.\n மிகவும் புத்திசாலியாக இருப்பார்.\n மென்மையானவராக இருப்பார்.\n சரளமாக, கவர்ச்சியாக பேசுவார்.\n நகைச்சுவை மன்னன், இளமையான தோற்றம்.\n வழுக்கை தலை. எல்லோரிடத்திலும் சமமாகப் பழகுவார்.',
  'mercury+venus': 'ஜாதகர் உயர்கல்வி பெறுவார்.\n ஜாதகரின் மனைவி படித்தவளாகவும்,\n பண்புள்ளவளாகவும் இருப்பார்.\n அழகாக இருப்பாள்.\n ஜாதகர் பணம் சேர்க்கும் வழிமுறைகளை நன்றாக அறிந்தவராக இருப்பார்.',
  'mercury+saturn': 'ஜாதகர் தொழில் நுட்பமறிந்தவராயிருப்பார்.\n சொந்த வியாபாரம் செய்வார்.\n நண்பர்கள் ஆதரவு தொழில்முறை கூட்டாளிகள் ஆதரவு எப்போதும் இருக்கும்.\n கல்வியில் தடை ஏற்படும்.',
  'mercury+rahu': 'ஜாதகர் மந்தபுத்தியுள்ளவர்.\n தோல் வியாதியுள்ளவர்.\n காது நோயுள்ளவர்.\n கல்வியில் தடை ஏற்படும்.\n அழகற்ற பெரிய நெற்றியை பெற்றிருப்பார்.\n ஜாதகர் பெரிய அளவில் வியாபாரத்தில் ஈடுபட்டிருப்பார்.',
  'mercury+ketu': 'ஜாதகருக்கு கல்வியில் தடையுண்டு.\n இதுபோன்ற அமைப்புள்ளவர்கள் தங்களுடைய 18, 24, 30,36 வயது காலங்களில் காதலில் ஈடுபட்டு, அதனாலே சண்டை சச்சரவுகள் ஏற்படும்.\n மனநிம்மதியை இழப்பர். காதலில் வெற்றியா, தோல்வியா என்பதை அறியமுடியாத நிலை.\n 36, 42, 48, 54 வயது காலங்களில் நிலம் சம்பந்தமாக தகராறு ஏற்படும்.\n இதே வயது காலங்களில் நண்பர்களுடன் சண்டை கருத்து வேறுபாடு தோன்றும்.\n தொழில் முறை கூட்டாளிகளுடன் கருத்து வேறுபாடு தோன்றி அது தகராறில் முடியும்.\n ஜாதகர் எண்ணெய் வளம் மற்றும் தோட்டக்கலை சம்பந்தமான கல்வி பயில்வார்.',
  'mercury+sun+moon': 'ஜாதகர் நல்ல புத்திசாலியாக இருப்பார்.\n ஜாதகர் சமூகவியல், பொருளாதாரம், அரசியல் சம்பந்தமான கல்வியைப் பெறுவார்.\n தகப்பனார் புத்திசாலியாக இருப்பார்.\n பேச்சாற்றல் உள்ளவராக ஜாதகர் இருப்பார்.',
  'mercury+sun+mars': 'ஜாதகர் பொறியியல் மற்றும் அறுவை சிகிச்சை செய்யும் மருத்துவம் சம்பந்தமான கல்வியைப் பெறுவார்.\n கல்வியில் தடை ஏற்பட வாய்ப்பு உண்டு.\n ஜாதகருக்கு தொழில்முறை கூட்டாளிகளுடன் கருத்து வேறுபாடு ஏற்பட்டு, அது ஒருபெரிய மனிதரால் தீர்த்து வைக்கப்படும்.',
  'mercury+sun+jupiter': 'ஜாதகர் உயர்ந்த கல்வியை பெறுவார்.\n மிகவும் புத்திசாலியாக இருப்பார்.\n கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களுடன், விருதுகளும் பெறுவார்.\n இதனால் இவருக்கு பேரும், புகழும் ஏற்படும்.\n தத்துவம் விஞ்ஞானம், சமூகவியல், பொறியியல், மருத்துவம் போன்ற கல்வியை பெறுவார்.\n கல்வி கேள்விகளில் எல்லா துறையிலும் சிறந்து விளங்குவார்.\n ஜாதகருடைய தந்தையார் புத்திசாலியாகவும், நல்ல குணமுள்ளவராகவும் இருப்பார்.',
  'mercury+sun+venus': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n தொழிற்கல்வியில் தேர்ச்சி பெறுவார்.\n பட்டு வளர்ப்பு, நிர்வாக பொறுப்பு சம்பந்தமான கல்வி, விசைத்தறி சம்பந்தமான படிப்பு.',
  'mercury+sun+saturn': 'ஜாதகர் தொழிற்கல்வி கற்பார்.\n நவீன மார்க்கமான மின்னணுவியல், கணிப்பொறியியல் போன்ற துறையில் தேர்ச்சி பெறுவார்.\n ஜாதகரின் தந்தையார் தொழில் விஷயங்களில் ஞானமுள்ளவராக இருப்பார்.\n ஜாதகருக்கு தகப்பனார் மூலம் சொந்தத் தொழில் அமையும் வாய்ப்பு உண்டு.',
  'mercury+sun+rahu': 'ஜாதகர் மின்னணுவியல் சம்பந்தமான கல்வி கற்பார் அல்லது இரசாயணம் சம்பந்தமான கல்வியைக் கற்பார்.\n ஜாதகருடைய தந்தையாருக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'mercury+sun+ketu': 'ஜாதகர் சட்டத்துறையில் கல்வி பயில்வார் அல்லது மருத்துவக் கல்வியில் தடை ஏற்படும்.\n தகப்பனாரின் சொத்து விஷயமாகத் தகராறு ஏற்படும்.\n பெண்கள் விஷயத்தில்காதல் தகராறு ஏற்படும்.',
  'mercury+moon+sun': 'ஜாதகர் சமூகவியல், பொருளாதாரம், அரசியல் போன்ற துறைகளில் கல்வி பயில்வார்.\n கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n ஜாதகரின் தாயார் புத்திசாலியாகவும், குடும்பத்தை நிர்வாகம் செய்வதில் திறமையுள்ளவராகவும் இருப்பார்.\n ஜாதகரின் தந்தையாருக்கு இருதார அமைப்பு ஏற்படலாம் அல்லது வேறு ஒரு பெண்ணிடம் தொடர்பு வைத்திருக்கலாம்.\n ஜாதகருக்கு தோல் வியாதி உண்டு.\n ஜாதகர் பெண்ணாக இருந்தால் கருப்பையில் கோளாறு உண்டு.',
  'mercury+moon+mars': 'ஜாதகர் தொழிற்கல்வி பயிலலாம்.\n கல்வியில் தடை ஏற்பட வாய்ப்பு உண்டு.\n சகோதரர்களிடையே ஏற்படும் சண்டை சச்சரவுகளில் தாய் மனநிம்மதியற்றிருப்பார்.\n ஜாதகர் நிலையில்லாத மனதை உடையவர்.\n ஜாதகருக்கு தோல்வியாதி உண்டு.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.\n அறுவை சிகிச்சை செய்து கொள்வார்.',
  'mercury+moon+jupiter': 'ஜாதகர் ரசாயணம் அல்லது மருத்துவம் சம்பந்தமான கல்வி பயில்வார்.\n ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n ஜாதகர் தூர தேசங்களுக்கு போய்வருவார்.\n ஜாதகரின் தாய் புத்திசாலியாகவும், நல்ல குணவதியாகவும் இருப்பார்.\n தாயாருக்கு தெய்வ பக்தி இருக்கும்.\n ஜாதகருக்கு தோல் வியாதி வரும்.\n ஜாதகருக்கு பேச்சுதிறமை இருக்கும்.',
  'mercury+moon+venus': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n இலக்கியம் சம்பந்தமான கல்வி பயிலலாம்.\n தோல் வியாதி மற்றும் வயிறு சம்பந்தமான பிணி ஏற்படும்.\n கலை, வங்கி, கட்டிடங்கள், விடுதி நிர்வாகம் சம்பந்தமான படிப்பு.',
  'mercury+moon+saturn': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n கணிதம், மின்னணுவியல், கணிப்பொறியியல் சம்பந்தமான கல்வி பயிலலாம்.\n ஜாதகர் தொழில் விஷயமாக பிரயாணங்கள் செய்வார்.\n ஜாதகர் பேச்சுத் திறமையுள்ளவர்.\n தோல் மற்றும் வயிறு சம்பந்தமானபிணி ஏற்படும்.\n தலைவலி போன்ற நோய்களும் ஏற்படலாம்.',
  'mercury+moon+rahu': 'ஜாதகர் வியாபாரம்.\n கணக்கியல், கட்டிடக்கலை சம்பந்தமான படிப்பு.\n ஜாதகர் மனநிலை சரியில்லாதவராக இருப்பார்.\n மனதில் அடிக்கடி இனம்புரியாத பயம் ஏற்படும்.\n புத்தி சுவாதீனமில்லாதவராக இருப்பார்.\n வயிறு மற்றும் தோல் சம்பந்தமான வியாதி ஏற்படும்.\n ஜாதகர் நீண்டதூரப் பயணங்கள் செய்வார்.\n ஜாதகருக்கு தண்ணீரில் கண்டம் உள்ளது.\n தொண்டையிலும் நோய் வரும்.',
  'mercury+moon+ketu': 'ஜாதகர் சட்டம், இரசாயணம் அல்லது மருத்துவம் சம்பந்தமான கல்வி பயில்வார்.\n மின்னியல் துறையிலும் கல்வி பயிலலாம்.\n ஜாதகருக்கு தோல் வியாதி உண்டு.\n ஜாதகர் காதல் விவகாரத்தில் ஈடுபட்டு தகராறு ஏற்படும்.\n நிலம், சொத்து சம்பந்தமான தகராறு ஏற்படும்.\n கல்வியில் தடை ஏற்படும்.\n ஜாதகருக்கு காதல் விவகாரங்களில் அவமானம் ஏற்படும்.\n கெட்ட பெயரும் வரும்.',
  'mercury+mars+sun': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n கல்வியில் தடை ஏற்படும்.\n சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n தொழில்முறை தோழர்களுடன் கருத்து வேறுபாடு ஏற்படும்.',
  'mercury+mars+moon': 'ஜாதகர் தொழில் கல்வி பயில்வார்.\n கல்வியில் தடை ஏற்படும்.\n சகோதரர்களிடையே ஒற்றுமை இருக்காது.\n ஜாதகருக்கு மனநிம்மதி இருக்காது.\n தொழில்முறை தோழர்களால் கஷ்டங்களும், அவமானமும் உண்டாகும்.',
  'mercury+mars+jupiter': 'ஜாதகர் தொழில் கல்வி பயில்வார்.\n கல்வியில் தடை ஏற்பட்டாலும் சிறிது காலத்திற்கு பின் கல்வியைத் தொடர்ந்து கற்கும் நிலை ஏற்படும்.\n ஜாதகர் சிறந்த பேச்சாளராக வருவார்.\n வாதம் புரிவதில் வல்லவராக இருப்பார்.',
  'mercury+mars+venus': 'ஜாதகர் தொழில்கல்வி பயில்வார்.\n கல்வியில் தடை ஏற்பட்டாலும் சிறிது காலத்திற்கு பின் கல்வியைக் கற்கும் நிலை ஏற்படும்.\n ஜாதகர் வாதம் புரிவதில் வல்லவனாக இருப்பார்.\n கணிதம், கணக்கியல், நிர்வாகம்சம்பந்தமான கல்வி.',
  'mercury+mars+saturn': 'ஜாதகருக்கு கல்வியில் தடை உண்டு.\n தொழிற்கல்வி பயிலலாம்.\n ஜாதகர் நல்ல பேச்சாளராக வருவார்.\n ஜாதகரின் சகோதரர்கள் கஷ்ட நிலையிலிருப்பார்.\n ஜாதகருக்கு திருமணத்தில் தாமதம் உண்பாகும்.\n ஜாதகர் பல்லில் ரோகமுள்ளவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு பலவிதமான கஷ்டங்கள் ஏற்படும்.',
  'mercury+mars+rahu': 'ஜாதகருக்கு கல்வியில் தடை ஏற்படும்.\n இரசாயணம் சம்பந்தமான கல்வி பயிலலாம்.\n சகோதரர்களுக்கு பலவிதமான கண்டங்களும், கஷ்டங்களும் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு பலவிதமான கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு பல்வரிசை நன்றாக இருக்காது.',
  'mercury+mars+ketu': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n கல்வியில் தடை ஏற்படும்.\n நிலம் சொத்து சம்பந்தமாக சகோதரர்களுடன் சண்டை சச்சரவுகள் உண்டாகும்.\n கணவன் மனைவிக்கிடையே கருத்துவேறுபாடு உண்டாகி மனமுறிவு ஏற்படும்.\n மூலவியாதி உண்டாகும்.',
  'mercury+jupiter+sun': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n நவீன மார்க்கத்தில் கல்வி பயிலும் நிலை உண்டாகும்.\n ஜாதகர் கடவுளின் அருளை பெற்றவராக இருப்பார்.\n இவருடைய பெயரில் சிவனும், விஷ்ணுவும் சேர்ந்திருப்பார்கள்.\n ஜாதகருக்கு எல்லாவிதமான நல்ல குணங்களும் இருக்கும்.\n ஜாதகர் தன்பேச்சு திறமையால் எல்லோரையும் கவர்வார்.',
  'mercury+jupiter+moon': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களும், விருதுகளும் பெறுவார்.\n பலதேசம் சுற்றி வருவார்.\n நவீன மார்க்கத்தில் கல்வி பயிலும் நிலை உண்டாகும்.\n ஜாதகர் மிகவும் புத்திசாலியாக இருப்பார்.\n ஜாதகர் பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகர் தன் பேச்சுத்திறமையால் எல்லோரையும் கவர்வார்.',
  'mercury+jupiter+mars': 'கல்வியில் தடை, பொறியியல், இயந்திரவியல் கல்வி, இயற்பியல், கட்டிடக்கலை (I.P.S ) உறுதியானகல்வி, உயர்கல்வி, நிதி, நீதி, ஆலோசனை வழங்கும் கல்வி, ஆசிரியர் பயிற்சி, முதல் மதிப்பெண், மதம் தத்துவம் சார்ந்த படிப்பு.',
  'mercury+jupiter+venus': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களும் விருதுகளும் பெறுவார்.\n நவீன மார்க்கத்தில் கல்வி பயிலலாம்.\n ஜாதகர் இளமையாகவும், கவர்ச்சியாகவும் இருப்பார்.\n ஜாதகரை பல பெண்கள் சூழ்ந்திருப்பார்கள்.\n ஜாதகருக்கு பேச்சுத்திறமை, நடிப்புத்திறமை போன்றவைகள் இருக்கும்.',
  'mercury+jupiter+saturn': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n ஜாதகருக்கு பேச்சுத் திறமை, எழுத்து திறமை, நிர்வாக திறமைகள் இருக்கும்.\n ஜாதகருக்கு வாழ்க்கையில் எந்தவித கஷ்டங்களும் வராது.\n சுமூகமான வாழ்க்கை அமையும்.\n பேரும் புகழும் உண்டாகும்.\n மருத்துவம், ஆசிரியர் பணி செய்வார்கள்.',
  'mercury+jupiter+rahu': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n நவீன மார்க்கத்தில் கல்வி பயில்வார்.\n பரதேசம் சென்றும் கல்வி பயில்வார்.\n ஜாதகருக்கு மூக்கில் கருப்பு மச்சம் இருக்கும்.\n ஜாதகருக்கு காலில் ரோகமுண்டாகும்.\n கால் பலவீனமாக இருக்கும்.\n வாதநோய் ஏற்படலாம்.\n வயிற்றில் கட்டிவளரும்.',
  'mercury+jupiter+ketu': 'ஜாதகர் சட்டத்துறையில் கல்வி பயில்வார்.\n மருத்துவ கல்வியும் பயில்வார்.\n காதல் விவகாரத்தில் தகராறு ஏற்படும்.\n நிலம் சம்பந்தமான விஷயத்திலும் தகராறு ஏற்படும்.\n தலையில் சுருண்ட கேசத்தை உடையவராக இருப்பார்.\n ஜாதகருக்கு ஆன்மீக ஈடுபாடு இருக்கும்.\n நரம்புதளர்ச்சி வாதநோய் போன்றவை ஏற்படும்.',
  'mercury+venus+sun': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களும், விருதுகளும் பெறுவார்.\n மருத்துவம் சம்பந்தமான கல்வி பயிலலாம்.\n ஜாதகருடைய மனைவி புத்திசாலியாகவும், நிர்வாகத் திறமையுள்ளவராகவும் இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் புத்திசாலியாகவும் நிர்வாகத் திறமையுள்ளவராகவும் இருப்பார்.',
  'mercury+venus+moon': 'ஜாதகர் கலை சம்பந்தமான கல்வி பயிலலாம்.\n தோல் வியாதி உடையவர்களாக இருப்பார்கள்.\n சதா காம எண்ணங்களிலேயே இருப்பார்கள்.\n ஜாதகர் ஆணானால் எப்பொழுதும் இவனை சுற்றி பெண்கள் கூட்டம் இருந்து கொண்டே இருக்கும்.',
  'mercury+venus+mars': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n சட்டமும் பயிலலாம்.\n ஜாதகர் ஆணானால் மனைவி புத்திசாலியாகயும், சற்று முன்கோபியாகவும் இருப்பார்.',
  'mercury+venus+jupiter': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களையும், பரிசுகளையும் பெறுவார்.\n ஜாதகருக்கு இருதார அமைப்பு ஏற்படலாம்.\n ஜாதகரின் மனைவி புத்திசாலியாகயும், நற்பண்புகள் உள்ளவராகவும் இருப்பாள்.\n ஜாதகர் பெண்ணாக இருந்தால் நல்ல புத்திசாலியாகவும், நற்பண்புகள் உள்ளவராகவும் இருப்பார்.\n சாந்தமாகவும், அமைதியாகவும் இருப்பார்.\n ஜாதகர் செல்வசெழிப்புள்ள குடும்பத்தில் பிறந்திருப்பார்.',
  'mercury+venus+saturn': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n தொழில் சம்பந்தமான கல்வி பயில்வார்.\n வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.\n ஜாதகரின் மனைவி சொந்த சம்பாத்தியம் உள்ளவர், புத்திசாலி.\n ஜாதகர் பெண்ணாக இருந்தால் புத்திசாலியாகவும், சொந்த சம்பாத்தியமுள்ளவராகவும் இருப்பார்.\n சற்று சோம்பேறியாக இருப்பார்.\n ஜாதகர் பிறந்ததும் குடும்பத்தில் செல்வம் பெருகும்.\n வீடு வாகனங்கள் எல்லா சொகுசு பொருட்களும் வரும்.',
  'mercury+venus+rahu': 'ஜாதகர் மின்னணுவியல் துறையில் கல்வி பயில்வார்.\n ஜாதகரின் மனைவி புத்திசாலியாக இருப்பார்.\n ஆனால் எப்பொழுதும் நோய்வாய்ப்பட்டிருப்பார்.\n ஜாதகர் திருட்டு வழியில் சம்பாதிப்பார்.',
  'mercury+venus+ketu': 'ஜாதகர் சட்டம் பயிலுவார் அல்லது மருத்துவம் பயில்வார்.\n ஜாதகருக்கு தோல் சம்பந்தமான வியாதி இருக்கும்.\n இரத்தம் சம்பந்தமான நோயும் வரும்.\n இவர்கள் தங்கள் இளம் வயதில் காதல் வயப்பட்டு, அதனால் சண்டை சச்சரவுகள் உண்டாகும்.\n நிலம், சொத்து, பணம் சம்பந்தமாக சண்டை சச்சரவுகள் ஏற்படும்.',
  'mercury+saturn+sun': 'ஜாதகர் தொழிற்கல்வி பயில்வார்.\n ஜாதகர் நல்ல பேச்சாளராகவும், எழுத்தாளராகவும் இருப்பார்.\n அரசு உத்யோகம் அமையும் வாய்ப்பு உண்டு.\n ஜாதகர் ஆரம்பகாலத்தில் கஷ்டப்பட்டாலும் பின்னாளில் பேரும் புகழும் அடைவார்.\n சொந்த உத்யோகமும் அமையலாம்.',
  'mercury+saturn+moon': 'ஜாதகர் கலை சம்பந்தமான கல்வி பயில்வார்.\n கற்பனை சக்தியுள்ளவராக இருப்பார்.\n கதை, காவியங்கள் புனைவதில் வல்லவராக இருப்பார்.\n தொழிலிலோ, உத்யோகத்திலோ இடமாற்றம் எப்பொழுதும் இருக்கும்.\n தாய்க்கு உடல்நலம் சரியாக இருக்கும்.\n ஜாதகருக்கும் மனசஞ்சலம் வயிற்றில் பிணி, அவமானங்கள் கெட்டபயர்கள் உண்டாகும்.',
  'mercury+saturn+mars': 'ஜாதகர் பொறியியல் துறையில் கல்வி பயில்வார்.\n தொழில்வகையில் கஷ்டங்கள் இருந்தாலும், நண்பர்கள் உதவி செய்வார்கள்.\n சொந்தத் தொழில் அமையும் வாய்ப்பு உண்டு.\n ஜாதகர் நல்ல பேச்சாளராக இருப்பார்.\n சகோதரர்களிடையே ஒற்றுமை இருக்காது.\n ஜாதகர் பல்லில் ரோகமுடையவர்.\n திருமணம் தாமதமாகும்.',
  'mercury+saturn+jupiter': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களும், பரிசுகளும் பெறுவார்.\n பேச்சுதிறமை.\n எழுத்துத்திறமையும் இருக்கும்.\n கௌரமான தொழிலோ, உத்யோகமோ அடைவார்.\n எல்லோருடைய ஆதரவும் இவருக்கு இருக்கும்.\n வாழ்க்கையில் எந்த பிரச்சனையும் இல்லாமல் சுகமான சுமூகமான நிலையில் இருப்பார்.\n வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.\n சொந்தவீடு, வாகனம் அமையும்.\n வணிகவியல், நிர்வாக பொறுப்பு.',
  'mercury+saturn+venus': 'ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.\n பல பட்டங்களும், பரிசுகளும் பெறுவார்.\n பல கலைகளில் திறமையுள்ளவராக இருப்பார்.\n நல்ல உத்யோகமோ, தொழிலோ அமையும்.\n சொந்தமாகவும் தொழில் செய்வார்.\n ஏராளமாக சம்பாதிப்பார்.\n எல்லா சுகங்களையும் அனுபவிப்பார்.\n எல்லாவிதமான சொகுசு பொருட்களையும் அனுபவிப்பார்.',
  'mercury+saturn+rahu': 'ஜாதகரின் கல்வியில் எந்த குறையும் இருக்காது.\n பெரிய அளவில் சொந்தத் தொழில் செய்யும் நிலை உருவாகும்.\n ஜாதகரின் காலில் \nநரம்பு தளர்ச்சி, வாதம் போன்ற நோய் உண்டாகும்.\n காது கேட்பதிலும் குறை இருக்கலாம்.\n திரைப்படகல்வி, புகைப்படங்கள், கணிப்பொறியியல் துறையில் ஆர்வம் இருக்கும்.',
  'mercury+saturn+ketu': 'ஜாதகர் சட்டம் பயில்வார்.\n சொந்தத் தொழில் செய்வார்.\n ஆன்மீகத்தில் ஈடுபாடு இருக்கும்.\n வேதங்கள் கற்றுணர்வார்.\n நிலம், சொத்து சம்பந்தமாக தகராறு ஏற்படும்.\n காதல் விவகாரங்களில் ஈடுபட்டு தகராறு ஏற்படலாம்.',
  'mercury+rahu+sun': 'ஜாதகருக்கு கல்வியில் தடை ஏற்படும்.\n ஜாதகர் மந்தபுத்தி உள்ளவராக இருப்பார்.\n கண்ணுக்கு அருகில் ஒரு மச்சம் இருக்கும்.\n தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மின்னணுவியல் துறையில் ஆர்வம் இருக்கும்.',
  'mercury+rahu+moon': 'ஜாதகருக்கு கல்வியில் தடை உண்டாகும்.\n ஜாதகர் மனநோயாளியாக இருப்பார்.\n தாய்க்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n உடம்பில் பல இடங்களில் மச்சமிருக்கும்.\n தோல் வியாதி இருக்கும்.\n மின்னணுவியல் துறையில் தேர்ச்சிபெறுவார்.',
  'mercury+rahu+mars': 'ஜாதகர் கல்வியில் தடை ஏற்படும்.\n மின்னணுவியல் துறையில் கல்வி பயில்வார்.\n சகோதரர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n புருவத்தில் மச்சமிருக்கும்.\n வாகனங்கள் சம்பந்தமான படிப்பு.',
  'mercury+rahu+jupiter': 'ஜாதகர் நவீன மார்க்கத்தில் கல்வி கற்பார்.\n விண்ணியல், மின்னணுவியல் துறைகளில் கல்வி கற்பார்.\n ஜாதகருக்கு கண்டங்கள் ஏற்படும்.\n நரம்பு தளர்ச்சி மற்றும் வாதநோய் உண்டாகும்.\n கன்னத்தில் அழகான மச்சமிருக்கும்.',
  'mercury+rahu+venus': 'ஜாதகர் உறவு உண்டு.\n கவர்ச்சியானவர், வசதியானவர், ஆடம்பரமான வாழ்க்கை வாழ்வார்.\n கலைகளில் ஆர்வம் இருக்கும்.\n சொகுசான வாழ்க்கை வாழ்வார்.\n அழகான முகத்தோற்றம் உள்ளவர்.\n மாமன் ஆதரவு உண்டு.\n அன்னிய தேசத்தில் வாழ்வார்கள்.\n அன்னிய தேசத்தாருடன் பழக்க வழக்கம் இருக்கும்.\n போதை பழக்கம் இருக்கும்.\n கண்டம் ஏற்படும்.\n இடம் வீட்டுமாறுவார்கள்.',
  'mercury+rahu+saturn': 'ஜாதகருக்கு தாடையில் மச்சமிருக்கும்.\n ஜாதகர் மந்தபுத்தி உள்ளவராக இருப்பார்.\n பெரிய அளவில் சொந்தமாகத் தொழில் செய்வார்.',
  'mercury+ketu+sun': 'ஜாதகர் கல்வியில் தடையுண்டாகும்.\n தகப்பனாருக்குச் சொந்தமான நிலம் உண்டு.\n சொத்து சம்பந்தமாக தகராறு உண்டாகும்.\n இளம்வயதில் ஜாதகர் காதல் வயப்படுவார்.\n காதலியுடன் கருத்து வேறுபாடு கொண்டு பிரிய நேரிடலாம்.',
  'mercury+ketu+moon': 'ஜாதகர் கல்வியில் தடையுண்டாகும்.\n தாய்க்கு சொந்தமான நிலம், சொத்து சம்பந்தமாக தகராறு உண்பாகும்.\n ஜாதகர் இளம் வயதில் காதல் வயப்படுவார்.\n பெண்களால் கெட்ட பெயரும் அவமானமும் உண்டாகும்.\n ஜாதகர் தோல்வியாதி உடையவர்.',
  'mercury+ketu+mars': 'ஜாதகரின் சகோதரர்களிடையே சண்டை சச்சரவு உண்டாகும்.\n கணவன், மனைவி இடையே கருத்து வேறுபாடு தோன்றி பிரிய நேரிடலாம்.\n காதல் விவகாரத்தில் தோல்வி உண்டாகும்.\n நிலம் விவகாரத்தில் தோல்வி உண்டாகும்.\n நிலம், சொத்து சம்பந்தமாக தகராறு ஏற்படும்.\n கல்வியில் தடையுண்டாகும்.\n பொறியியல், தையல், நெசவு, ஜவுளி சம்பந்தமான கல்வி.',
  'mercury+ketu+jupiter': 'ஜாதகருக்கும் நண்பர்களுக்கும் இடையே கருத்து வேறுபாடு உண்டாகும்.\n காதல் விவகாரத்தில் சண்டை சச்சரவு உண்டாகும்.\n நிலம், சொத்து சம்பந்தமாக தகராறு உண்டாகும்.\n மருத்துவம் சம்பந்தமான கல்வி.',
  'mercury+ketu+venus': 'ஜாதகர் இரண்டு பெண்களிடையே சிக்கி தவிப்பார்.\n பணம், சொத்து, நிலம் சம்பந்தமாக தகராறு உண்டாகும்.\n கணவன் மனைவியருக்கிடையே கருத்து வேறுபாடு உண்டாகும்.\n காதல் விவகாரத்தில் சண்டை சச்சரவு உண்டாகும்.',
  'mercury+ketu+saturn': 'ஜாதகர் தொழில்முறை கூட்டாளிகளுடன் கருத்து வேறுபாடு ஏற்படும்.\n நிலம், சொத்து சம்பந்தமான தகராறு உண்டாகும்.\n காதல் விவகாரத்தில்தகராறு உண்டாகும்.',
  'mercury+ketu+rahu': 'ஜாதகர் காதல் விவகாரத்தில் தகராறு.\n சொத்து தகராறு ஏற்படலாம்.\n மனைவி அதிகார தோரணை உள்ளவள்.',
  'jupiter+sun': 'ஜாதகர் நல்ல புகழ்பெற்றவராக இருப்பார்.\n இரக்க குணம் உள்ளவராகவும் கடவுள் பக்தி உடையவராகவும் இருப்பார்.\n அரசு ஆதரவு முழுமையாக இருக்கும்.\n தர்ம குணம் உள்ளவர்.\n அவர் புகழ் என்றும் நிலைத்து நிற்கும்.',
  'jupiter+moon': 'ஜாதகர் எப்பொழுதும் மன சஞ்சலத்தோடு இருப்பார்.\n தர்ம குணம் உள்ளவர்.\n புகழ் அடைவார்.\n தீர்த்தயாத்திரைகள் நிறைய செய்வார்.\n எப்பொழுதும் பயணம் செய்து கொண்டே இருப்பார்.',
  'jupiter+mars': 'ஜாதகர் எதையும் நேரடியாகப் பேசக்கூடியவர்.\n இரத்த அழுத்தம் அதிகமாக இருக்கும்.\n இதய நோய் உள்ளவர்.\n சிறுவிஷயம் என்றாலும் உரக்கப்பேசுவார்.\n கோபப்படுவார்.\n எல்லோரிடத்திலும் சண்டை போடுவார்.',
  'jupiter+mercury': 'ஜாதகர் மிகவும் புத்திசாலி.\n நகைச்சுவையாகவும் சரளமாகவும் பேசுவார்.\n எல்லோரிடமும் சமமாகப் பழகுவார்.\n கல்வி கேள்விகளில் நல்ல புலமை இருக்கும்.\n பெண்கள் மீது மோகம் உள்ளவர்.',
  'jupiter+venus': 'ஜாதகர் மிக அழகாக இருப்பார்.\n கவர்ச்சியாக இருப்பார்.\n அழகான மூக்கு, கன்னங்கள் இருக்கும்.\n இனிமையான குரல் வளமிருக்கும்.\n காம உணர்வு அதிமாக இருக்கும்.\n மது மற்றும் போதை பொருட்கள் மீது நாட்டமிருக்கும்.\n சுவையான உணவு வகைகளை விரும்பி சாப்பிடுவார்.\n சொகுசான, சுகமான வாழ்க்கையை விரும்புவார்.\n பொண்டாட்டிதாசன், அலங்காரப்பிரியர்.\n வாசனை திரவியங்களை உபயோகிப்பார்.\n செல்வம், செல்வாக்கு உள்ளவர்.\n கலைத்துறையில் நாட்டமிருக்கும்.\n நடிப்பு, நாட்டியம், இசை, சங்கீதம் போன்றவற்றில் ஈடுபாடு இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் ஒழுக்கமான பெண்ணாக இருப்பார்.\n எல்லா நல்ல குணங்களும் இருக்கும்.\n தெய்வபக்தி நிரம்பியவர்.',
  'jupiter+saturn': 'ஜாதகர் அமைதியானவர்.\n கௌரவமான உத்யோகத்தில் இருப்பார்.\n உயர் அதிகாரிகளின் அன்பையும், ஆதரவையும் பெற்றிருப்பார்.\n உத்யோகத்தில் எந்த தடையுமில்லாமல் படிப்படியாக உயர்வு பெற்று நிர்வாகப் பொறுப்பேற்கும் நிலைக்கு உயர்வார்.\n புகழ்பெற்ற மனிதராக இருப்பார்.\n தன் கடமைகளைச் சரிவர நிறைவேற்றுவார்.\n உத்யோகமானாலும் சரி, தொழிலானாலும் சரி நேர்மையுடன் நடந்து கொள்வார்.\n இதுபோன்ற அமைப்புடையவர்கள் வாழ்க்கையில் எந்த கஷ்டமில்லாமல் கடைசிவரை சுமூகமான வாழ்க்கையை அடைவார்.',
  'jupiter+rahu': 'ஜாதகருக்கு ஆயுள் குறைவு.\n பிறக்கும் போது பெரிய கண்டத்திலிருந்து தப்பித்திருப்பார்.\n சோம்பேறியாக இருப்பார்.\n பெரிய அல்லது அழகற்ற மூக்கையுடையவர்.\n பொய் சொல்வார்.\n ஏமாற்று வேலைகள் எல்லாம் செய்வார்.\n நடிப்பில் மிக கில்லாடியாக இருப்பார்.\n பார்ப்பதற்கு மிகவும் சாதுபோன்று இருப்பார்.\n ஆனால் வஞ்சகராக இருப்பார்.\n ஜாதகர் தேசம் வீட்டு தேசம் போவார்.\n வாயு சம்பந்தமான பிணியிருக்கும்.\n மூட்டுவலி, கைகால் உளைச்சல் போன்ற நோய்களும் வரும்.',
  'jupiter+ketu': 'ஜாதகர் விரக்தி மனப்பான்மையுடன் இருப்பார்.\n வாழ்க்கையில் எந்த பிடிப்பும் இருக்காது.\n எப்பொழுதும் ஆன்மீக சிந்தனையில் இருப்பார்.\n சன்யாசி போல இருப்பார்.\n இந்த பிறவியிலேயே இவர் முக்தி அடைவார்.\n நரம்புத்தளர்ச்சி, மூச்சு விடுவதில் கஷ்டம் போன்ற பிணிகள் இருக்கும்.',
  'jupiter+sun+moon': 'ஜாதகர் தைர்யமானவர்.\n தெய்வ பக்தியுள்ளவர்.\n சத்தியவான்.\n புகழுடையவர்.\n தர்ம குணமுள்ளவர்.\n ஜாதகரின் தந்தையார் தெய்வ பக்தியுள்ளவர்.\n நற்பண்புகள் உள்ளவர்.\n பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகரின் தாய் நிர்வாகத்திறமையுள்ளவர்.',
  'jupiter+sun+mars': 'ஜாதகர் தைர்யமானவர்.\n நிர்வாகத் திறமையுள்ளவர்.\n முன்கோபி.\n பிறரால் எளிதில் ஏமாற்றப்படுவார்.\n ஜாதகருக்கு இரத்தம் சம்பந்தமான வியாதி வரும்.\n ஜாதகர் மகன் திறமைசாலியாக இருப்பார்.\n ஜாதகரின் தந்தை திறமைசாலியாகவும் முன்கோபியாகவும் இருப்பார்.',
  'jupiter+sun+mercury': 'ஜாதகர் தைர்யமானவர்.\n புத்திசாலி, புகழுடையவர்.\n பேச்சு வன்மையுள்ளவர்.\n தன்பேச்சு திறமையால் எல்லோரையும் கவர்வார்.\n ஜாதகர் தந்தை நற்குணங்கள் உள்ளவராகவும், புத்திசாலியாகவும் இருப்பார்.\n ஜாதகரின் மகன் புத்திசாலியாகவும் நற்பண்புகள் உள்ளவராகவும் இருப்பார்.',
  'jupiter+sun+venus': 'ஜாதகர் தைர்யமானவர்.\n கலை ஆர்வம் மிக்கவர்.\n புகழுடையவர்.\n இயல், இசை, நாடகங்களில் சிறந்து விளங்குவார்.\n ஜாதகரின் தந்தையார் செல்வந்தராகவும்.\n நற்குணங்கள் உள்ளவராகவும் இருப்பார்.\n ஜாதகரின் மனைவி நிர்வாகத்திறமையுள்ளவராக இருப்பார்.\n ஜாதகருக்கு குழந்தைகள் பிறப்பது கடினம்.',
  'jupiter+sun+saturn': 'ஜாதகர் தைர்யமானவர்.\n புகழுடையவர்.\n அரசு உத்யோகமோ, அரசாங்க ஆதரவோ கிடைக்கும்.\n தனது உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n தந்தையார் செய்த தொழிலையே ஜாதகரும் செய்யலாம்.',
  'jupiter+sun+rahu': 'ஜாதகருக்கும் அவர் தந்தைக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் கஷ்டப்பட்டு வாழ்க்கையில் முன்னேறுவார்.\n ஜாதகருக்கு குழந்தை பிறப்பதில் தோஷம் உண்டு.\n ஆண் குழந்தைகளுக்கு கண்டங்கள் ஏற்படும் அல்லது அடிக்கடி நோய்வாய்ப்படுவார்கள்.',
  'jupiter+sun+ketu': 'ஜாதகர் ஆன்மீக ஈடுபாடு உடையவர்.\n மோட்சத்தை அடைவார்.\n ஜாதகரின் தந்தை தெய்வ பக்தியுள்ளவர்.\n ஜாதகருக்கு குழந்தை பிறப்பதில் தடை உண்டு.\n ஜாதகர் புகழுடையவர்.',
  'jupiter+moon+sun': 'ஜாதகர் தர்ம குணமுள்ளவர்.\n புகழுடையவர்.\n நிர்வாகத் திறமையுள்ளவர்.\n பிறந்த இடம் வீட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகரின் தாய் தெய்வ பக்தியுள்ளவர்.\n நற்பண்புகள் உடையவர்.\n நிர்வாகத் திறமை உள்ளவர்.\n தாயார் தைர்யசாலியாக இருப்பார்.\n ஜாதகர் பருத்த சரீரத்தை பெற்றிருப்பார்.',
  'jupiter+moon+mars': 'ஜாதகர் சலனப்புத்தி உள்ளவராக இருப்பார்.\n பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகரின் தாய் தெய்வ பக்தியுள்ளவர்.\n தைர்யசாலி சற்று முன்கோபி.\n ஜாதகர் பருத்த சரீரத்தை உடையவர்.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.',
  'jupiter+moon+mercury': 'ஜாதகர் புத்திசாலியாக இருப்பார்.\n பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n ஜாதகரின் தாய் தெய்வ பக்தியுள்ளவர்.\n புத்திசாலி.\n ஜாதகர் தோல் வியாதி உடையவர்.\n பெண்கள் ஜாதகரை மிகவும் விரும்புவார்கள்.',
  'jupiter+moon+venus': 'ஜாதகர் பருத்த சரீரத்தை உடையவர்.\n உணவு வகைகளின் மீது பிரியமுள்ளவர்.\n காம உணர்வும், எண்ணங்களும் அதிகமாக இருக்கும்.\n கற்பனையில் மூழ்கிவிடும் தன்மையுடையவர்.\n கலைத் துறையில் நாட்டமுள்ளவர்.\n ஜாதகரின் தாய் தெய்வ பக்தியுள்ளவர்.\n வயிற்றில் பிணி உள்ளவர்.\n ஜாதகருக்கு வயிற்றில் கோளாறு உண்டு.',
  'jupiter+moon+saturn': 'ஜாதகர் தான் பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.\n தொழில் விஷயமாக அடிக்கடி பிரயாணம் செய்ய வேண்டிய நிலை ஏற்படும் அல்லது அடிக்கடி இடம் மாற்றம் உண்டாகும்.\n ஜாதகர் ஜோதிடம், ஆன்மீகம் போன்றவற்றில் ஈடுபாடு வைத்திருப்பார்.',
  'jupiter+moon+rahu': 'ஜாதகருக்கு நீரில் கண்டமுண்டு.\n தாய் அடிக்கடி நோய்வாய்ப்படுவார்.\n ஜாதகருக்கு அம்மை வைசூரி போன்ற நோய்கள் வரும்.\n ஜாதகர் வெளிநாடு செல்லும் யோகம் உண்டு.\n ஜாதகர் பரதேசத்தில் குடியேறும் நிலையும் ஏற்படலாம்.\n வயிற்றுபிணியும் உண்டு.',
  'jupiter+moon+ketu': 'ஜாதகர் ஆன்மீக ஈடுபாடு உள்ளவர்.\n கடவுள் அருளை பெற்றவர்.\n முக்காலத்தையும் உணர்வார்.\n முனிவனாவார்.\n ஜாதகருக்கு சுவாசம் சம்பந்தமான பிணி வரும்.\n ஜாதகருடைய தாய் தெய்வபக்தியுள்ளவர்.\n வயிற்று பிணியும் உண்டு.',
  'jupiter+mars+sun': 'ஜாதகர் தைர்யமானவர்.\n சுறுசுறுப்பானவர்.\n நிர்வாகத் திறமை உள்ளவர்.\n ஆனால் முன்கோபியாகவும், ஆத்திரப்படுபவராகவும் இருப்பார்.\n ஜாதகருக்கு உடலில் உஷ்ணம் அதிகமாக இருக்கும்.\n இருதயம், இரத்தம் சம்பந்தமான நோய் வரும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நற்பண்புகள் உள்ளவர்.\n தைர்யசாலி, நிர்வாகத் திறமை உள்ளவர்.',
  'jupiter+mars+moon': 'ஜாதகர் மனசஞ்சலம் உடையவர்.\n எளிதில் உணர்ச்சி வசப்படுவார்.\n ஜாதகருடைய ஒரு சகோதரர் வேறு இடத்தில் குடியேறுவார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நற்பண்புகள் உள்ளவர்.\n அடிக்கடி பயணம் மேற்கொள்வார்.',
  'jupiter+mars+mercury': 'ஜாதகர் தைர்யமானவர்.\n வாக்குவன்மையுள்ளவர்.\n மேடை பேச்சாளராக வருவார்.\n புத்திசாலியாகவும் இருப்பார்.\n வாதம் செய்வதில் சிறந்தவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் நற்குணங்கள் உடையவர்.\n புத்திசாலி.',
  'jupiter+mars+venus': 'ஜாதகர் அழகான கட்டுடலை உடையவர்.\n ஒருவித வசீகத் தோற்றமுடையவர்.\n பெண்கள் இவரை மிகவும் விரும்புவார்கள்.\n ஜாதகருக்கு காம உணர்வு அதிகமாக இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் அழகாகவும் நற்குணங்களுடையவராகவும் இருப்பார்.\n பண வசதியுள்ளவராகவும் இருப்பார்.\n கலைத்துறையில் நாட்டமிருக்கும்.',
  'jupiter+mars+saturn': 'ஜாதகர் தைர்யமானவர், திறமைசாலி, யாருக்கும் அடிபணியமாட்டார்.\n பிடிவாத குணமுள்ளவர்.\n தொழில் வகையில் எதிரிகள் மூலம் தொல்லைகள் வரும்.\n தன் தகுதிக்கு ஏற்ற ஊதியம் கிடைப்பதில் எதிரிகள் தடையாக இருப்பார்கள்.\n இதனால் இவர் தன் தொழிலை அடிக்கடி மாற்ற வேண்டிய நிலை ஏற்படலாம்.',
  'jupiter+mars+rahu': 'ஜாதகர் முன்கோபி, நற்பண்புகள் இல்லாதவர்.\n ஆத்திரக்காரர்.\n ஆதிக்க எண்ணமுள்ளவர்.\n ஜாதகருக்கு நெருப்பு, வாகனங்கள் மற்றும் ஆயுதங்களால் அபாயம் ஏற்படும்.\n ஜாதகருக்கு உடலில் வெட்டு காயங்கள் ஏற்படும்.\n கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவனை மதிக்க மாட்டார்.\n கணவனுக்கு கண்டங்கள் ஏற்படும்.',
  'jupiter+mars+ketu': 'ஜாதகர் வீர சன்யாசி, பெண் வாசனை ஏற்க மாட்டார்.\n வைராக்யமுள்ளவர்.\n மனைவியைத் திருப்திபடுத்த முடியாதவர்.\n வெட்டுக் காயம், மூலவியாதியுள்ளவர்.\n ஆன்மீக ஈடுபாடுள்ளவர்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவனுக்கு தடை உண்டு.',
  'jupiter+mercury+ketu': 'ஜாதகர் ஆன்மீக ஈடுபாடு உடையவர்.\n வேதபாடங்களைக் கற்றுணர்வார்.\n சொத்து சம்பந்தமான தகராறு இருக்கும்.\n வசீகரத்தோற்றமுடையவர்.\n ஜாதகருக்கு கல்வியில் தடையுண்டு.\n சட்டத்துறையில் கல்வி பயிலலாம்.',
  'jupiter+mercury+sun': 'நிபுணத்துவ யோகம் உடைய குழந்தைகள்.\n குழந்தைகளால் நன்மை ஏற்படும்.\n குழந்தைகளுக்கு கல்வி மூலம் வெற்றியும், பதவியும் கிடைக்கும்.',
  'jupiter+mercury+moon': 'ஜாதகர் புத்திசாலி.\n கற்பனா சக்தி மிகுந்தவர்.\n ஜாதகர் நண்பர்களால் கெட்ட பெயர் வாங்குவார்.\n தோல் வியாதி உடையவர்.\n ஜாதகர் பிரயாணம் செய்வதில் விருப்பமுள்ளவர்.\n நீண்ட தூரப்பயணங்கள் மேற்கொள்வார்.',
  'jupiter+mercury+mars': 'ஜாதகர் புத்திசாலி, தைர்யசாலி. பேச்சாற்றல் மிக்கவர்.\n வாதம் புரிவதில் வல்லவர்.\n ஜாதகருக்கு கல்வியில் தடை உண்டாகும்.\n சிறிது கால இடைவெளிக்கு பின் கல்வியை தொடரும் நிலை ஏற்படும்.\n ஜாதகருக்கு நெற்றியில் ஒரு தழும்பு இருக்கும்.',
  'jupiter+mercury+venus': 'ஜாதகர் அழகானவர்.\n கவர்ச்சியானவர்.\n இயல், இசை, நாடகம் போன்ற கலைத்துறையில் ஈடுபாடு உள்ளவர்.\n பேச்சில் ஒரு கவர்ச்சித் தன்மை இருக்கும்.\n ஜாதகரைச் சுற்றி பல பெண்கள் இருப்பார்கள்.',
  'jupiter+mercury+saturn': 'ஜாதகர் மிகவும் புத்திசாலியாக இருப்பார்.\n தொழிலில் ஆர்வமுள்ளவர்.\n மிகவும் தந்திரசாலியாக இருப்பார்.\n பேச்சிலேயே மக்களை மயக்கும் திறமையுள்ளவர்.\n வாணியத்தில் கொடிகட்டிப் பறப்பார்.\n எப்பொழுதும் நண்பர்கள் மத்தியிலேயே இருப்பார்.\n நண்பர்களின் உதவியும் ஆதரவும் எப்பொழுதும் கிடைக்கும்.\n பெண் நண்பர்களால் நன்மை அடைவார்.\n பேச்சாற்றல் எழுத்தாற்றல் போன்றவை இருக்கும்.',
  'jupiter+mercury+rahu': 'ஜாதகர் தந்திரசாலியாக இருப்பார்.\n எல்லோரையும் எளிதாக ஏமாற்றிவிடுவார்.\n பெண்களிடம் ரகசிய தொடர்பு வைத்திருப்பார்.\n ஜாதகருக்கு மூக்கின் மீது ஒரு மச்சமிருக்கும்.\n நரம்பு தளர்ச்சி, வாதம் போன்ற நோய்கள் வரும்.\n நடிப்பு திறமையுள்ளவர்.',
  'jupiter+venus+sun': 'ஜாதகர் செல்வந்தராக இருப்பார்.\n நிர்வாகத் திறமை உள்ளவர்.\n புகழ் உடையவர்.\n அழகான தோற்றம் உடையவர்.\n கலைத்துறையில் புகழ் அடைவார்.\n புத்ரதோஷம் உடையவர்.\n ஜாதகர் மனைவி நற்பண்புகள் உடையவர்.\n நிர்வாகத்திறமையுள்ளவர்.',
  'jupiter+venus+moon': 'ஜாதகர் காம உணர்வு மிக்கவர்.\n எதிர்பாலார் மீது அதிக மோகம் வைத்திருப்பார்.\n ஜாதகருக்கு வயிற்றில் பிணி உண்டு.\n சுவாசம் சம்பந்தமான பிணியும் உண்டு.\n ஜாதகருடைய மனைவி அழகானவள்.\n சாந்த குணமுடையவள்.\n நிலையற்ற மனமுடையவள்.',
  'jupiter+venus+mars': 'ஜாதகர் காம உணர்ச்சி அதிகமானவர்.\n ஜாதகரின் மனைவி ஆதிக்க எண்ணமுடையவள்.\n ஜாதகருடைய பற்கள் மிக அழகாக இருக்கும்.\n ஜாதகர் அழகான கட்டுமஸ்தான உடம்பை பெற்றிருப்பார்.',
  'jupiter+venus+mercury': 'ஜாதகர் அழகான இளமையான தோற்றமுடையவர்.\n ஜாதகருக்கு கலைத்துறையில் நாட்டமிருக்கும்.\n ஜாதகர் பேச்சாற்றல் மற்றும் எழுத்தாற்றல் மிக்கவர்.\n ஜாதகரை பெண்கள் மிகவும் விரும்புவார்கள்.\n ஜாதகரின் மனைவி மிகவும் புத்திசாலியாக இருப்பாள்.\n மென்மையானவள்.\n நற்பண்புடையவள்.\n ஜாதகர் கல்வி கேள்விகளில் சிறந்து விளங்குவார்.',
  'jupiter+venus+saturn': 'ஜாதகர் மிகப்பெரிய செல்வந்தனாக இருப்பார்.\n கலைத்துறையில் ஈடுபாடு உள்ளவராக இருப்பார்.\n ஜாதகர் கௌரவமான உத்யோகத்தில் இருப்பார்.\n ஜாதகருடைய மனைவி சுயமாக சம்பாதிப்பாள்.\n ஜாதகர் வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.',
  'jupiter+venus+rahu': 'ஜாதகர் செல்வ செழிப்பிலுள்ள குடும்பத்தில் பிறந்தவர்.\n ஜாதகருக்கு கன்னத்தில் அழகான மச்சமிருக்கும்.\n ஜாதகர் கலைத்துறையில் மிக உயர்ந்த நிலையை அடைவார்.\n ஜாதகருக்கும் அவர் மனைவிக்கும் அடிக்கடி கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n அடிக்கடி நோய்வாய்ப்படுவார்கள்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.',
  'jupiter+venus+ketu': 'ஜாதகர் மற்றும் அவர் மனைவி இருவரும் தெய்வ பக்தி உள்ளவர்கள்.\n குடும்பத்தில் ஒற்றுமையிருக்காது.\n குடும்பத்தில் சொத்து மற்றும் பணம் சம்பந்தமாக தகராறு இருக்கும்.\n ஜாதகரின் மனைவி சோம்பேறியாக இருப்பாள்.\n வாழ்க்கையில் எந்த பிடிப்பும் இருக்காது.',
  'jupiter+saturn+sun': 'ஜாதகர் உத்யோகத்திலோ அல்லது தொழிலிலோ உயர்ந்த நிலையை அடைவார்.\n எப்பொழுதும் கடமையே கண்ணாக இருப்பார்.\n அரசாங்க உத்யோகம் கிடைக்கும்.\n அரசு அதிகாரிகள் அல்லது அரசியல்வாதிகள் ஆதரவு கிடைக்கும்.\n ஜாதகருக்கும் அவர் தந்தைக்கும் இடையே கருத்து வேறுபாடு இருக்கும்.',
  'jupiter+saturn+moon': 'ஜாதகருக்கு கௌரவமான உத்யோகம் கிடைக்கும்.\n உத்யோகத்தில் அடிக்கடி மாற்றமுண்டாகும்.\n ஜாதகர் தன் உத்யோகத்திற்காக வேறு இடம் குடியேற நேரிடும்.\n ஜாதகர் நிலையற்ற மனமுடையவராக இருப்பார்.\n ஜாதகர் திரவ வாருட்கள் அல்லது உணவு பொருட்கள் சம்பந்தமான தொழில் செய்வார்.\n ஜோதிடம் மற்றும் ஆன்மீக சம்பந்தமானவற்றில் ஈடுபாடு இருக்கும்.',
  'jupiter+saturn+mars': 'ஜாதகருக்கு கௌரவமான உத்யோகம் அமைந்தாலும் தன்னுடைய பிடிவாத குணத்தினால் மேல் அதிகாரிகளின் கோபத்துக்குள்ளாவார்.\n இதனால் அடிக்கடி உத்யோகத்தையே மாற்றும் நிலை உண்பாகும்.\n ஜாதகர் உலோகம், விவசாயம், பூமி அல்லது பொறியியல் சம்பந்தமான தொழில் செய்வார்.',
  'jupiter+saturn+mercury': 'ஜாதகர் மிகவும் புத்திசாலியாக இருப்பார்.\n பேச்சாற்றல், எழுத்தாற்றல் மிக்கவராக இருப்பார்.\n நண்பர்கள் மற்றும் சான்றோர்களின் அன்பையும், ஆதரவையும் பெற்றவர்.\n சொந்த வியாபாரத்தில் கொடிகட்டி பறப்பார்.\n வாணயம், எழுத்து, சட்டம், புத்தகத் தொழில்போன்றவற்றில் சிறந்து விளங்குவார்.',
  'jupiter+saturn+venus': 'ஜாதகர் கலைத்துறையில் கொடிகட்டி பறப்பார்.\n மிகப்பெரிய செல்வந்தராக இருப்பார்.\n வாழ்க்கை சுகமானதாக இருக்கும்.\n கஷ்டம் என்றால் என்னவென்று அறியமாட்டார்.\n சான்றோர்களின் அன்பையும், ஆதரவையும் பெறுவார்.\n சொகுசு பொருட்கள் விற்பனை, வட்டித்தொழில் வங்கியில் பணி, கணக்கர் தொழில், வியாபாரம் முதலியவற்றில் சிறந்து விளங்குவார்.\n சொந்தமாகச் சொத்து சுகங்களைச் சேர்த்து வைப்பார்.\n திருமணத்திற்கு பின் மனைவியால் யோகம் வரும்.\n மனைவியின் ஒத்துழைப்பு எப்பொழுதும் இருக்கும்.',
  'jupiter+saturn+rahu': 'ஜாதகர் கௌரவமான உத்யோகத்திலிருப்பார்.\n உத்யோகத்தில் மிகப்பெரிய பதவியை வகிப்பார்.\n வாழ்க்கை எந்த பிரச்சனையும் இல்லாமல் எப்பொழுதும் சுகமாக இருக்கும்.\n ஜாதகர் எல்லோருடைய அன்பையும், ஆதரவையும் பெறுவார்.\n ஜாதகருக்கு வாழ்க்கையில் எந்த குறையும் இருக்காது.',
  'jupiter+saturn+ketu': 'ஜாதகர் ஜோதிடம் மற்றும் ஆன்மீக விஷயங்களில் ஈடுபாடு உள்ளவர்.\n சித்த மருத்தவ நுணுக்கங்களை அறிந்திருப்பார்.\n வேதங்களைக் கற்றறிவார்.\n ஜாதகருக்கு வாழ்க்கையில் எந்தப் பிடிப்பும் இருக்காது.\n ஜாதகர் சன்யாசி போன்றிருப்பார்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சத்தை அடைவார்.\n ஜாதகருக்கு சுவாசம் சம்பந்தமான பிணி இருக்கும்.',
  'jupiter+rahu+sun': 'ஜாதகர் மற்றும் தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் மற்றும் அவர் தந்தைக்கிடையே ஒற்றுமையிருக்காது.\n ஜாதகருடைய மூக்கு பெரிதாக இருக்கும்.\n ஜாதகர் காலில் ரோகமுடையவர்.\n நரம்பு தளர்ச்சி, பக்கவாதம் போன்றநோய்கள் தோன்றும்.\n ஜாதகருக்கு நெருப்பில் கண்டம் உண்டு.',
  'jupiter+rahu+moon': 'ஜாதகர் மற்றும் அவர் தாய்க்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் தாய்ப்பாசம் என்றால் என்னவன்று அறியமாட்டார் அல்லது மாற்றாந்தாயிருப்பாள்.\n ஜாதகர் தேசம் விட்டு தேசம் போவார்.\n ஜாதகருக்கு அம்மை மற்றும் வைசூரி போன்ற நோய் உண்டாகும்.\n மஞ்சள்காமாலை போன்ற நோய் உண்டாகலாம்.\n ஜாதகருக்கு நீரில் கண்டம் உண்டு.',
  'jupiter+rahu+mars': 'ஜாதகர் முன்கோபம் உள்ளவராக இருப்பார்.\n மிருகத்தனமான குணங்கள் இருக்கும்.\n உடம்பில் வெட்டு காயங்கள்.\n தழும்புகள் இருக்கும்.\n ஜாதகருக்கு நெருப்பு, வாகனம் மற்றும் ஆயுதங்களால் அபாயம் உண்டாகும்.\n ஜாதகருக்கும் அவன் சகோதரருக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'jupiter+rahu+mercury': 'ஜாதகர் அதிபுத்திசாலியாக இருப்பார்.\n ஜாதகர் பொய் சொல்வார்.\n ஜாதகர் தோல்வியாதி உடையவர்.\n பேச்சுத்துறையிலும், எழுத்துத் துறையிலும் உயர்ந்த நிலையை அடைவார்.\n ஜாதகருக்கு நரம்பு சம்பந்தமான வியாதி உண்டாகும்.\n பக்கவாதம் போன்ற நோயும் உண்டாகலாம்.',
  'jupiter+rahu+venus': 'ஜாதகர் மற்றும் அவர் மனைவிக்கு கண்டங்கள், கஷ்டங்கள் உண்டாகும்.\n ஜாதகர் கலைத்துறையில் சிறந்து விளங்குவார்.\n கன்னத்தில் அழகானமச்சம் இருக்கும்.',
  'jupiter+rahu+saturn': 'ஜாதகர் தேசம் விட்டு தேசம் போவார்.\n காலில் ரோகமுடையவர்.\n நரம்புத்தளர்ச்சி இளம்பிள்ளை வாதம் போன்றவை உண்டாகும்.\n ஜாதகர் சோம்பேறியாக இருப்பார்.',
  'jupiter+rahu+ketu': 'ஜாதகருக்கு பல கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு யாருடைய உதவியும் கிடைக்காது.',
  'jupiter+ketu+sun': 'ஜாதகருக்கும் அவன் தந்தைக்கும் இடையே தகராறு ஏற்படும்.\n ஜாதகர் மனவிரக்தி உடையவர்.\n வாழ்க்கையில் எந்த பிடிப்பும் இல்லாதவர்.\n ஆன்மீக விஷயங்களில் அதிகம் நாட்டமுள்ளவர்.\n பிடிவாத குணமுள்ளவர்.\n வைராக்கியமுள்ளவர்.\n ஜாதகருக்கு உடம்பில் உஷ்ணம் அதிகமாக இருக்கும்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சம் அடைவார்.',
  'jupiter+ketu+moon': 'ஜாதகருக்கும் அவர் தாய்க்கும் இடையே ஒற்றுமையிருக்காது.\n அடிக்கடி கருத்து வேறுபாடு தோன்றும்.\n ஜாதகர் உள்ளுணர்வு மிக்கவர்.\n ஜோதிடம் மற்றும் ஆன்மீக விஷயங்களில் ஈடுபாடு உள்ளவர்.\n வைராக்கிய குணமுடையவர்.\n பின்னால் நடப்பதை முன்னால் அறியும் திறமை உடையவர்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சத்தை அடைவார்.',
  'jupiter+ketu+mars': 'ஜாதகர் மற்றும் அவர் சகோதரர்களுக்கிடையே கருத்து வேறுபாடு இருக்கும்.\n ஒற்றுமை இருக்காது.\n ஜாதகர் ஒரு சன்யாசி.\n வைராக்கிய குணமுள்ளவர்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சத்தை அடைவார்.',
  'jupiter+ketu+mercury': 'ஜாதகரின் நண்பர்கள் மற்றும் உறவினர்களுடன் கருத்துவேறுபாடு கொண்டிருப்பார்.\n நிலம் சம்பந்தமான சொத்துவகையில் தகராறு இருக்கும்.\n ஜாதகர் காதல் விவகாரத்தில் ஈடுபட்டு, அதனால் தகராறு ஏற்படும்.\n ஜாதகர் பிற்காலத்தில் வேதப்பாடங்களைக் கற்றறிவார்.\n இப்பிறவியிலேயே மோட்சத்தை அடைவார்.',
  'jupiter+ketu+venus': 'ஜாதகர் மற்றும் மனைவிக்கிடையே ஒற்றுமை இருக்காது.\n அடிக்கடி சண்டை சச்சரவு ஏற்படும்.\n சொத்து மற்றும் பணம் சம்பந்தமான விஷயங்களில் தகராறு ஏற்படும்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சத்தை அடைவார்.',
  'jupiter+ketu+saturn': 'ஜாதகர் மற்றும் மூத்த சகோதரனுக்கிடையே கருத்து வேறுபாடு ஏற்படும்.\n ஜாதகர் தேசம் விட்டு தேசம் போவார்.\n ஜாதகர் ஜோதிடம் மற்றும் ஆன்மீக விஷயத்தில் ஈடுபாடு உள்ளவர்.\n ஜாதகர் இப்பிறவியிலேயே மோட்சத்தை அடைவார்.\n ஜாதகருக்கு நரம்பு தளர்ச்சி மற்றும் சுவாசம் சம்பந்தமான பிணி வரும்.',
  'jupiter+ketu+rahu': 'ஜாதகருக்கு எப்பொழுதும் கண்டங்களும், கஷ்டங்களும் இருந்து கொண்டே இருக்கும்.\n ஜாதகரின் தாத்தா நல்ல தெய்வ பக்தி உள்ளவர்.',
  'venus+sun': 'ஜாதகர் மனைவி அதிகார தோரணை உள்ளவர்.\n நிர்வாக திறமையுள்ளவர்.\n உடம்பில் அதிக உஷ்ணம் உள்ளவர்.\n ஆணவம் கர்வம் பிடித்தவர்.',
  'venus+moon': 'ஜாதகர் மனைவி சிரித்த முகம்.\n முகப்பொலிவு உடையவர்.\n சாந்த குணமும், அழகும் உள்ளவள்.\n காமம் அதிகமுள்ளவர்.\n சாந்தம் அமைதி இருப்பாள்.\n கருப்பையில் கோளாறு உள்ளவர்.\n அடிக்கடி நோய்வாய்ப்படுவார்.',
  'venus+mars': 'ஜாதகர் மனைவி அதிகார தோரணை உள்ளவர்.\n கணவனை அடக்கி ஆள துடிப்பவர்.\n முன்கோபி பிடிவாத குணமுள்ளவர்.\n உடம்பில் அதிக உஷ்ணமுள்ளவர்.\n படபடப்பு, தைர்யம், சண்டை வீண்வாதம் செய்வார்.',
  'venus+mercury': 'ஜாதகர் மனைவி சாதாரண குடும்பத்தை சேர்ந்தவர்.\n படித்தவர், அழகும் அறிவும் உள்ளவர்.\n அலங்காரபிரியை.\n அதிர்ஷ்டசாலி.\n தெய்வபக்தி உள்ளவர்.\n பேச்சாற்றல் உள்ளவர்.\n அமைதி, பொறுமை, புத்திகூர்மை உடையவர்.',
  'venus+jupiter': 'ஜாதகர் மனைவி நல்ல குடும்பத்தில் பிறந்தவர்.\n நல்ல குணமுள்ளவர்.\n உத்தமி.\n பக்தி உள்ளவர்.\n சாந்தமுள்ளவர்.\n தர்ம குணமுள்ளவர்.\n கணவனை அக்கறையுடன் கவனித்துக்கொள்வார்.\n பெரியோர்களிடம் மரியாதை உள்ளவர்.\n நற்புத்ர பாக்கியமுள்ளவர்.\n உடலுறவில் நாட்டம் குறைந்தவர்.',
  'venus+saturn': 'ஜாதகர் மிகவும் அதிர்ஷ்டசாலியாக இருப்பார்.\n பிறந்தது முதல் இவர் எல்லா சுகங்களையும் அனுபவிப்பார்.\n திருமணத்திற்கு பின் மிகப்பெரிய செல்வந்தராவார்.\n மனைவி மூலம் சொத்தோ, பணமோ கிடைக்கும் அல்லது மனைவி சம்பாதிப்பவராக இருப்பார்.\n உலகத்தில் என்னென்ன சுகப்பொருட்கள் சொகுசு பொருட்கள் உண்டோ, அத்தனையும் அனுபவிப்பார்.\n சொந்தமாக வீடு, வாகனம், நகைகள் எல்லாமிருக்கும்.\n பணப்புழக்கத்தில் என்றும் குறையிருக்காது.\n ஜாதகர் வட்டித்தொழில் அல்லது வங்கியில் பணிபுரிபவராக இருப்பார் அல்லது அழகுபொருட்கள், ஆடம்பர பொருட்கள் சம்பந்தமான தொழில் அமையும்.\n கலைத்துறையிலும் ஈடுபடலாம்.',
  'venus+rahu': 'ஜாதகரின் மனைவிக்கு ஆயுள் குறைவு.\n எப்பொழுதும் நோய்வாய்ப்பட்டிருப்பார்.\n சோம்பேறியாகவும் இருப்பார்.\n ஜாதகர் அழகான பெரிய வீடு கட்டுவார்.\n நான்கு சக்கர வாகனங்கள் வாங்குவார்.\n இதுபோன்ற அமைப்பு உடையவர்களுக்கு கன்னத்தில் அழகான மச்சமிருக்கும்.\n ஜாதகர் பிறந்த இடத்தில் புதையல் இருக்கும்.\n அதை ஒரு நாகப்பாம்பு பாதுகாத்து வரும்.\n ஜாதகரின் மனைவி பொய் பேசுபவராக இருப்பார்.',
  'venus+ketu': 'ஜாதகரின் மனைவி விரக்தி மனப்பான்மையுடன் இருப்பார்.\n ஆன்மீகத்தில் ஈடுபாடு இருக்கும்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n ஜாதகருக்கு புத்ரதோஷம்.\n பொருளாதார தடைகள், பணமுடக்கம், பணம் சம்பந்தமான தகராறு மற்றும் மனைவியுடன் கருத்து வேறுபாடு இருக்கும்.\n ஜாதகர் பெண்ணாக இருந்தால் கருப்பை மற்றும் மர்ம உறுப்பில் கோளாறு இருக்கும்.',
  'venus+sun+moon': 'ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n மனைவி இளைத்த சரீரம் கொண்டவர்.\n முன்கோபி, தனிமை விரும்பி, வைராக்கியமுள்ளவர்.\n ஜாதகருடைய தந்தைக்கு இருதாரம் இருக்கலாம்.\n மனைவி கருப்பையில் கோளாறு உடையவர்.',
  'venus+sun+mars': 'ஜாதகருடைய மனைவி அதிகாரத் தோரணையுடையவர்.\n முன்கோபி ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n மனைவி மற்றும் மகளுக்கு உஷ்ணம் சம்பந்தமான நோய் வரும்.\n ஜாதகருடைய தந்தை முன்கோபமுடையவர்.\n ஜாதகருக்கு இருதயம் மற்றும் இரத்தம் சம்பந்தமான நோய் வரும்.',
  'venus+sun+mercury': 'ஜாதகரின் மனைவி படித்தவராகவும், புத்திசாலியாகவும் இருப்பார்.\n நிர்வாக திறமையுடையவர்.\n புத்ரதோஷம் உண்டு.\n ஜாதகருடைய தந்தை புத்திசாலியாக இருப்பார்.\n தந்தைக்கு இருதார அமைப்பு இருக்கலாம்.',
  'venus+sun+jupiter': 'ஜாதகரின் மனைவி நிர்வாகத் திறமையுடையவர்.\n சற்று முன்கோபி.\n கற்புநெறி தவறாதவர்.\n ஜாதகர் பெண்ணாக இருந்தால் தங்க நகைகள், அணிகலன்கள் முதலியவற்றை அதிகமாக சேர்த்து வைப்பார்.',
  'venus+sun+saturn': 'ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஜாதகருடைய தந்தையாருக்கு அற்ப ஆயுள்.\n ஜாதகருடைய மனைவி அதிகாரத் தோரணையுடையவர்.\n சுயசம்பாத்திமுடையவர்.',
  'venus+sun+rahu': 'ஜாதகருடைய மனைவி அடிக்கடி நோய்வாய்ப்படுவார்.\n புத்ரதோஷம் உண்டாகும்.\n ஜாதகர் விதவை பெண்களுடன் தொடர்பு வைத்து இருப்பார்.',
  'venus+sun+ketu': 'ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n பண கஷ்டம்.\n பொருளாதாரத் தடை உண்டாகும்.\n மனைவி அதிகாரத் தோரணையுடையவர்.\n மனதில் வைராக்கியமுடையவர்.\n உடம்பில் அதிக உஷ்ணமுள்ளவர்.\n ஆன்மீகத்தில் ஈடுபாடு உடையவர்.\n ஜாதகருக்கு சிறுநீரகத்தில் கோளாறு, குறைந்த இரத்த அழுத்தம், நரம்புத் தளர்ச்சி போன்ற வியாதிகள் வரும்.',
  'venus+moon+sun': 'ஜாதகருக்கு பணக்கஷ்டம், தேவையில்லாத செலவினங்கள், சொத்து நாசமுண்டாகும்.\n மனைவி அழகாக இருப்பார்.\n குடும்பப் பொறுப்பை நிர்வகிப்பதில் திறமையாக இருப்பார்.\n மனைவி நோயாளியாக இருப்பார்.\n கணவன் மீது சந்தேகப்படுவார்.\n காம எண்ணங்கள் அதிகமுள்ளவர்.\n மனைவி கருப்பையில் கோளாறு உடையவர்.',
  'venus+moon+mars': 'ஜாதகரின் மனைவி அற்பத்தனமானவர்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n கருப்பையில் கோளாறு உடையவர்.\n குறை பிரசவம் உண்டாகும்.\n அறுவை சிகிச்சை செய்து கொள்ள நேரிடும்.',
  'venus+moon+mercury': 'ஜாதகருடைய மனைவி அழகானவர்.\n பெண் பித்தனாக இருப்பார்.\n ஜாதகருக்கு தோல் வியாதி உண்டு.\n காது கேட்பதில் குறையுண்டு.\n ஜாதகருக்கு பெண்களால் அவமானம் உண்டாகும்.',
  'venus+moon+jupiter': 'ஜாதகருடைய மனைவி அழகானவர்.\n சாந்தகுணமுள்ளவர்.\n நற்குணங்கள் உடையவர்.\n சற்று சலனப்புத்தியுடையவராக இருப்பார்.\n ஜாதகருக்கு வயிற்றில் கோளாறு உண்டு.',
  'venus+moon+saturn': 'ஜாதகருடைய சொத்துக்கள் நாசமாகும்.\n பணவிரயம் ஏற்படும்.\n ஜாதகருடைய தாயார் அடிக்கடி நோய்வாய்படுவார்.\n ஜாதகருக்கு வயிற்றில் கோளாறு உண்டு.\n மனைவி சோம்பேறியாக இருப்பார்.\n பருத்த சரிரமுடையவர்.',
  'venus+moon+rahu': 'ஜாதகரின் மனைவி அடிக்கடி நோய்வாய்ப்படுவாள்.\n குறை பிரசவம் உண்டாகும்.\n மர்ம உறுப்பில் வியாதி வரும்.\n ஜாதகருடைய மனைவிக்கும் தாயாருக்கும் அடிக்கடி கண்டங்கள் ஏற்படும்.\n ஜாதகர் அன்னியப் பெண்ணுடன் ரகசியத் தொடர்பு வைத்து இருப்பார்.\n ஜாதகருடைய வயிற்றில் கோளாறு உண்டு.\n ஜாதகர் மனதில் பயம் உடையவர்.\n பில்லி, ஏவல், சூனியம் மற்றும் மந்திரவாதிகளால் பாதிக்கப்படுவார்.',
  'venus+moon+ketu': 'ஜாதகரின் மனைவி மனம் குழப்பமுடையது.\n ஜாதகருக்கு பணவிரயம் மற்றும் பொருளாதாரத் தடையுண்டு.\n ஜாதகருடையத் தாயார் அடிக்கடி நோய்வாய்ப்படுவார்.\n ஜாதகருக்கு கண் ரோகம் உடையவர்.',
  'venus+mars+sun': 'ஜாதகருடைய மனைவி முன்கோபியாக இருப்பார்.\n மனைவி மற்றும் மகளுக்கு உஷ்ணம் சம்பந்தமானவியாதி உண்டாகும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.',
  'venus+mars+moon': 'ஜாதகருடைய மனைவி முன்கோபியாக இருப்பார்.\n நிம்மதி இல்லாமல் மனகலக்கம் உடையவராக இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவர் அடிக்கடி பிரயாணம் செய்யக்கூடியவராக இருப்பார்.',
  'venus+mars+mercury': 'ஜாதகருக்கு திருமணத்தில் தடையுண்டு.\n ஜாதகருடைய சகோதரர்களுக்கு இடையே ஒற்றுமை இருக்காது.\n ஜாதகருடைய மனைவி தர்க்கம் செய்ய கூடியவராக இருப்பார்.\n படித்தவராக இருப்பார்.',
  'venus+mars+jupiter': 'ஜாதகருடைய மனைவி முன்கோபியாக இருந்தாலும் நற்குணங்கள் உடையவராக இருப்பார்.\n தெய்வ பக்தியுடையவராக இருப்பார்.\n ஜாதகருக்கு திருமணம் ஆவதற்கு முன்பே அவனுடைய இளைய சகோதரனுக்கு திருமணமாகும்.',
  'venus+mars+saturn': 'ஜாதகருடைய மனைவி முன்கோபியாக இருப்பார்.\n ஜாதகருடைய தொழில் வகையில் எதிரிகளால் தொல்லை உண்டாகும்.\n ஜாதகர் கண்ணில் ரோகம் உடையவர்.',
  'venus+mars+rahu': 'ஜாதகருடைய மனைவிக்கு அடிக்கடி கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மனைவி பிணியுடையவராக இருப்பார்.\n ஜாதகருடைய சகோதரர்களுக்கும் அடிக்கடி கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் பெண்ணாக இருந்தால் கணவருக்கு கண்டங்கள் ஏற்படும்.\n ஜாதகருக்கு அதிக இரத்த அழுத்தம் உண்டாகும்.\n ஜாதகர் எளிதில் உணர்ச்சிவசப்படுவார்.\n ஜாதகருக்கு நெருப்பினால் அபாயம் உண்டாகும்.',
  'venus+mars+ketu': 'ஜாதகருடைய மனைவி பிடிவாத குணமுடையவர்.\n வைராக்யம் உடையவர்.\n கணவன் மனைவிக்கிடையே ஒற்றுமை இருக்காது.',
  'venus+mercury+sun': 'ஜாதகரின் மனைவி படித்தவர்.\n புத்திசாலி.\n நிர்வாகத் திறமையுடையவர்.\n ஜாதகர் தன் தாய்மாமனின் மகளைத் திருமணம் செய்து கொள்வார்.\n மனைவி இளமையானத் தோற்றமுடையவர்.\n இனிமையாகப் பேசுவார்.\n பேச்சுத் திறமை, எழுத்துத் திறமையுடையவர்.',
  'venus+mercury+moon': 'ஜாதகர் பெண் பித்தனாக இருப்பார்.\n ஜாதகர் பெண்ணாக இருந்தால் நடத்தை விஷயமாக வீண்பழி உண்டாகும்.\n ஜாதகருக்கு தோல் வியாதி உண்டு.\n காது கேட்பதில் குறையுண்டு.',
  'venus+mercury+mars': 'ஜாதகருக்கு திருமணத்தில் தடையுண்டு.\n திருமணமான தம்பதியருக்கிடையே ஒற்றுமை இருக்காது.\n அன்னியருடைய தலையீட்டால் கணவன் - மனைவியருக்கிடையே கருத்து வேறுபாடு உண்டாகும்.',
  'venus+mercury+jupiter': 'ஜாதகருடைய மனைவி நல்ல படித்தவராகவும், புத்திசாலியாகவும், நற்குணங்கள் நிறைந்தவராகவும் இருப்பார்.\n தெய்வ பக்தியுடையவராக இருப்பார்.',
  'venus+mercury+saturn': 'ஜாதகருடைய மனைவி படித்தவராகவும், சுயசம்பாத்தியம் உள்ளவராகவும் இருப்பார்.\n ஜாதகருக்கு சொந்தமாக சொத்துக்கள் நிலபுலன்கள் எல்லாம் இருக்கும்.\n ஜாதகர் சொந்தமாக வீடுகட்டுவார்.',
  'venus+mercury+rahu': 'ஜாதகரின் மனைவி படித்தவராக இருப்பார்.\n சற்று சோம்பேறியாக இருப்பார்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n ஜாதகருக்கு கன்னத்தில் அழகாக மச்சம் இருக்கும்.',
  'venus+mercury+ketu': 'ஜாதகருக்கு ஞாபக சக்தி குறைவாக இருக்கும்.\n ஜாதகருக்கு சொத்து, நிலம், பணம் விஷயமாக தகராறு இருக்கும்.\n மனைவியுடன் கருத்து வேறுபாடு இருக்கும்.',
  'venus+jupiter+sun': 'ஜாதகரின் மனைவி சொந்த வருமானமுள்ளவர்.\n வசதியான செல்வாக்குள்ள குடும்பத்தில் பிறந்தவர்.\n எல்லா சுகங்களையும் அனுபவிப்பார்.\n கொஞ்சம் சோம்பேறியாக இருப்பார்.\n ஜாதகருக்கு அரசு உத்யோகம் கிடைக்கும் அல்லது அரசாங்க உதவி கிடைக்கும்.\n ஆரம்பகாலத்தில் உத்யோகத்திலோ, தொழிலிலோ சிறுசிறு பிரச்சனை இருந்தாலும் பிற்காலத்தில் உயர்ந்த நிலையை அடைவார்.',
  'venus+jupiter+moon': 'மனைவி நற்குணங்களுடையவர்.\n அழகான தோற்றம் உடையவர்.\n மென்மையானவர்.\n போன ஜென்மத்தில் எந்த பெண் மனைவியாக இருந்தாலோ, அதே பெண் இந்த ஜென்மத்தில் மனைவியாக வருவாள்.\n ஜாதகர் தன் தாய் மற்றும் மனைவி இருவருக்கிடையே நடக்கும் சண்டையைத் தீர்த்து வைக்க முடியாமல் தவிப்பார்.',
  'venus+jupiter+mars': 'ஜாதகருடைய மனைவி நற்குணங்களுடையவராகவும், பிடிவாதம் உடையவராக இருப்பார்.\n ஜாதகர் அழகானவராகவும், கட்டுமஸ்தான உடல்வாகு உடையவராகவும் இருப்பார்.\n ஜாதகர் முன்கோபியாக இருப்பார்.\n தைர்யவானாக இருப்பார்.\n இரத்த சம்பந்தமான வியாதி உண்டாகும்.\n ஜாதகர் பிறரால் எளிதில் ஏமாற்றப்படுவார்.\n மனைவிதெய்வபக்தியுடையவர்.',
  'venus+jupiter+mercury': 'ஜாதகருடைய மனைவி அமைதியான, இளமையான தோற்றமுடையவர், சாந்தகுணமுள்ளவர், படித்தவர், மென்மையானவர், இனிமையாக பேசக்கூடியவர்.\n ஜாதகர் இளமையான, கவர்ச்சியான, தோற்றம் உடையவர்.\n இனிமையாக பேசக்கூடியவர்.\n பெண்களை எளிதில் கவர்ந்து விடுவார்.\n ஜாதகரை சுற்றி எப்போதும் பெண்கள் இருந்து கொண்டே இருப்பார்கள்.\n ஜாதகர் மனைவியைத் தவிர வேறொரு இளம் பெண்ணுடன் தொடர்பு இருக்கும்.\n அந்த இளம் பெண் ஜாதகருக்கு பல வகையில் உதவிகரமாக இருப்பார்.\n போன ஜென்மத்தில் எந்த பெண் மனைவியாக இருந்தாளோ, அதே பெண்ணே இந்த ஜென்மத்தில் மனைவியாக வருவார்.',
  'venus+jupiter+saturn': 'ஜாதகருடைய மனைவி அமைதியான தோற்றமுடையவர்.\n சாந்தகுணமுடையவர்.\n சுயமாக சம்பாத்தியம் உடையவர்.\n ஜாதகர் வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.\n கஷ்டம் என்றால் என்னவென்று அறியமாட்டார்.\n வாழ்க்கை பாதையில் எந்த தடையும் இருக்காது.\n ஜாதகர் செல்வந்தர் ஆவார்.\n சொந்தமாக நிலப்புலன்கள், சொத்துக்கள், வீடு வாகனங்கள் எல்லாம் இருக்கும்.',
  'venus+jupiter+rahu': 'ஜாதகருக்கும் அவர் மனைவிக்கும் அடிக்கடி நோய் நொடிகள் வந்து போய் கொண்டு இருக்கும்.\n ஜாதகர் நடிப்பு துறையில் சிறந்து விளங்குவார்.\n ஜாதகருக்கும் மனைவிக்கும் அற்ப ஆயுள்.',
  'venus+jupiter+ketu': 'ஜாதகர் மற்றும் அவர் மனைவி ஆன்மீகத்தில் ஈடுபாடுள்ளவர்களாக இருப்பார்கள்.\n இதே ஜென்மத்தில் இருவரும் மோட்சத்தை அடைவார்கள்.\n ஜாதகர் விரக்தி மனப்பான்மை உள்ளவராகவும், குடும்ப வாழ்க்கையில் பிடிப்பு இல்லாதவராகவும் இருப்பார்.\n ஜாதகருடைய மனைவியும் அமைதியான தோற்றமுடையவர்.\n வைராக்கியம் உடையவர்.',
  'venus+saturn+moon': 'ஜாதகரின் மனைவி சொந்த வருமானமுள்ளவர்.\n அழகான தோற்றமுடையவர்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n கருப்பையில் கோளாறு உடையவர்.\n ஜாதகர் தொழில் விஷயமாக அடிக்கடி பிரயாணம் செய்வார்.\n உணவு பொருட்கள், மருந்து பொருட்கள் அல்லது திரவப் பொருட்கள் சம்பந்தமான விற்பனை உத்யோகம் அமையும்.',
  'venus+saturn+mars': 'ஜாதகருடைய மனைவி சொந்த வருமானமுள்ளவர்.\n அதிகாரத் தோரணையுள்ளவர்.\n முன்கோபி, ஜாதகர் ஆரம்பகாலத்தில் உத்யோகம் அல்லது தொழில் வகையில் எதிரிகளின் தொல்லைகளைச் சந்திப்பார்.\n ஜாதகர் உலோகம், விவசாயம் அல்லது பொறியியல் சம்பந்தமான தொழில் செய்வார்.',
  'venus+saturn+mercury': 'ஜாதகருடைய மனைவி சொந்த வருமானமுள்ளவர்.\n படித்தவர்.\n தொழில் விஷயத்தில் ஞானமுள்ளவர்.\n ஜாதகர் வாணிபம், எழுத்து, சட்டம் அல்லது வங்கியில் பணிபுரிதல், வட்டித்தொழில் போன்ற தொழில் செய்வார்.\n ஜாதகர் மனைவி மற்றும் பெண்களால் லாபம் அடைவார்.\n நண்பர்களின் அன்பையும், ஆதரவையும் பெறுவார்.\n வாழ்க்கையில் எல்லா சுகங்களையும் அனுபவிப்பார்.\n சொந்தமாக நிலபுலன்கள், சொத்துக்கள் வாங்குவார்.\n சொந்தமாக வீடுகட்டுவார்.',
  'venus+saturn+jupiter': 'ஜாதகருடைய மனைவி சொந்த வருமானம் உள்ளவர்.\n நற்குணங்கள் உடையவர்.\n அமைதியான தோற்றமுடையவர்.\n தெய்வபக்தியுடையவர்.\n ஜாதகர் கௌரவமான உத்யோகத்தில் இருப்பார்.\n ஏராளமாக சம்பாதிப்பார்.\n வாழ்க்கை மிகவும் சுமூகமானதாகவும், சுகமானதாகவும் இருக்கும்.\n ஜாதகர் தன் உத்யோகத்திலோ, தொழிலிலோ உயர்ந்த நிலையை அடைவார்.\n பெயரும், புகழும் அடைவார்.\n எல்லோருடைய அன்பையும், ஆதரவையும் பெறுவார்.',
  'venus+saturn+rahu': 'ஜாதகருடைய மனைவி சொந்த வருமானம் உள்ளவர்.\n நோயாளியாக இருப்பார்.\n மனதில் பயமுடையவர்.\n சோம்பேறியாக இருப்பார்.\n பொய் பேசுவார்.\n எதையும் ரகசியமாக செய்வார்.\n ஜாதகர் சினிமா தொழில், வாகனங்கள் சம்பந்தமான தொழில் ரகசியமாக பணம் சம்பாதித்தல் போன்ற தொழில்கள் செய்வார்.\n வட்டி தொழிலையும் மிகப்பெரிய அளவில் செய்யலாம்.\n ஜாதகருடைய மனைவிக்கு ஊனம் இருக்கலாம்.',
  'venus+saturn+ketu': 'ஜாதகருடைய மனைவி ஆன்மீக ஈடுபாடு உள்ளவர்.\n சொந்த வருமானமுடையவர்.\n விரக்திமனப்பான்மையுடையவர்.\n வாழ்க்கையில் எந்தவித பிடிப்பும் இல்லாதவர்.\n ஜாதகர் வழக்கறிஞர், ஆன்மீககுரு, தையல்கடை வைத்தல், கயிறு தயாரித்தல், மின்கம்பி தயாரித்தல், நூற்பாலை சம்பந்தமான உத்யோகம் செய்வார்.',
  'venus+rahu+sun': 'ஜாதகருடைய மனைவிநோயுடையவர்.\n அற்பஆயுளுடையவர்.\n மனதில் பயமுடையவர்.\n சோம்பேறியாக இருப்பார்.\n பொய் பேசுவார், ஜாதகருடைய மனைவிக்கும், தகப்பனுக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.',
  'venus+rahu+moon': 'ஜாதகருடைய மனைவி நோயாளியாக இருப்பார்.\n அற்பஆயுளுடையவர்.\n மனதில் பயமுடையவர்.\n ஜாதகருடைய மனைவிக்கும்.\n தாய்க்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருடைய மனைவி கருப்பையில் கோளாறு உள்ளவர்.',
  'venus+rahu+mars': 'ஜாதகருடைய மனைவிக்கும் சகோதரருக்கும்.\n சகோதரிக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n மனைவி குணங்கெட்டவராக இருப்பார்.\n தன் கணவனை வெறுப்பார்.\n நோயாளியாக இருப்பார்.\n கணவன், மனைவியரிடையே ஒற்றுமை இருக்காது.',
  'venus+rahu+mercury': 'ஜாதகருடைய மனைவி மந்தபுத்தியுடையவர்.\n நோய் உடையவர்.\n கபடதன்மை உடையவர்.\n ஜாதகருக்கு கன்னத்தில் அழகான மச்சம் இருக்கும்.\n மனைவி அற்ப ஆயுளுடையவர்.\n ஏவல், பில்லி சூன்யம் மற்றும் மந்திரவாதிகளால் தொல்லைகள் இருந்து கொண்டு இருக்கும்.\n மனதில் எப்போதும் பயம் இருந்து கொண்டே இருக்கும்.\n மனைவி படித்தவர்.',
  'venus+rahu+jupiter': 'ஜாதகர் மற்றும் அவர் மனைவி இருவரும் நோயாளியாக இருப்பார்கள்.\n அடிக்கடிகண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருடைய மனைவி அற்ப ஆயுளுடையவர்.\n மனைவி தெய்வபக்தி உடையவர்.',
  'venus+rahu+saturn': 'ஜாதகருக்கு நோயுள்ள மனைவி, ஒழுக்கமற்ற மனைவி, சந்தர்பங்கள் அமைந்தாலும் அனுபவிக்க முடியாது.\n வெளிபடுத்த முடியாத நிலை.\n இவர்களுக்கு ஆவி, பேய், பிசாசு இது போன்ற தொந்தரவுகள் ஏற்படும்.',
  'venus+rahu+ketu': 'ஜாதகருடைய மனைவிக்கு அற்ப ஆயுள்.\n நோயாளியாக இருப்பார்.\n எதிர்பாராதகண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'venus+ketu+sun': 'ஜாதகருடைய வீட்டில் பூர்வீகச் சொத்து சம்பந்தமான தகராறு இருக்கும்.\n மனைவி அதிகாரத் தோரணையுடையவர்.\n வைராக்யமுடையவர்.',
  'venus+ketu+moon': 'ஜாதகருடைய மனைவி ஆன்மீக ஈடுபாடு உடையவர்.\n கருப்பையில் வியாதி உடையவர்.\n ஜாதகனுடைய மனைவிக்கும் தாயாருக்கும் இடையே அடிக்கடி சண்டை, சச்சரவு உண்டாகும்.\n தாய்வழி பூர்வீகச்சொத்து சம்பந்தமாக தகராறுவரும்.',
  'venus+ketu+mars': 'ஜாதகருடைய மனைவி அதிகாரத் தோரணையுடையவர்.\n வைராக்யம் உடையவர்.\n கணவன், மனைவியரிடையே ஒற்றுமை இருக்காது.\n கருத்து வேறுபாடு ஏற்பட்டு பிரிய நேரிடும்.\n குடும்பத்தில் பண விஷயமாக தகராறு இருக்கும்.\n ஜாதகருக்கு நரம்பு தளர்ச்சி, குறைந்த இரத்த அழுத்தம், வியாதிகள் உண்டாகும்.',
  'venus+ketu+mercury': 'ஜாதகருடைய மனைவி திருமணத்திற்கு முன்பே காதல் விவகாரங்களில் ஈடுபட்டிருப்பார்.\n ஜாதகரும் காதல் விவகாரங்களில் ஈடுபடுவார்.\n அதனால் பல பிரச்சனை உண்டாகும்.\n குடும்பத்தில் சொத்து, நிலம் சம்பந்தமாகவோ அல்லது பண விஷயமாகவோ தகராறு உண்டாகும்.\n மனைவியுடனும் தகராறு செய்ய நேரிடும்.',
  'venus+ketu+jupiter': 'ஜாதகருடைய மனைவி தெய்வபக்தியுடையவராக இருப்பார்.\n மனைவியுடன் சண்டை சச்சரவுகள் செய்ய நேரிடும்.\n இதுபோன்ற சமயங்களில் தெய்வ அருளால் பிரச்சனைகள் தீரும்.',
  'venus+ketu+saturn': 'ஜாதகரின் குடும்பத்தில் சொத்து அல்லது பண விஷயமாக தகராறு ஏற்படும்.\n மனைவியுடன் கருத்து வேறுபாடு உண்டாகும்.\n ஜாதகருக்கு உத்யோகத்தில் பல தொல்லைகள் ஏற்படும்.',
  'venus+ketu+rahu': 'ஜாதகருடைய மனைவி நோயாளியாக இருப்பார்.\n கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'saturn+sun': 'அரசாங்க உத்யோகம் அரசியல், உத்யோகத்தில் சுமுகமான நிலை இருக்காது.',
  'saturn+moon': 'அடிக்கடி பிரயாணம் செய்ய வேண்டிய தொழில், ஜோதிடம், கணக்கர்தொழில், ஆன்மீக குரு போன்ற தொழில், வாசனைப் பொருட்கள், மருந்து பொருட்கள் விற்பனை செய்தல், ஐலப்பொருட்கள் விற்பனை செய்தல்.',
  'saturn+mars': 'தொழிலில் சுமுகமான நிலை இருக்காது.\n எப்பொழுதும் தொல்லைகள் இருந்து கொண்டே இருக்கும்.\n உலோகம் சம்பந்தமானபொறியியல் சம்பந்தமான தொழில் அல்லது விவசாயம், பூமிதொழில்.',
  'saturn+mercury': 'வாணிபம், எழுத்து, சட்டம், புத்தகம் எழுதுதல், போன்ற தொழில் தொழில் முறை கூட்டாளிகளின் ஆதரவு எப்பொழுதும் இருக்கும்.',
  'saturn+jupiter': 'கௌரவமான தொழில், சுயதொழில், நிர்வாக பொறுப்புள்ள உத்யோகம்.\n தொழிலில் அல்லது உத்யோகத்தில் சுமுகமானநிலை காணப்படும்.',
  'saturn+venus': 'அதிர்ஷ்டமுள்ளவர் ஜாதகர், சொகுசு பொருட்கள், விற்பனை செய்தல், வட்டித்தொழில், வங்கியில் பணி, கணக்கர், வியாபாரம், சொந்தமாக வீடு கட்டுவார்.\n திருமணத்திற்கு பின்யோகம் வரும்.',
  'saturn+rahu': 'ஜாதகர் அடிமைத்தொழில் செய்வார்.\n கள்ளக்கடத்தல், திருட்டு வழியில் சம்பாதிப்பார்.\n யாருடைய உதவியுமில்லாமல் கஷ்டப்பட்டு முன்னுக்கு வருவார்.\n வாயு சம்பந்தமான பிணியுடையவர்.\n மூட்டுவலி, கால்வலி, மற்றும் முடக்குவாதம் போன்ற நோய்கள் உண்டாகும்.\n ஜாதகர் பரதேசம் போவார்.\n சுய உழைப்பால் உயர்ந்தவராவார்.\n இவன் பூர்வ ஜன்மத்தில் அதிகமான பாவங்கள் செய்ததால் வாழ்க்கையில் மிகவும் கஷ்டப்பட்டு முன்னேறுவார்.',
  'saturn+ketu': 'ஜாதகர் வெறுப்பும்.\n ஏமாற்றமும் அடைவார்.\n சரியான தொழிலோ, உத்யோகமோ அமையாது.\n அப்படி அமைந்தால் எப்போதும் ஏதாவது தொல்லைகள் இருந்துகொண்டே இருக்கும்.\n சன்யாசி போல இருப்பார்.\n ஆன்மீகத்தில் ஈடுபாடு இருக்கும்.\n இந்த ஜன்மத்திலேயே தன்கர்மங்களைத் தீர்த்து முக்தி அடைவார்.\n நரம்புத்தளர்ச்சி, சுவாசம் சம்பந்தமானபிணிகள் உண்டாகும்.',
  'saturn+sun+moon': 'ஜாதகர் தொழிலிலோ, உத்யோகத்திலோ பல இன்னல்கள் அனுபவிப்பார்.\n ஜாதகர் தன் தந்தை செய்து வந்த தொழில் செய்யலாம்.\n உத்யோகம் சம்பந்தமான விஷயமாக பிரயாணம் செய்யலாம்.\n தொழில் விஷயமாக மனதில் கவலை இருந்து கொண்டே இருக்கும்.',
  'saturn+sun+mars': 'ஜாதகருடைய உத்யோகத்திலோ அல்லது தொழிலிலோ, அதிகாரிகளால் பல தொல்லை உண்டாகும்.\n இதனால் அடிக்கடி உத்யோக மாற்றம் செய்ய வேண்டி வரும்.\n ஜாதகருக்கு காவல் துறை, இராணுவம் போன்ற அரசு துறைகளில் உத்யோகம் அமையலாம்.',
  'saturn+sun+mercury': 'ஜாதகருக்கு அரசு உத்யோகம் அமையும்.\n அரசாங்க உதவி கிடைக்கும்.',
  'saturn+sun+jupiter': 'ஜாதகனுக்கு மிகவும் அதிர்ஷ்டமானவர்.\n கௌரவமான உத்யோகம் அமையும்.\n உத்யோகத்தின் மூலம் நல்ல பணம் வரும் வாய்ப்பும், பெயரும், புகழம் கிடைக்கும்.\n ஜாதகருக்கு ஏராளமான சொத்துக்கள் சேரும்.',
  'saturn+sun+venus': 'ஜாதகருக்கு பூர்வீகச் சொத்து கிடைக்கும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஜாதகருக்கு அரசு உத்யோகம் அமையும் உத்யோகத்தின் மூலம் நல்லபணமும் வருவாயும் புகழும் கிடைக்கும்.',
  'saturn+sun+rahu': 'உத்யோகத்தில் பல தடைகள் உண்டாகும்.\n அடிமைத்தொழில் செய்ய நேரிடும்.\n திருட்டு வழியில் பணம் சம்பாதிக்க நேரிடும்.',
  'saturn+sun+ketu': 'ஜாதகருக்குசரியான உத்யோகமோ, தொழிலோ அமையாது.\n அரசு துறையில் வழக்கறிஞர் தொழில் அமையலாம்.',
  'saturn+moon+sun': 'ஜாதகர் தொழில் விஷயமாக அடிக்கடி பிரயாணம் செய்ய நேரிடும்.\n ஜாதகர் தன் தந்தை செய்த தொழிலை அல்லது அரசு துறையினோ பணிபுரிய நேரிடும்.',
  'saturn+moon+mars': 'ஜாதகர் உத்யோகத்தில் பல தடைகளையும், கஷ்டங்களையும் அனுபவிப்பார்.\n உத்யோக சம்பந்தமாக மனதில் எப்போதும் கவலை இருந்து கொண்டே இருக்கும்.\n வீண்பழி உண்டாகும்.\n ஜாதகர் உத்யோகம் சம்பந்தமாக அடிக்கடி பிரயாணம் செய்ய நேரிடும்.\n ஜாதகர் பூமி தொழில் அல்லது இயந்திரங்கள் சம்பந்தமாக தொழில் செய்வார்.\n ஜாதகர் அறுவை சிகிச்சை செய்து கொள்வார்.',
  'saturn+moon+mercury': 'ஜாதகர் கணக்கியல் அல்லது சட்டம் போன்ற துறைகளில் பணிபுரிவார்.\n எழுத்து துறையிலும் ஈடுபடலாம்.\n ஜாதகருக்கு தொண்டையில் வியாதியிருக்கும் அல்லது மூக்கில் கட்டிவரும்.',
  'saturn+moon+jupiter': 'ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.\n ஜாதகர் ஆசிரியர் பணி, ஜோதிடர், சட்டம் அல்லது மருத்துவம் போன்ற துறைகளில் பணிபுரிவார்.',
  'saturn+moon+venus': 'ஜாதகர் சொகுசு பொருட்கள் அல்லது சுகந்த பொருட்கள் அல்லது சுவையான இனிப்பான பண்டவகைகள் போன்ற விற்பனையில் ஈடுபடுவார் அல்லது மருத்துவம் போன்ற துறைகளில் பணிபுரிவார்.',
  'saturn+moon+rahu': 'ஜாதகர் திருட்டு வகையில் பணம் சம்பாதிப்பார்.\n இதனால் உத்யோகத்தில் வீண்பழி மற்றும் அவமானமுண்டாகும்.\n ஜாதகர் புகைப்படம்.\n திரைப்படம் போன்ற துறைகளில் பணிபுரியலாம்.\n கள்ளக்கடத்தலினும் ஈடுபடுவார்.',
  'saturn+moon+ketu': 'ஜாதகருக்கு தொழில் விஷயங்களில் எந்த ஈடுபாடும் இருக்காது.\n ஜாதகர் ஆன்மீகத்தில் அதிக ஈடுபாடு கொள்வார்.\n கயிறு தயாரித்தல் நூற்பாலை, தையல் தொழில் அல்லது மின்கம்பி தயாரித்தல் போன்ற தொழில் அமையலாம்.\n உத்யோகத்தில் வீண்பழி, வீண் தகராறு உண்டாகும்.',
  'saturn+mars+sun': 'ஜாதகருக்கு உத்யோகத்தில் பல கஷ்டங்களும், தடைகளும் உண்டாகலாம்.\n இதனால் உத்யோகத்தை அடிக்கடி மாற்ற நேரிடும்.\n காவல்துறை அல்லது இராணுவம் போன்ற அரசு துறைகளில் உத்யோகம் அமையலாம்.\n அல்லது இயந்திரம் சம்பந்தமான தொழில் அமையும்.',
  'saturn+mars+moon': 'ஜாதகருக்கு உத்யோகத்திலோ அல்லது தொழிலிலோ கஷ்டங்களும் தடைகளும் உண்டாகும்.\n இதுகுறித்து மனதில் எப்போதும் கவலை இருந்துகொண்டே இருக்கும்.\n எதிரிகள் எப்போதும் தொல்லை கொடுத்து கொண்டு இருப்பார்கள்.\n ஜாதகர் இயந்திரம் அல்லது பூமி சம்பந்தமான தொழில் செய்யலாம்.\n உத்யோகம் சம்பந்தமான அடிக்கடி பிரயாணம் செய்ய நேரிடும்.',
  'saturn+mars+mercury': 'ஜாதகர் சொந்தமாக வியாபாரம், தரகு தொழில் அல்லது நிலம் விற்றல், வாங்கல் சம்பந்தமான தொழில் அல்லது இயந்திர சம்பந்தமான தொழில் செய்வார்.\n ஜாதகர் தொழில்முறை கூட்டாளிகளுடன் அடிக்கடி சண்டை போடுவார்.',
  'saturn+mars+jupiter': 'ஜாதகர் சொந்தமாக தொழிற்சாலையோ, இயந்திர சம்பந்தமான தொழிலையோ அல்லது அறுவை சிகிச்சை சம்பந்தமான மருத்துவத் தொழில் செய்வார்.\n ஜாதகர் தன் கடின உழைப்பால் உத்யோகத்தில் பெயரும் புகழும் பெறுவார்.\n வாதகருக்கு ரத்தம் மற்றும் இருதய சம்பந்தமான பிணி உண்டாகும்.',
  'saturn+mars+venus': 'ஜாதகர் ஆடம்பர பொருட்கள் விற்பனை செய்வதோ, வட்டித் தொழிலோ செய்வார்.\n ஜாதகருக்கு ஆரம்ப காலங்களில் தொழிலில் அல்லது உத்யோகத்திலோ கஷ்டங்களும், தடைகளும் உண்டாகும்.',
  'saturn+mars+rahu': 'ஜாதகர் அடிமைத்தொழில் செய்வார்.\n சமூக விரோதிகளின் தொடர்பால் தொழிலில் பல இன்னல்களைச் சந்திப்பார்.\n ஜாதகர் மிகப்பெரிய தொழிற்சாலையில் பணிபுரியும் நிலையும் ஏற்படலாம்.',
  'saturn+mars+ketu': 'ஜாதகருக்கு சரியான உத்யோகமோ, தொழிலோ அமையாது.\n அப்படியே அமைந்தாலும் பல பிரச்சனைகளும், தடைகளும் உண்டாகும்.\n இதனால் வழக்கு விஷயங்களில் ஈடுபட நேரிடும்.\n ஜாதகருக்கு திருமணத்தில் தடை உண்டாகும்.\n ஜாதகர் விரக்தி அடைந்தவனாகவும் சன்யாசி போலும் இருப்பார்.',
  'saturn+mercury+sun': 'ஜாதகருக்கு சொந்த தொழிலோ அல்லது அரசு உத்யோகமோ அமையும்.\n ஜாதகர் தன் புத்திசாலித்தனத்தால் பெயரும் புகழும் அடைவார்.\n ஜாதகருக்கு சொந்தமாக நிலபுலன்கள் எல்லாம் அமையும்.\n ஜாதகர் சட்டம் எழுத்துத்துறை மற்றும் பத்திரிகைத் துறைகளில் ஏதாவது ஒன்றில் பணிபுரிவார்.',
  'saturn+mercury+moon': 'ஜாதகர் கணக்கியல் அல்லது சட்டம் அல்லது எழுத்து துறையில் பணிபுரிவார்.',
  'saturn+mercury+mars': 'ஜாதகர் இயந்திரம் சம்பந்தமான தொழில் புரிவார்.\n அல்லது சொந்த வியாபாரம் தரகு தொழில், நிலம் விற்றல் வாங்கல் சம்பந்தமான தொழில் செய்வார்.\n தொழில் விஷயமாக அடிக்கடி சண்டை, சச்சரவுகள் ஏற்படும்.',
  'saturn+mercury+jupiter': 'ஜாதகர் அதிர்ஷ்டம் உள்ளவர்.\n ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.\n உத்யோகத்தில் பெயரும் புகழும் கிடைக்கும்.\n ஜாதகர் பலருக்கும் வழிகாட்டியாக இருப்பார்.\n ஆலோசனை வழங்குதல் ஆசிரியர் பணி, கணக்கியல், சட்டம் போன்ற துறைகளில் உத்யோகம் அமையும்.',
  'saturn+mercury+venus': 'ஜாதகர் பணம், வங்கி, வணிகம், வணிகவரி சம்பந்தமான தொழிலில் ஈடுபடுவார்.\n சொந்த தொழிலும் அமையலாம்.\n ஜாதகருக்குசொந்தமாக நிலபுலன்கள், சொத்துக்கள், வீடுவாகனங்கள் எல்லாம் அமையும்.',
  'saturn+mercury+rahu': 'ஜாதகர் மிகப்பெரிய அளவில் சொந்தமாக வியாபாரம் செய்வார்.\n திருட்டு வழியில் பணம் சம்பாதித்தல், கள்ளக்கடத்தல் போன்ற தொழிலிலும் ஈடுபடுவார்.',
  'saturn+mercury+ketu': 'ஜாதகர் சட்டம் நூற்பாலை அல்லது துணிமணிகள் விற்பனை செய்தல், தையல் தொழில் போன்றவற்றில் ஈடுபடுவார்.',
  'saturn+jupiter+sun': 'ஜாதகர் அதிர்ஷ்டமுள்ளவர்.\n ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.\n அதிகாரம் செய்ய கூடிய வகையில் தொழில் அமையும்.\n ஜாதகர் தன் உத்யோகத்திலோ அல்லது தொழிலிலோ, பேரும் புகழும் அடைவார்.\n ஜாதகர் ஏராளமாகச் சம்பாதிப்பார்.\n தன் உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n எல்லோருடைய அன்பையும், ஆதரவையும் பெறுவார்.',
  'saturn+jupiter+moon': 'ஜாதகருக்கு கௌரவமான உத்யோகமோ அல்லது தொழிலோ அமையும்.\n ஜாதகர் பேரும், புகழும் அடைவார்.\n உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n ஜாதகர் ஆசிரியர், பணி, ஜோதிடம், சட்டம், மருத்துவம் போன்ற துறைகளில் ஏதாவது ஒன்றில் பணிபுரிவார்.\n ஜாதகர் தன் உத்யோகம் சம்பந்தமாக அடிக்கடி பிரயாணம் செய்வார்.',
  'saturn+jupiter+mars': 'ஜாதகர் பொறியியல் அல்லது மருத்துவத் துறையில் அறுவை சிகிச்சை பிரிவில் பணிபுரிவார்.\n கடின உழைப்பால் பேரும் புகழும் பெறுவார்.\n ஜாதகர்சற்று முன்கோபியாக இருப்பார்.',
  'saturn+jupiter+mercury': 'ஜாதகர் மிகவும் புத்திசாலியாக இருப்பார்.\n ஆகவே பிறருக்கு ஆலோசனை வழங்குதல்.\n ஆசிரியர் பணி, கணக்கர், வழக்கறிஞர் போன்ற துறைகளில் ஏதாவது ஒன்றில் பணிபுரிவார்.\n தன் உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n பேரும், புகழும் பெறுவார்.\n எல்லோருடைய அன்பையும், ஆதரவையும் பெறுவார்.\n ஏராளமாக பணம் சம்பாதிப்பார்.\n சொந்தமாக நிலம் சொத்துக்கள் வாங்குவார்.',
  'saturn+jupiter+venus': 'ஜாதகர் பிறருக்கு ஆலோசனை வழங்குதல் அல்லது வங்கியில் பணிபுரிபவராக இருப்பார்.\n ஜாதகருக்கு உத்யோகத்தில் பேரும், புகழும் கிடைக்கும்.\n உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n வீடுகள், வாகனங்கள், நிலபுலன்கள் எல்லாம் வாங்குவார்.',
  'saturn+jupiter+rahu': 'ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.\n சொந்தத்தொழிலும் அமையலாம்.\n ஜாதகருக்கு கீழ்பல தொழிலாளர்கள் வேலை செய்வார்கள்.\n ஜாதகர் பேரும் புகழும் அடைவார்.\n தன் உத்யோகத்தில் உயர்ந்த நிலையை அடைவார்.\n எல்லோருடைய அன்பையும், ஆதரவையும், பெறுவார்.\n ஏராளமாக பணம் சம்பாதிப்பார்.\n வீடு, வாகனங்கள், சொத்துக்கள்.\n வாங்குவார்.',
  'saturn+jupiter+ketu': 'ஜாதகர் ஜோதிடம், ஆன்மீகம் சம்பந்தமான உத்யோகம் புரிவார்.\n ஜாதகருக்கு வாழ்க்கையில் குறிப்பாக உத்யோகத்தில் எந்தவித ஈடுபாடும் இருக்காது.',
  'saturn+venus+sun': 'ஜாதகருக்கு திருமணத்திற்கு பின் மனைவியால் யோகம் வரும்.\n ஜாதகர் அரசுதுறை வங்கியில் பணிபுரிபவராக இருப்பார்.\n அல்லது கணக்கர், வட்டித்தொழில் சொகுசு பொருட்கள் விற்பனை போன்ற தொழில்களில் ஏதாவது ஒன்றை செய்வார்.\n சொந்தமாக வீடு கட்டுவார்.\n வாகனங்கள் வாங்குவார்.\n எல்லா சுகபோகப் பொருட்களையும் அனுபவிப்பார்.',
  'saturn+venus+moon': 'ஜாதகர் சொகுசு பொருட்கள் அல்லது சுகந்த பொருட்கள் அல்லது சுவையான, இனிப்பான பண்டங்கள் போன்ற விற்பனையில் ஈடுபடுவார் அல்லது வட்டித்தொழில், அல்லது அரசுத்துறை வங்கியில் பணிபுரிவார்.\n ஜாதகருக்கு கணக்கில்லாமல் சொத்துக்கள் சேரும்.\n அவை எல்லாம் வீணாகவிரயமாகும்.',
  'saturn+venus+mars': 'ஜாதகர் கனரகவாகன தொழில் புரிவார், கட்டிடத் தொழில், சிவில் என்ஜீனியரிங், ஆர்கிடெக்சர்ஸ், பெரிய பெரிய தொழில்களை செய்வார்கள்.\n தொழிலுக்கு கடனும் நெருக்கடியும் இருக்கும்.',
  'saturn+venus+mercury': 'ஜாதகர் பணம், வங்கி, வணிகம், வணிகவரி சம்பந்தமான தொழில்களில் ஏதாவதொன்றில் ஈடுபடுவார்.\n சொந்தத்தொழிலும் அமையலாம்.\n ஜாதகருக்கு சொந்தமாக நிலபுலன்கள், சொத்துக்கள், வீடு வாகனங்கள் எல்லாம் அமையும்.',
  'saturn+venus+jupiter': 'ஜாதகர் அரசுத்துறை வங்கியில் மேலாளர் போன்ற உயர்ந்த பதவியில் இருக்கலாம் அல்லது பிறருக்கு ஆலோசனை வழங்குதல் சம்பந்தமான தொழில் செய்யலாம்.\n ஜாதகர் தன் உத்யோகத்தின் மூலம் பேரும், புகழும் அடைவார்.\n ஏராளமாகச் சம்பாதிப்பார்.\n வீடு, வாகனங்கள், நில புலன்கள் எல்லாம் வாங்குவார்.\n எல்லோருடைய அன்பையும், ஆதரவையும் பெறுவார்.',
  'saturn+venus+rahu': 'ஜாதகர் பங்கு சந்தையில் பணம் போட்டு ஏராளமாக பணம் சம்பாதிப்பார்.\n சட்டத்திற்கு புறம்பான வழிகளிலும் பணம் சம்பாதிப்பார்.\n தங்கும் விடுதி அல்லது உணவு விடுதி நடத்தலாம்.\n ஜாதகர் மிகப்பெரிய வீடுகளைக் கட்டுவார்.\n பல வாகனங்கள் வைத்திருப்பார்.',
  'saturn+venus+ketu': 'ஜாதகர் விமான ஓட்டியாகவோ அல்லது விமானத்துறையில் பணிபுரிவார்.\n உத்யோகத்தில் பிரச்சனைகள் உண்டாகும்.\n இதனால் வழக்குவிஷயங்களில் ஈடுபட நேரும்.',
  'saturn+rahu+sun': 'ஜாதகர் அடிமைத்தொழில் செய்வார்.\n சட்டத்திற்கு புறம்பான வழியில் பணம் சம்பாதிப்பார் அல்லது அரசுத்துறையில் கீழ்மட்ட நிலையில் பணிபுரிவார்.',
  'saturn+rahu+moon': 'ஜாதகர் சட்டத்திற்கு புறம்பான வழியில் பணம் சம்பாதிப்பார்.\n இதனால் உத்யோகத்தில் வீண்பழிமற்றும் அவமானம் உண்டாகும்.\n ஜாதகர், புகைப்படம் மற்றும் திரைப்படம் சம்பந்தமான துறைகளில் பணி புரியலாம்.\n கள்ளக்கடத்தலிலும் ஈடுபடுவார்.',
  'saturn+rahu+mars': 'ஜாதகர் அடிமைத்தொழில் செய்வார்.\n சமூக விரோதிகளின் தொடர்பால் தொழிலின் பல இன்னல்களைச் சந்திப்பார்.\n ஜாதகர் மிகப்பெரிய தொழிற்சாலையில் பணிபுரியும் நிலையும் ஏற்படலாம்.',
  'saturn+rahu+mercury': 'ஜாதகர் மிகப்பெரிய அளவில் வியாபாரம் செய்வார்.\n சட்டத்திற்கு புறம்பான வழியில் ஏராளமாகச் சம்பாதிப்பார்.',
  'saturn+rahu+jupiter': 'ஜாதகர் மிகப்பெரிய கௌரவமான உத்யோகத்தில் இருப்பார்.\n சொந்தத்தொழிலும் செய்யலாம்.\n ஜாதகருக்கு கீழ் பல தொழிலாளர்கள் பணிபுரிவார்கள்.\n ஏராளமாக பணம் சம்பாதிப்பார்.\n வீடு, வாகனங்கள் வாங்குவார்.',
  'saturn+rahu+venus': 'ஜாதகர் சட்டத்திற்கு புறம்பான வழியில் பணம் சம்பாதிப்பார்.\n பங்கு சந்தையில் பணம் போட்டும் பணம் சாம்பாதிப்பார்.\n ஜாதகர் மிகப்பெரிய வீடுகளைக் கட்டுவார்.\n பல வாகனங்கள்வைத்திருப்பார்.',
  'saturn+rahu+ketu': 'ஜாதகர் அடிமைத்தொழில் செய்வார் அல்லது சட்டத்திற்கு புறம்பான வழியில் பணம் சம்பாதிப்பார்.\n புகைப்படம், திரைப்படம்.\n பாதுகாப்புத்துறை, விமானத்துறை போன்றவற்றில் ஏதாவது ஒன்றில் பணிபுரிவார்.',
  'saturn+ketu+sun': 'ஜாதகருக்கும் அவன் தந்தைக்குமிடையே அடிக்கடி சண்டை சச்சரவுகள் ஏற்படும்.\n ஜாதகருக்கு உத்யோகத்தில் தடை அல்லது தொழிலில் முடக்கம் உண்டாகும்.\n அரசுத்துறை அதிகாரிகள் மற்றும் அரசியல்வாதிகளால் தொல்லை உண்டாகும்.',
  'saturn+ketu+moon': 'ஜாதகருக்கும் தாய்வழி உறவினர்களுக்குமிடையே அடிக்கடி சண்டை, சச்சரவுகள் உண்டாகும்.\n வழக்கு விஷயங்களில் ஈடுபட நேரிடும்.\n ஜாதகர் தாய் அல்லது மனைவியுடன் அடிக்கடி சண்டை போடுவார்.\n வாழ்க்கையில் வெறுப்பும்.\n ஏமாற்றமும் உண்டாகும்.\n ஜாதகர் ஒரு சன்யாசி போல் இருப்பார்.\n எதிரிகளால் தொல்லை உண்டாகும்.',
  'saturn+ketu+mars': 'சகோதரர்களுக்கிடையே அடிக்கடி சண்டைகள், சச்சரவுகள் உண்டாகும்.\n ஜாதகருக்கு எதிரிகளால் தொல்லை உண்டாகும்.\n சரியானதொழிலோ, உத்யோகமோ அமையாது.\n அப்படியே அமைந்தாலும் பல கஷ்டங்களையும், இன்னல்களையும் சந்திக்க நேரிடும்.\n உத்யோகத்தில் வெறுப்பும் ஏமாற்றமும் உண்டாகும்.\n எதிரிகள் தொல்லை கொடுத்துக்கொண்டே இருப்பார்கள்.',
  'saturn+ketu+mercury': 'ஜாதகர் தொழில்வகை கூட்டாளிகளுடன் கருத்து வேறுபாடு கொள்வார்.\n உத்யோகத்திலோ அல்லது தொழிலிலோ பல தடைகள் உண்டாகும்.\n வெறுப்பும் ஏமாற்றமும் உண்டாகும்.',
  'saturn+ketu+jupiter': 'ஜாதகருக்கு உத்யோகத்தில் கஷ்டங்கள் ஏற்படலாம்.\n சில பெரிய மனிதர்களின் உதவியால் பிரச்சனை சுமுகமாகும்.\n ஜாதகருக்கு உத்யோகத்தில் பிடிப்பு இருக்காது.',
  'saturn+ketu+venus': 'ஜாதகருக்கு உத்யோகத்தில் பிடிப்பு இருக்காது.\n ஜாதகர் தையல் தொழில், துணி வியாபாரம் போன்ற தொழில்களில் ஈடுபடுவார்.',
  'saturn+ketu+rahu': 'ஜாதகருக்கு உத்யோகத்தில் பிடிப்பு இருக்காது.\n ஒரு சன்யாசி போல் இருப்பார்.\n உத்யோகத்தில் தடைகளும் இன்னல்களும் ஏற்படும்.',
  'rahu+sun': 'ஜாதகரின் தகப்பனார் ரோகமுடையவராக இருப்பார்.\n ஜாதகரின் பாட்டனார் புகழை உடையவர்.\n ஆதிக்க குணம் உள்ளவர்.\n அரசியல் செல்வாக்கு உள்ளவர்.\n ஜாதகருக்கு கண்நோய் ஏற்படும்.',
  'rahu+moon': 'ஜாதகரின் தாய் ஆயுள் குறைவுடையவராக இருப்பார்.\n ஜாதகரின் இடக்கண் பாதிக்கப்படும்.\n ஜாதகரின் பாட்டனார் வேறிடத்திலிருந்து வந்து குடியேறியவர், சலனப்புத்தி உடையவர், மென்மையான குணம் கொண்டவர்.',
  'rahu+mars': 'ஜாதகரின் சகோதரன் நோய் உடையவராக இருப்பார்.\n ஜாதகருக்கு இரத்தம் மற்றும் எலும்பு சம்பந்தமான வியாதி இருக்கும்.\n ஜாதகரின்தந்தைவழி பாட்டனார் அகம்பாவம் மிக்கவர்.\n உடலில் பலகாயங்களைக் கொண்டவர், கோபக்காரர்.',
  'rahu+mercury': 'ஜாதகரின் மாமன் ரோகம் உடையவர்.\n ஜாதகருக்கு கல்வியில் தடை இருக்கும்.\n ஜாதகரின் பாட்டனார் புத்திசாலி, நகைச்சுவை உணர்வு மிக்கவர்.\n தோல் வியாதி உடையவர்.',
  'rahu+jupiter': 'ஜாதகருக்கு ஆயுள் குறைவு.\n வாயு சம்பந்தமான பிணி இருக்கும்.\n விகாரமான மூக்கை உடையவர்.\n சாஸ்திரங்களுக்குப் புறப்பானவர்.\n ஜாதகரின் பாட்டனார், ஆச்சாரமானவர், நேர்மையான குணத்தையுடையவர்.',
  'rahu+venus': 'ஜாதகரின் மனைவிக்கு ஆயுள் குறைவு.\n சோம்பல் நிறைந்தவர், பொய் பேசுவார்.\n ஜாதகரின் பாட்டனார் அழகிய மனைவியை உடையவர்.\n மனைவியால் நிறையச் சொத்து சேர்த்தவர்.',
  'rahu+saturn': 'நீச்சத்தொழில் செய்வார்.\n கள்ளக்கடத்தல் போன்ற சமுதாயத்திற்கு புறம்பான தொழில் செய்ய தயங்கமாட்டார்.\n ஜாதகரின்பாட்டனார் மந்தபுத்தியுடையவர், சோம்பேறி நிறையப் பாவங்கள் செய்தவர்.',
  'rahu+sun+moon': 'ஜாதகருடைய பெற்றோர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருடைய மகனுக்கு நீரில் கண்டமுண்டு.',
  'rahu+sun+mars': 'ஜாதகருடைய தந்தையாருக்கு எதிர்பாராத மரணம் ஏற்படும்.\n ஜாதகருடைய மகனுக்கு நெருப்பு மற்றும் வாகனங்களால் அபாயம் உண்டாகும்.',
  'rahu+sun+mercury': 'ஜாதகருடைய தந்தைக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருடைய கண்ணில் கருப்பு மச்சம் இருக்கும்.',
  'rahu+sun+jupiter': 'ஜாதகருக்கும் அவன் தந்தைக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகர் சிறைவாசம் அனுபவிக்க நேரிடலாம்.',
  'rahu+sun+venus': 'ஜாதகருக்கு புத்ரதோஷம் உண்டு.\n ஆண்குழந்தைகள் பிறப்பது கடினம்.\n ஜாதகருடைய தந்தைக்கும்.\n சகோதரிகளுக்கும் கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'rahu+sun+saturn': 'ஜாதகருடைய தந்தையாருக்கும்.\n மகனுக்கும் வாழ்க்கையில் கஷ்டங்களும், தடைகளும் ஏற்படும்.\n தந்தையாருக்கு அற்பஆயுள்.',
  'rahu+sun+ketu': 'ஜாதகருடைய தந்தையாருக்கு அற்ப ஆயுள்.\n ஆண் குழந்தைகளுக்கு பல கண்டங்களும், கஷ்டங்களும் ஏற்படும்.\n தந்தைக்கு விபத்தில் மரணமுண்டாகும்.',
  'rahu+moon+sun': 'ஜாதகருடைய பெற்றோர்களுக்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.',
  'rahu+moon+mars': 'ஜாதகருடைய தாய்க்கு எதிர்பாராத மரணம் ஏற்படும்.\n தாய்க்கு அற்ப ஆயுள்.\n ஜாதகர் குறுகிய மனப்பான்மையுடன் மனக்குழப்பம் மற்றும் தேவையில்லாத பயமுடையவர்.',
  'rahu+moon+mercury': 'ஜாதகருடைய தாய்க்கு கண்டங்கள், கஷ்டங்கள் ஏற்படும்.\n ஜாதகருக்கு வயிற்றில் கோளாறு உண்டு.\n தோல் வியாதியும் வரலாம்.\n செய்வினைத் தொல்லைகளினால் பயம் ஏற்படும்.',
  'rahu+moon+jupiter': 'ஜாதகருக்கு நீரில் கண்டம் உண்டு.\n நீர் சம்மந்தமான நோய்களும் வரும்.\n ஜாதகர் நீண்ட தூரப்பயணங்கள் செய்வார்.\n அயல்நாடு செல்லும் யோகமும் உண்டு.',
  'rahu+moon+venus': 'ஜாதகருடைய தாயும், மனைவியும் நோயாளியாக இருப்பார்கள்.\n தாய்க்கு பலவிதமான கஷ்டங்கள் ஏற்படும்.',
  'rahu+moon+saturn': 'தாய்க்கு அற்பஆயுள், தாய் அடிக்கடி நோய்வாய்ப்படுவார்.\n சோம்பேறியாக இருப்பார்.\n ஜாதகருக்கு வயிற்றில் கோளாறு உண்டு.\n ஜாதகர் மந்த புத்தியுள்ளவர்.',
  'rahu+moon+ketu': 'தாய்க்கு அற்பஆயுள், தாய் தெய்வபக்தியுள்ளவராக இருப்பார்.\n தாய்க்கு விபத்தில் மரணம் உண்டாகும்.',
  'rahu+mars+sun': 'ஜாதகருடைய தகப்பனார் மற்றும் சகோதரர்கள் பலவிதமான கஷ்டங்களை அனுபவிப்பார்கள்.',
  'rahu+mars+moon': 'ஜாதகர் மனசஞ்சலம் உடையவர்.\n தற்கொலை உணர்ச்சி உடையவர்.\n சகோதரர்கள் பலவிதமான கஷ்டங்களை அனுபவிப்பார்கள்.\n ஜாதகர் சிறுவிஷயங்களிலேயே கவனம் செலுத்திக் கொண்டு இருப்பார்.',
  'rahu+mars+mercury': 'குடும்பத்தில் ஒற்றுமை இருக்காது.\n சகோதரர்கள் பலவிதமான கஷ்டங்களை அனுபவிப்பார்கள்.',
  'rahu+mars+jupiter': 'ஜாதகருக்கு தீக்காயம் ஏற்பட வாய்ப்புள்ளது.\n ஜாதகர் பேசத்தெரியாமல் பேசி மாட்டிக்கொள்வார்.\n ஜாதகரின் பாட்டனார் இதய நோயுள்ளவர்.',
  'rahu+mars+venus': 'சகோதரனின் உயிர் ஆபத்தான நிலையில் சகோதரனுக்கு அற்ப ஆயுள்.\n சகோதரன் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.\n ஜாதகருடைய வலதுகண்ணில் ஒரு கருப்பு மச்சமிருக்கும்.',
  'rahu+mars+saturn': 'சகோதரனின் உயிருக்கு ஆபத்து வரும்.\n ஜாதகர் பெண்ணானால் கணவரின் உயிருக்கு ஆபத்து.',
  'rahu+mercury+sun': 'ஜாதகருடைய பாட்டனார் புத்திசாலி, நகைச்சுவை உணர்வு மிக்கவர்.\n தோல் வியாதி உடையவர்.\n ஜாதகரின் மாமன் ரோகம் உடையவர்.',
  'rahu+mercury+moon': 'ஜாதகருடைய இளைய சகோதரன் மனதில் குழப்பமுடையவர்.\n தேவையில்லாத பயமுடையவர்.\n ஜாதகருடைய இடதுகண்ணில் ஒரு கருப்பு மச்சமிருக்கும்.\n மந்திரவாதிகளால் தொல்லை உண்டாகும்.',
  'rahu+mercury+mars': 'சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n ஜாதகருடைய இளைய சகோதரனுக்கு நெருப்பு, வாகனம் மற்றும் ஆயுதங்களால் அபாயம் உண்டு.\n ஜாதகருடைய இமை பகுதியில் ஒரு கருப்பு மச்சமிருக்கும்.',
  'rahu+mercury+jupiter': 'ஜாதகருடைய மூக்கின்மீது ஒரு கருப்பு மச்சமிருக்கும்.\n ஜாதகர் அதிகப்படியான அறிவினால் மனம் குழம்பி போவார்.\n மனதில் தேவையில்லாத பயம் இருக்கும்.',
  'rahu+mercury+venus': 'ஜாதகர் தொழிலில் புதிய பலமுறைகளைப் புகுத்துவார்.\n சுகங்கள் அனுபவிக்கும்போதும் நூதன முறையைக் கடைபிடிப்பார்.',
  'rahu+mercury+saturn': 'ஜாதகர் மந்தபுத்தி உடையவர்.\n ஜாதகருடைய தாடையில் ஒரு கருப்பு மச்சமிருக்கும்.\n ஜாதகருடைய இளைய சகோதரன் சோம்பேறியாக இருப்பார்.',
  'rahu+mercury+ketu': 'ஜாதகருடைய இளைய சகோதரனுக்கு அற்பஆயுள்.\n இளைய சகோதரன் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.',
  'rahu+jupiter+sun': 'ஜாதகருக்கு நெருப்பினால் அபாயம் ஏற்படும்.\n ஜாதகர் புகழுடையவர்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n உஷ்ணசரீரத்தை உடையவர்.',
  'rahu+jupiter+moon': 'ஜாதகருக்கு நீரினால் அபாயம் ஏற்படும்.\n ஜாதகர் நீண்ட தூரப்பயணங்கள் செய்வார்.\n ஜாதகருக்கு அம்மை, வைசூரி போன்ற நோய்கள் வரும்.\n வயிற்றினும் பிணி உண்டு.\n ஜாதகர் பருத்த சரீரத்தை உடையவர்.',
  'rahu+jupiter+mars': 'ஜாதகருக்கு நெருப்பு, வாகனங்கள் மற்றும் ஆயுதங்களால் ஆபத்து உண்டு.\n ஜாதகர் குணங்கெட்டவராகவும், அகம்பாவம் மிக்கவராகவும் இருப்பார்.\n ஜாதகருக்கு பல்வரிசை சரியாக இருக்காது.\n ஜாதகருக்கு எதிர்பாராத மரணம் உண்டாகலாம்.\n இருதயம் மற்றும் ரத்தம் சம்பந்தமான வியாதி வரும்.',
  'rahu+jupiter+mercury': 'ஜாதகருக்கு மூக்கில் ஒரு கருப்பு மச்சம் இருக்கும்.\n ஜாதகர் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.\n ஜாதகர் புத்திசாலியாக இருப்பார்.',
  'rahu+jupiter+venus': 'ஜாதகருக்கும் அவன் மனைவிக்கும் பலவிதமான கஷ்டங்கள் ஏற்படும்.\n அடிக்கடி நோய் வாய்ப்படுவார்கள்.\n ஜாதகருக்கு அற்பஆயுள்.',
  'rahu+jupiter+saturn': 'ஜாதகர் சோம்பேறியாக இருப்பார்.\n ஜாதகருக்கு விஷ ஜந்துக்களால் அபாயம் உண்டு.\n வாயுக்கோளாறு மற்றும் வாத நோயால் துன்புறுவார்.',
  'rahu+jupiter+ketu': 'ஜாதகருக்கு அற்ப ஆயுள்.\n ஜாதகர் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.\n ஜாதகருக்கு விபத்தினால் மரணம் உண்டாகும்.',
  'rahu+venus+sun': 'ஜாதகருடைய மனைவிக்கு நெருப்பில் அபாயம் உண்டு.\n புத்ரதோஷம் உண்டு.\n மனைவி மனதில் குழப்பமுடையவர்.\n ஏவல், பில்லி, சூன்யம் முதலியவற்றால் பாதிக்கப்படுவார்.',
  'rahu+venus+moon': 'ஜாதகருடைய மனைவிக்கு நீரில் கண்டமுண்டு.\n மனைவி பருத்த சரீரத்தை உடையவர்.\n பெரிய விழிகளை உடையவர்.\n கணவனை சந்தேகிப்பார்.\n எப்பொழுதும் மனதில் பயத்துடனேயே இருப்பார்.\n மனநிலை சரியாக இருக்காது.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n கருப்பையில் கோளாறு உடையவர்.\n கருச்சிதைவு உண்டாகும்.\n ஏவல், பில்லி, சூன்யம் முதலியவற்றால் பாதிக்கப்படுவார்.',
  'rahu+venus+mars': 'ஜாதகருடைய மனைவிக்கு நெருப்பில் அபாயம் உண்டு.\n குணங்கெட்டவராக இருப்பார்.\n கணவனை மதிக்கமாட்டார்.\n கணவனை வெறுப்பார்.',
  'rahu+venus+mercury': 'ஜாதகருக்கு கன்னத்தில் ஒரு கருப்பு மச்சம் இருக்கும்.\n மனைவி மனதில் குழப்பமுடையவர்.\n மனதில் பயம் நிரம்பி இருக்கும்.',
  'rahu+venus+jupiter': 'ஜாதகர் வித்யாசமான முறையில் சுகம் அனுபவிப்பார்.\n ஜாதகர் மனைவி ஒற்றுமையாக இருப்பார்கள்.\n ஆனால் ஒரே நாளில் இறக்கவும் வாய்ப்புள்ளது.',
  'rahu+venus+saturn': 'மனைவி சொந்த வருமானமுள்ளவர்.\n சோம்பேறியாக இருப்பார்.\n செல்வ செழிப்புள்ள குடும்பத்திலிருந்து வருவார்.\n பெரியமாடி வீட்டில் குடியிருப்பார்.',
  'rahu+venus+ketu': 'மனைவிக்கு அற்ப ஆயுள், மனைவி பலவிதமான கஷ்டங்கள் அனுபவிப்பார்.\n மனைவிக்கு விபத்தினால் மரணம் உண்டாகும்.',
  'rahu+saturn+sun': 'ஜாதகருக்கு நெருப்பில் அபாயம் உண்டு.\n குடும்பத்தில் ஒற்றுமை இருக்காது.\n தந்தை மகனுக்கிடையே பிரிவு உண்டாகும்.',
  'rahu+saturn+moon': 'ஜாதகருக்கு நீரில் கண்டம் உண்டு.\n ஜாதகர் நீண்ட தூரப்பயணங்கள் செய்வார்.\n அயல்நாடு செல்லும் யோகமும் உண்டு.\n ஜாதகர் சோம்பேறியாக இருப்பார்.\n ஜாதகர் மந்தபுத்தி உடையவர்.\n வயிற்றில் பிணி உடையவர்.',
  'rahu+saturn+mars': 'ஜாதகருக்கு நெருப்பு, வாகனங்கள் மற்ற ஆயுதங்களால் அபாயம் ஏற்படும்.\n ஜாதகருக்கு பல்வரிசை நன்றாக இருக்காது.\n பல்லில் ரோகமுடையவர்.\n ஜாதகர் தொழில் வகையில் பல கஷ்டங்களை அனுபவிப்பார்.\n மூத்த சகோதரனுக்கு விபத்தில் மரணம் உண்டாகும்.',
  'rahu+saturn+mercury': 'ஜாதகர் அதிபுத்திசாலித்தனத்தால் கஷ்டப்படுவார்.\n சட்டத்திற்கு புறம்பான வழியில் பணம் சம்பாதிப்பார்.\n ஜாதகருடைய தாடையில் ஒரு கருப்பு மச்சமிருக்கும்.',
  'rahu+saturn+jupiter': 'ஜாதகருக்கு கௌரமான உத்யோகம் அமையும்.\n தொழிலில் பல ஊழல்கள், ஏமாற்று வேலை செய்யத் தயங்காதவர்.\n வாயுக் கோளாறு மற்றும் வாதநோயால் கஷ்டப்படுவார்.',
  'rahu+saturn+venus': 'ஜாதகர் சட்டத்திற்கு புறம்பான வழியில் பணம் சேர்த்து வைப்பார்.\n மனைவி சுறுசுறுப்பாக இருக்க மாட்டார்.',
  'rahu+saturn+ketu': 'ஜாதகர் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.\n யாருடைய உதவியும் கிடைக்காது.\n ஜாதகர் அற்ப ஆயுளுடையவர்.\n விபத்தில் மரணம் உண்டாகும்.',
  'ketu+sun': 'ஜாதகர் தந்தையுடன் கருத்து வேறுபாடு கொண்டவர்.\n கண் நோய் மற்றும் மலட்டுத்தன்மை ஏற்படும்.\n ஜாதகரின் பாட்டனார் புகழ்மிக்கவர்.\n அரசாங்கத்தில் நல்ல செல்வாக்கு உள்ளவர்.',
  'ketu+moon': 'ஜாதகர் தாயுடன் கருத்து வேறுபாடு கொண்டவர்.\n மனவியாதி ஏற்படவாய்ப்புள்ளது.\n ஆன்மீகத்தில் நாட்டமுடையவர், மென்மையானவர்.',
  'ketu+mars': 'ஜாதகர் சகோதரர்களுடன் அடிக்கடி சண்டை இடுவார்.\n விகாரமான பல் கொண்டவர்.\n இரத்தசோகை, மூலவியாதி, புற்றுநோய், குடல் இறக்கம், இரத்த ஓட்டத்தில் தடை ஏற்படலாம்.\n பெண் என்றால் கணவனுடன் கருத்துவேறுபாடு கொள்பவர்.\n ஜாதகரின் பாட்டனார் தைர்யமானவர்.\n வேகம் மிகுந்தவர், கடுஞ்சொல் உடையவர்.',
  'ketu+mercury': 'ஜாதகர் நண்பர்களுடன் காரசாரமாக விவாதித்து சண்டை இடுவார்.\n தோல் வியாதியும் காதில் நோயும் உடையவர்.\n ஜாதகரின்பாட்டனார் புத்திசாலி, கற்பதில் ஆர்வம் உடையவர்.',
  'ketu+jupiter': 'ஜாதகர் யாருடனும் ஒத்துப்போக மாட்டார்.\n நரம்புத்தளர்ச்சி ஏற்படும்.\n ஆண்மைக்குறைவு.\n சோம்பேறித்தனம், ஆகியவை கொண்டவர்.\n ஜாதகரின் பாட்டனார் பிறருக்கு வழிகாட்டியாக இருப்பவர்.\n ஆச்சாரமானவர், பக்திமான்.',
  'ketu+venus': 'ஜாதகர் மனைவியைப் பிரியும் வாய்ப்பு உள்ளது.\n குடும்ப வாழ்க்கை நன்றாக இராது.\n கருப்பையில் அடைப்பு அல்லது மலட்டுத்தன்மை ஏற்படும்.\n ஜாதகரின் பாட்டனார் மனைவி சொல்படி நடப்பவர்.\n கலைகளில் ஆர்வம் உடையவர்.',
  'ketu+saturn': 'தொழிலில் எப்போதும் தடை இருக்கும்.\n தொழில் செய்ய நாட்டம் இருக்காது.\n நரம்புத்தளர்ச்சி, புத்தி சுவாதீனமின்மை ஏற்படவாய்ப்புள்ளது.\n ஜாதகர் எந்த தொழில் செய்தாலும் தடங்கல்களைச் சந்திப்பார்.',
  'ketu+sun+moon': 'பெற்றோர்கள் கஷ்டநிலையில் இருப்பார்கள்.\n பூர்வீகச்சொத்து சம்பந்தமாக குடும்பத்தில் தகராறு இருக்கும்.\n தந்தையார் தெய்வபக்தியுடையவர்.',
  'ketu+sun+mars': 'பெற்றோர்கள் கஷ்டநிலையில் இருப்பார்கள்.\n பூர்வீகச்சொத்து சம்பந்தமாக குடும்பத்தில் தகராறு இருக்கும்.\n தந்தையார் முன்கோபியாக இருப்பார்.\n ஜாதகருக்கு மூல வியாதி இருக்கும்.\n திருமணத்தில் தடையுண்டு.',
  'ketu+sun+mercury': 'பூர்வீகச்சொத்து சம்பந்தமாக குடும்பத்தில் தகராறு இருக்கும்.\n நிலம் சம்பந்தமான வகையில் தகராறு இருக்கும்.\n இது காரணமாக நீதிமன்றம் செல்ல நேரிடும்.',
  'ketu+sun+jupiter': 'தந்தை மகனுக்கிடையே தகராறு இருக்கும்.\n தந்தையார் தெய்வ பக்தியுடையவர்.',
  'ketu+sun+venus': 'பூர்வீகச்சொத்து அல்லது பணம் விஷயமாக குடும்பத்தில் தகராறு வரும்.\n ஜாதகருக்கு புத்ரதோஷம் உண்டு.',
  'ketu+sun+saturn': 'ஜாதகருக்கு ஆண் வாரிசு தங்காது.\n ஜாதகருடைய தகப்பானருக்கு அற்ப ஆயுள்.\n விபத்தினால் மரணம் உண்டாகும்.\n ஆண்குழந்தைகள் இளம் வயதிலேயே மரிப்பார்கள்.',
  'ketu+sun+rahu': 'தந்தையாருக்கு அற்ப ஆயுள்.\n எதிர்பாராத வகையில், விபத்தில் மரணம் உண்டாகும்.\n ஜாதகருடைய ஆண்வாரிசு தங்காது.',
  'ketu+moon+sun': 'பெற்றோர்கள் கஷ்டநிலையில் இருப்பார்கள்.\n ஜாதகருக்கு தன் ஆண்வாரிசு குறித்து மனக்கவலை இருக்கும்.\n ஜாதகருடைய தாயார் முன்கோபியாக இருப்பார்.',
  'ketu+moon+mars': 'ஜாதகருக்கு தன் சகோதரன் குறித்து மனக்கவலையிருக்கும்.\n ஜாதகருடைய தாயார் முன்கோபியாக இருப்பார்.\n குடும்பத்தில் நிலம் சம்பந்தமாக தகராறு இருக்கும்.\n திருமணத்தில் தடையுண்டு.',
  'ketu+moon+mercury': 'ஜாதகருக்கு தன் இளைய சகோதரன் குறித்து மனக்கவலை இருக்கும்.\n குடும்பத்தில் நிலம், பூமி சம்பந்தமாக தகராறு இருக்கும்.\n ஜாதகர் காதல் விவகாரத்தில் ஈடுபட்டு வீண்பழி உண்டு.',
  'ketu+moon+jupiter': 'ஜாதகர் ஆன்மீகத்தில் ஈடுபாடு உடையவனாக இருப்பார்.\n வாழ்க்கையில் பிடிப்பில்லாமல் இருப்பார்.\n ஜாதகருடைய தாயார் தெய்வபக்தி உடையவர்.',
  'ketu+moon+venus': 'ஜாதகர் தன் மனைவி குறித்து மனக்கவலை கொண்டிருப்பார்.\n தாயார் நோயாளியாக இருப்பார்.\n குடும்பத்தில் சொத்து மற்றும் பணம் சம்பந்தமாக தகராறு இருக்கும்.',
  'ketu+moon+saturn': 'ஜாதகர் தன் உத்யோகம் சம்பந்தமாக மனக்கவலை கொண்டிருப்பார்.\n தாயார் சோம்பேறியாக இருப்பார்.\n அடிக்கடி நோய்வாய்ப்படுவார்.\n தாயாருக்கு அற்பஆயுள்.\n எதிர்பாராத மரணம் உண்டாகும்.',
  'ketu+moon+rahu': 'தாயாருக்கு அற்பஆயுள்.\n எதிர்பாராத மரணம் உண்டாகும்.\n தாயார் பலவிதமான கஷ்டங்களை அனுபவிப்பார்.',
  'ketu+mars+sun': 'ஜாதகருடைய சகோதரன் முன்கோபியாக இருப்பார்.\n பூர்வீகச்சொத்து சம்பந்தமாக குடும்பத்தில் தகராறு இருக்கும்.\n ஜாதகருக்கு மூலவியாதி இருக்கும்.\n ஜாதகருக்கு திருமணத்தில் தடையுண்டு.',
  'ketu+mars+moon': 'ஜாதகர் தன் சகோதரன் குறித்து மனக்கவலை கொண்டிருப்பார்.\n ஜாதகருக்கு மூலவியாதி இருக்கும்.\n சகோதரன் சலனப்புத்தியுடையவராக இருப்பார்.\n திருமணத்தில் தடையுண்டு.',
  'ketu+mars+mercury': 'குடும்பத்தில் சகோதரர்களுக்கிடையே அடிக்கடி சண்டை, சச்சரவுகள் உண்டாகும்.\n நிலம், பூமி சம்பந்தமாக குடும்பத்தில் தகராறு ஏற்படும்.\n திருமணத்தில் தடையுண்டு.\n காதலில் தோல்வியுண்டு.\n நிலம் சம்பந்தமான வழக்கிலும் தோல்வி உண்டாகும்.',
  'ketu+mars+jupiter': 'ஜாதகருடைய சகோதரன் ஆன்மீகத்தில் ஈடுபாடு உடையவர்.\n ஜாதகருக்கு மூலவியாதி உண்டு.\n திருமணத்தில் தடையுண்டு.\n தடைகள்யாவும் தெய்வ அருளால் நீங்கும்.',
  'ketu+mars+venus': 'சொத்து மற்றும் திருமணம் சம்பந்தமாக குடும்பத்தில் தகராறு இருக்கும்.\n கணவன் மனைவியருக்கிடையே கருத்து வேறுபாடு உண்டாகும்.\n திருமணத்தில் தடையுண்டு.',
  'ketu+mars+saturn': 'ஜாதகருடைய சகோதரன் கஷ்டநிலையில் இருப்பார்.\n ஜாதகருக்கு திருமணத்தில் தடை உண்டு.\n உத்யோகத்திலும் பலவிதமான தடைகளும், கஷ்டங்களும் உண்டாகும்.\n ஜாதகர் பணி நீக்கம் செய்யப்படலாம்.\n சகோதரனுக்கு அற்ப ஆயுள்.',
  'ketu+mars+rahu': 'சகோதரனுக்கு அற்ப ஆயுள்.\n எதிர்பாராதவிதமாக மரணம் உண்டாகும்.',
  'ketu+mercury+sun': 'குடும்பத்தில் பூர்வீகச்சொத்து சம்பந்தமாக தகராறு ஏற்படும்.',
  'ketu+mercury+moon': 'குடும்பத்தில் நிலம், பூமி, சம்பந்தமாக தகராறு ஏற்படும்.\n ஜாதகர் காதல் விவகாரத்தில் ஈடுபட்டு வீண்பழிக்கு உள்ளாக நேரிடும்.\n ஜாதகனுக்கு தோல்வியாதி உண்டு.',
  'ketu+mercury+mars': 'சகோதரர்களுக்கிடையே ஒற்றுமை இருக்காது.\n நிலம், பூமி சம்பந்தமாக குடும்பத்தில் தகராறு உண்டாகும்.\n ஜாதகர் காதலில் தோல்வி அடைவார்.\n நிலம் சம்பந்தமாக வழக்கிலும் தோல்வி உண்டாகும்.',
  'ketu+mercury+jupiter': 'ஜாதகர் காதலில் வெற்றி அடைவார்.\n நிலம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.',
  'ketu+mercury+venus': 'ஜாதகர் காதலில் வெற்றி அடைவார்.\n நிலம், பூமி மற்றும் பணம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.',
  'ketu+mercury+saturn': 'ஜாதகர் காதலில் வெற்றி அடைவார்.\n உத்யோகம் சம்பந்தமான வழக்கில் வெற்றி அடைவார்.\n நிலம் சம்பந்தமான வழக்கிலும் வெற்றி அடைவார்.',
  'ketu+mercury+rahu': 'ஜாதகருடைய இளைய சகோதரனுக்கு அற்பஆயுள்.\n எதிர்பாராதவிதமாக மரணம் ஏற்படும்.',
  'ketu+jupiter+sun': 'ஜாதகர் முன்கோபியாக இருப்பார்.\n வைராக்யமுள்ளவர்.\n உடலில் அதிக உஷ்ணம் சம்பந்தமான வியாதிகள் வரும்.\n ஜாதகர் அவன் தந்தைக்கு முதல் குழந்தையாகும்.',
  'ketu+jupiter+moon': 'ஜாதகர் பருத்த சரீரத்தையுடையவர்.\n ஆன்மீகத்தில் ஈடுபாடு உடையவர்.\n பிறந்த இடம் விட்டு வேறு இடத்தில் குடியேறுவார்.',
  'ketu+jupiter+mars': 'ஜாதகர் பிடிவாத குணமுள்ளவர்.\n வைராக்யமுள்ளவர்.\n ஜாதகருக்கு மூலவியாதி உண்டு.\n ஜாதகருக்கு ஆன்மீகத்தில் ஈடுபாடு இருக்கும்.',
  'ketu+jupiter+mercury': 'ஜாதகருக்கு காதலில் வெற்றியுண்டாகும்.\n ஜாதகர் வேதபாடங்களைக் கற்றறிவார்.\n ஜாதகருக்கு அழகான மீசையிருக்கும்.\n நிலம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.\n ஜாதகர் இளமையான தோற்றமுடையவர்.',
  'ketu+jupiter+venus': 'சொத்துக்கள் மற்றும் பணம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.\n ஜாதகர் அழகான தோற்றமுடையவர்.',
  'ketu+jupiter+saturn': 'உத்யோகம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.\n ஜாதகர் ஆன்மீகத்தில் ஈடுபாடு உடையவர்.',
  'ketu+jupiter+rahu': 'ஜாதகருக்கு அற்ப ஆயுள்.\n எதிர்பாராதவகையில் மரணம் உண்டாகும்.',
  'ketu+venus+sun': 'புத்ரதோஷம் உண்டு.\n பூர்வீகச்சொத்து சம்பந்தமாக குடும்பத்தில் தகராறு ஏற்படும்.\n மனைவி அதிகாரத்தோரணைஉடையவர்.',
  'ketu+venus+moon': 'மனைவி பருத்த சரீரத்தை உடையவர்.\n நோயாளியாக இருப்பார்.\n மர்ம உறுப்பில் நோயுடையவர்.\n பெரிய கண்களை உடையவர்.\n கணவன் மீது சந்தேகப்படுவார்.\n மனைவிக்கு கருச்சிதைவு உண்டாகும்.',
  'ketu+venus+mars': 'கணவன் மனைவியருக்கிடையே கருத்து வேறுபாடு உண்டாகும்.\n குடும்பத்தில் பிரிவும் ஏற்படலாம்.',
  'ketu+venus+mercury': 'காதலில் வெற்றி, நிலம், சொத்து சம்பந்தமான வழக்குகளில் வெற்றியுண்டாகும்.\n மனைவிக்கு பிடித்தவராக இருப்பார்.',
  'ketu+venus+jupiter': 'சொத்து மற்றும் பணம் சம்பந்தமான வழக்குகளில் வெற்றி உண்டாகும்.\n மனைவி தெய்வ பக்தியுடையவர்.',
  'ketu+venus+saturn': 'உத்யோகம் மற்றும் பணம் சம்பந்தமான வழக்குகளில் வெற்றியுண்டாகும்.\n மனைவி வருமானமுள்ளவராக இருப்பார்.',
  'ketu+venus+rahu': 'மனைவிக்கு அற்ப ஆயுள்.\n எதிர்பாராதவிதமாக மரணம் உண்டாகும்.',
  'ketu+saturn+sun': 'உத்யோகத்தில் பல தடைகளும், கஷ்டங்களும் ஏற்படும்.\n அரசாங்கம் மற்றும் மேலதிகாரியிடம் மோதல் போக்கு இருக்கும்.',
  'ketu+saturn+moon': 'உத்யோகம் சம்பந்தமாக வீண்பழிகெட்டபெயர் உண்டாகும்.',
  'ketu+saturn+mars': 'உத்யோகத்தில் பல தடைகளும், கஷ்டங்களும் ஏற்படும்.\n ஜாதகர் உத்யோகத்திலிருந்து பணிநீக்கம் செய்யப்படுவார்.',
  'ketu+saturn+mercury': 'உத்யோகம் மற்றும் நிலம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.\n காதலில் வெற்றி உண்டாகும்.',
  'ketu+saturn+jupiter': 'உத்யோகம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.\n ஜாதகருக்கு கௌரவமான உத்யோகம் அமையும்.',
  'ketu+saturn+venus': 'உத்யோகம் மற்றும் பணம் சம்பந்தமான வழக்கில் வெற்றி உண்டாகும்.',
  'ketu+saturn+rahu': 'ஜாதகருக்கு அற்ப ஆயுள் எதிர்பாராத விதமாக மரணம் உண்டாகும்.\n தெய்வபக்தி உள்ளவர்.\n சோம்பேறியாக இருப்பார்.\n விரக்தியுடையவர்.',
